-- ══════════════════════════════════════════════════════════════════════════
-- 0003_views.sql
-- ══════════════════════════════════════════════════════════════════════════

-- ═══════════════════════════════════════════════════════════════════════════
-- Funnel OS — the 29 metrics.
--
-- Every view is the same spine with different columns, so the metric maths lives
-- in ONE function and each view only decides how to cut the data.
--
-- The two rules the PRD calls out are encoded here and nowhere else:
--
--   BLANK vs ZERO   a cut with no ads_performance rows has no spend, so spend,
--                   reach, frequency, impressions, clicks, CTR, lead-gen, every
--                   CP* and every ROAS return NULL — not 0. A class doesn't buy
--                   traffic; the round does. Organic has no spend. Not zero,
--                   not infinite — absent.
--
--   ZERO-DENOM      every ratio divides by NULLIF(denominator, 0), so a missing
--                   denominator renders '—' instead of 0%, and never #DIV/0!.
--
-- The frontend receives NULL and prints '—'. It never decides which is which.
-- ═══════════════════════════════════════════════════════════════════════════

drop function if exists fo_metrics cascade;

-- Parameters are p_-prefixed deliberately: inside a SQL function body, a column
-- name from the FROM clause outranks a same-named parameter, so a parameter
-- called `spend` would be silently shadowed by the blanked `spend` column (or
-- worse, the other way round) and blank-vs-zero would stop working.
create or replace function fo_metrics(
  p_has_ads           boolean,          -- does this cut have ANY ads_performance rows?
  p_spend             numeric,
  p_reach             bigint,
  p_impressions       bigint,
  p_clicks            bigint,
  p_leads             bigint,
  p_attendance        bigint,
  p_preview_purchases bigint,
  p_middle_purchases  bigint,
  p_preview_revenue   numeric,
  p_middle_revenue    numeric,
  p_preview_price     numeric,          -- configured unit price, from client_journey_config
  p_middle_price      numeric
) returns jsonb
language sql
immutable
as $$
  with m as (
    select
      -- blank-vs-zero: no ads rows for this cut => the ads metrics do not exist
      case when p_has_ads then p_spend       end as spend,
      case when p_has_ads then p_reach       end as reach,
      case when p_has_ads then p_impressions end as impressions,
      case when p_has_ads then p_clicks      end as clicks,
      coalesce(p_leads, 0)             as leads,
      coalesce(p_attendance, 0)        as attendance,
      coalesce(p_preview_purchases, 0) as prev_buy,
      coalesce(p_middle_purchases, 0)  as mid_buy,
      coalesce(p_preview_revenue, 0)   as prev_rev,
      coalesce(p_middle_revenue, 0)    as mid_rev
  )
  select jsonb_build_object(
    -- ── METRICS (1–14) ────────────────────────────────────────────────────
    'spend',      spend,
    'reach',      reach,
    'freq',       impressions::numeric / nullif(reach, 0),
    'impr',       impressions,
    'clicks',     clicks,
    'leads',      leads,
    'att',        attendance,
    'prevBuy',    prev_buy,
    'midBuy',     mid_buy,
    'prevRev',    prev_rev,
    'midRev',     mid_rev,
    -- selling price is the configured unit price, shown only where the cut
    -- actually has purchases of that product ('—' otherwise, per the mockup)
    'prevPrice',  case when prev_buy > 0 then p_preview_price end,
    'midPrice',   case when mid_buy  > 0 then p_middle_price  end,
    'rev',        prev_rev + mid_rev,

    -- ── FUNNEL METRICS (15–19) ────────────────────────────────────────────
    'ctr',        clicks::numeric  * 100 / nullif(impressions, 0),
    'leadgen',    leads::numeric   * 100 / nullif(clicks, 0),
    'attPct',     attendance::numeric * 100 / nullif(leads, 0),
    'prevPct',    prev_buy::numeric   * 100 / nullif(attendance, 0),
    'midPct',     mid_buy::numeric    * 100 / nullif(prev_buy, 0),

    -- ── UNIT OF ECONOMICS (20–29) ─────────────────────────────────────────
    'cpm',        spend * 1000 / nullif(impressions, 0),
    'cpc',        spend / nullif(clicks, 0),
    'cpl',        spend / nullif(leads, 0),
    'cpAtt',      spend / nullif(attendance, 0),
    -- CPA is cost per *acquired customer*, and the mockup measures that against
    -- preview purchases (12,897.14 / 39 = 330.70), not preview+middle. The middle
    -- offer is sold to people already acquired by the preview.
    'cpa',        spend / nullif(prev_buy, 0),
    'prevAov',    prev_rev / nullif(prev_buy, 0),
    'prevRoas',   prev_rev / nullif(spend, 0),
    'midAov',     mid_rev / nullif(mid_buy, 0),
    'midRoas',    mid_rev / nullif(spend, 0),
    'roas',       (prev_rev + mid_rev) / nullif(spend, 0)
  )
  from m;
$$;

-- ═══════════════════════════════════════════════════════════════════════════
-- Building blocks
-- ═══════════════════════════════════════════════════════════════════════════

-- Configured unit prices, one row per client.
-- A journey whose purchase stage is 'checkout' rather than 'preview' (ecommerce)
-- still records its sales as product = 'preview' — the first purchase in the
-- journey — so the checkout price stands in as the preview price for that client.
create or replace view v_client_prices as
select
  client_id,
  coalesce(
    max(unit_price) filter (where stage_slug = 'preview'),
    max(unit_price) filter (where stage_slug = 'checkout')
  ) as preview_price,
  max(unit_price) filter (where stage_slug = 'middle')   as middle_price,
  max(unit_price) filter (where stage_slug = 'checkout') as checkout_price
from client_journey_config
group by client_id;

-- Clients, for the switcher. Derived from the journey config — client is a
-- dimension, and the journey is what makes a client real to this app.
--
-- Ordered by how much history each client has, so the app opens on the account
-- with something to look at rather than on whichever name sorts first.
create or replace view v_clients as
select
  j.client_id,
  min(j.client_name)        as client_name,
  min(j.client_note)        as client_note,
  count(*)                  as stage_count,
  coalesce(r.round_count, 0) as round_count
from client_journey_config j
left join (
  select client_id, count(*) as round_count from rounds group by client_id
) r on r.client_id = j.client_id
group by j.client_id, r.round_count
order by coalesce(r.round_count, 0) desc, j.client_id;

-- Journey stages, in order. Drives the Customer Journey strip AND the Compare nav
-- group — change a client's journey and the views change with it.
create or replace view v_journey as
select
  client_id, stage_order, stage_name, stage_slug,
  compare_dimension, stage_metric, stage_rate_label, unit_price
from client_journey_config
order by client_id, stage_order;

-- Every ads_performance row with its client attached (ads_performance scopes
-- through round_id — there's no client_id on the table).
create or replace view v_ads as
select r.client_id, a.*
from ads_performance a
join rounds r on r.round_id = a.round_id;

-- Every event with its client, plus the derived attribution bucket.
--
-- "Previous Paid Ads" is not a source. It's the sales where the round that
-- produced the lead isn't the round whose class closed it — AND the source is
-- Paid Ads. An Organic lead from August buying in October is still Organic.
create or replace view v_events as
select
  r.client_id,
  e.*,
  case
    when e.source = 'Paid Ads'
     and coalesce(e.close_round_id, e.round_id) is distinct from e.lead_round_id
      then 'Previous Paid Ads'
    else e.source
  end as attribution_bucket
from events e
join rounds r on r.round_id = e.round_id;

-- ═══════════════════════════════════════════════════════════════════════════
-- BY ROUND  — Overview / By round     (fully wired)
--
-- Note the deliberate asymmetry, straight from the schema doc:
--   leads + attendance are counted on round_id      — whose class was this?
--   revenue + purchases are counted on lead_round_id — whose spend produced it?
-- So a lead from 0526-02 who attends 0526-03's class and buys there is counted
-- in 0526-03's attendance and in 0526-02's revenue. Both true, same total.
-- ═══════════════════════════════════════════════════════════════════════════
create or replace view v_metrics_by_round as
with ads as (
  select client_id, round_id,
         sum(spend) as spend, sum(reach) as reach,
         sum(impressions) as impressions, sum(clicks) as clicks,
         count(*) as ad_rows
  from v_ads group by client_id, round_id
),
ev as (
  select client_id, round_id,
         count(*) filter (where event_type = 'lead')       as leads,
         count(*) filter (where event_type = 'attendance') as attendance
  from v_events group by client_id, round_id
),
sales as (
  select client_id, lead_round_id as round_id,
         count(*) filter (where product = 'preview')                     as prev_buy,
         count(*) filter (where product = 'middle')                      as mid_buy,
         sum(amount - coalesce(refund_amount, 0)) filter (where product = 'preview') as prev_rev,
         sum(amount - coalesce(refund_amount, 0)) filter (where product = 'middle')  as mid_rev
  from v_events where event_type = 'sale' and lead_round_id is not null
  group by client_id, lead_round_id
)
select
  r.client_id,
  r.round_id                                  as cut_key,
  r.round_id                                  as cut_label,
  to_char(r.start_date, 'Mon DD') || ' – ' || to_char(r.end_date, 'DD') as cut_sub,
  r.start_date,
  fo_metrics(
    coalesce(ads.ad_rows, 0) > 0,
    ads.spend, ads.reach, ads.impressions, ads.clicks,
    ev.leads, ev.attendance,
    sales.prev_buy, sales.mid_buy, sales.prev_rev, sales.mid_rev,
    p.preview_price, p.middle_price
  ) as m
from rounds r
left join ads   on ads.client_id = r.client_id and ads.round_id = r.round_id
left join ev    on ev.client_id  = r.client_id and ev.round_id  = r.round_id
left join sales on sales.client_id = r.client_id and sales.round_id = r.round_id
left join v_client_prices p on p.client_id = r.client_id
order by r.client_id, r.start_date;

-- ═══════════════════════════════════════════════════════════════════════════
-- TARGETED VIEWS  — Compare / Targeted views     (fully wired)
--
-- The bridge is events.utm_campaign -> ads_performance.ad_set: the audience the
-- lead came from. People with no utm (organic, previous-round) have no audience,
-- so they land in the client total but in none of the audience columns — which
-- is exactly right, they cost nothing.
-- ═══════════════════════════════════════════════════════════════════════════
create or replace view v_metrics_by_adset as
with ads as (
  select client_id, ad_set,
         sum(spend) as spend, sum(reach) as reach,
         sum(impressions) as impressions, sum(clicks) as clicks,
         count(*) as ad_rows
  from v_ads where ad_set is not null group by client_id, ad_set
),
ev as (
  select client_id, utm_campaign as ad_set,
         count(*) filter (where event_type = 'lead')       as leads,
         count(*) filter (where event_type = 'attendance') as attendance,
         count(*) filter (where event_type = 'sale' and product = 'preview') as prev_buy,
         count(*) filter (where event_type = 'sale' and product = 'middle')  as mid_buy,
         sum(amount - coalesce(refund_amount, 0)) filter (where event_type = 'sale' and product = 'preview') as prev_rev,
         sum(amount - coalesce(refund_amount, 0)) filter (where event_type = 'sale' and product = 'middle')  as mid_rev
  from v_events where utm_campaign is not null group by client_id, utm_campaign
)
select
  coalesce(ads.client_id, ev.client_id) as client_id,
  coalesce(ads.ad_set, ev.ad_set)       as cut_key,
  coalesce(ads.ad_set, ev.ad_set)       as cut_label,
  null::text                            as cut_sub,
  fo_metrics(
    coalesce(ads.ad_rows, 0) > 0,
    ads.spend, ads.reach, ads.impressions, ads.clicks,
    ev.leads, ev.attendance,
    ev.prev_buy, ev.mid_buy, ev.prev_rev, ev.mid_rev,
    p.preview_price, p.middle_price
  ) as m,
  coalesce(ads.spend, 0) as sort_spend
from ads
full join ev on ev.client_id = ads.client_id and ev.ad_set = ads.ad_set
left join v_client_prices p on p.client_id = coalesce(ads.client_id, ev.client_id)
order by 1, sort_spend desc;

-- ═══════════════════════════════════════════════════════════════════════════
-- CLIENT TOTAL — the "Total" column that leads every comparison view
-- ═══════════════════════════════════════════════════════════════════════════
create or replace view v_metrics_total as
with ads as (
  select client_id, sum(spend) as spend, sum(reach) as reach,
         sum(impressions) as impressions, sum(clicks) as clicks, count(*) as ad_rows
  from v_ads group by client_id
),
ev as (
  select client_id,
         count(*) filter (where event_type = 'lead')       as leads,
         count(*) filter (where event_type = 'attendance') as attendance,
         count(*) filter (where event_type = 'sale' and product = 'preview') as prev_buy,
         count(*) filter (where event_type = 'sale' and product = 'middle')  as mid_buy,
         sum(amount - coalesce(refund_amount, 0)) filter (where event_type = 'sale' and product = 'preview') as prev_rev,
         sum(amount - coalesce(refund_amount, 0)) filter (where event_type = 'sale' and product = 'middle')  as mid_rev
  from v_events group by client_id
)
select
  c.client_id,
  'TOTAL'::text as cut_key,
  'Total'::text as cut_label,
  'all rounds'::text as cut_sub,
  fo_metrics(
    coalesce(ads.ad_rows, 0) > 0,
    ads.spend, ads.reach, ads.impressions, ads.clicks,
    ev.leads, ev.attendance,
    ev.prev_buy, ev.mid_buy, ev.prev_rev, ev.mid_rev,
    p.preview_price, p.middle_price
  ) as m
from v_clients c
left join ads on ads.client_id = c.client_id
left join ev  on ev.client_id  = c.client_id
left join v_client_prices p on p.client_id = c.client_id;

-- ═══════════════════════════════════════════════════════════════════════════
-- BASELINE — the pinned reference column that never scrolls away.
-- The mockup pins a single historical round as the yardstick; we pin the client's
-- earliest round that has both spend and sales, so it stays meaningful as rounds
-- are added rather than drifting to whatever is first alphabetically.
-- ═══════════════════════════════════════════════════════════════════════════
create or replace view v_metrics_baseline as
select distinct on (client_id)
  client_id, cut_key, cut_label, cut_sub, m
from v_metrics_by_round
where (m->>'spend') is not null and (m->>'rev')::numeric > 0
order by client_id, start_date;

-- ═══════════════════════════════════════════════════════════════════════════
-- CUSTOMER JOURNEY STRIP — one card per stage, values straight off the total.
-- Stage -> metric mapping is data (client_journey_config.stage_metric), so an
-- ecommerce client's strip is built by the same query with no branching.
-- ═══════════════════════════════════════════════════════════════════════════
create or replace view v_journey_strip as
select
  j.client_id, j.stage_order, j.stage_name, j.stage_slug, j.stage_rate_label,
  case j.stage_metric
    when 'impressions'       then (t.m->>'impr')
    when 'clicks'            then (t.m->>'clicks')
    when 'leads'             then (t.m->>'leads')
    when 'attendance'        then (t.m->>'att')
    when 'preview_purchases' then (t.m->>'prevBuy')
    when 'middle_purchases'  then (t.m->>'midBuy')
  end as value,
  case j.stage_metric
    when 'clicks'            then (t.m->>'ctr')
    when 'leads'             then (t.m->>'leadgen')
    when 'attendance'        then (t.m->>'attPct')
    when 'preview_purchases' then (t.m->>'prevPct')
    when 'middle_purchases'  then (t.m->>'midPct')
  end as rate
from v_journey j
left join v_metrics_total t on t.client_id = j.client_id
order by j.client_id, j.stage_order;

-- ═══════════════════════════════════════════════════════════════════════════
-- IMPORT + UNMATCHED — the Data group, and the staleness flag the header carries.
-- ═══════════════════════════════════════════════════════════════════════════
create or replace view v_import_status as
select
  client_id, source, imported_at, coverage_start, coverage_end, row_count,
  column_map, expected_cadence,
  stale_flag or (now() - imported_at) > coalesce(expected_cadence, interval '1 day') * 2
    as is_stale,
  extract(day from now() - imported_at)::int as days_since
from import_batches
order by client_id, source;

create or replace view v_unmatched_summary as
select
  client_id,
  count(*) filter (where not auto_resolved and resolved_at is null) as waiting,
  count(*) filter (where auto_resolved)                             as auto_resolved,
  coalesce(sum(revenue_held) filter (where resolved_at is null), 0) as revenue_held,
  count(*) filter (where resolved_at is null and revenue_held > 0)  as sales_held,
  count(distinct source) filter (where not auto_resolved and resolved_at is null) as source_count
from unmatched_rows
group by client_id;

create or replace view v_unmatched_by_reason as
select
  client_id, reason,
  count(*)                as rows_waiting,
  sum(revenue_held)       as revenue_held
from unmatched_rows
where not auto_resolved and resolved_at is null
group by client_id, reason
order by client_id, count(*) desc;

-- ═══════════════════════════════════════════════════════════════════════════
-- Grants — PostgREST serves these views to the anon key. Views run with the
-- owner's rights (security_invoker is off by default), so base-table RLS isn't
-- re-evaluated per row here; read access is what's granted.
-- ═══════════════════════════════════════════════════════════════════════════
grant usage on schema public to anon, authenticated;
grant select on all tables in schema public to anon, authenticated;

-- ══════════════════════════════════════════════════════════════════════════
-- 0004_client_default.sql
-- ══════════════════════════════════════════════════════════════════════════

-- Funnel OS — patch 0004
-- 1. v_clients now orders by how much history a client has, so the app opens on
--    Shely rather than on whichever client name sorts first alphabetically.
-- 2. v_client_prices falls back to the checkout stage price for journeys that
--    have no 'preview' stage (ecommerce), so their Selling Price row isn't blank.
-- Safe to re-run. Nothing else changes.

-- Configured unit prices, one row per client.
-- A journey whose purchase stage is 'checkout' rather than 'preview' (ecommerce)
-- still records its sales as product = 'preview' — the first purchase in the
-- journey — so the checkout price stands in as the preview price for that client.
create or replace view v_client_prices as
select
  client_id,
  coalesce(
    max(unit_price) filter (where stage_slug = 'preview'),
    max(unit_price) filter (where stage_slug = 'checkout')
  ) as preview_price,
  max(unit_price) filter (where stage_slug = 'middle')   as middle_price,
  max(unit_price) filter (where stage_slug = 'checkout') as checkout_price
from client_journey_config
group by client_id;

-- Clients, for the switcher. Derived from the journey config — client is a
-- dimension, and the journey is what makes a client real to this app.
--
-- Ordered by how much history each client has, so the app opens on the account
-- with something to look at rather than on whichever name sorts first.
create or replace view v_clients as
select
  j.client_id,
  min(j.client_name)        as client_name,
  min(j.client_note)        as client_note,
  count(*)                  as stage_count,
  coalesce(r.round_count, 0) as round_count
from client_journey_config j
left join (
  select client_id, count(*) as round_count from rounds group by client_id
) r on r.client_id = j.client_id
group by j.client_id, r.round_count
order by coalesce(r.round_count, 0) desc, j.client_id;


grant select on v_clients, v_client_prices to anon, authenticated;

-- ══════════════════════════════════════════════════════════════════════════
-- 0005_import.sql
-- ══════════════════════════════════════════════════════════════════════════

-- ═══════════════════════════════════════════════════════════════════════════
-- Funnel OS — patch 0005: the import pipeline
--
-- The workflow the brief specifies is gated and one-way:
--
--   imported ──→ matched ──→ attributed ──→ diffed ──→ committed
--                    │
--                    ├──→ auto-resolved  (confident match, counted, no review)
--                    └──→ parked         (unmatched_rows, not counted, revenue held)
--
-- "Show the diff before committing" means a batch has to exist in a staged state
-- with its parsed rows attached, so nothing is written to events / ads_performance
-- until someone approves it. That's what staged_payload and status are for.
--
-- Safe to re-run.
-- ═══════════════════════════════════════════════════════════════════════════

alter table import_batches
  add column if not exists status         text not null default 'committed'
    check (status in ('staged', 'committed', 'discarded')),
  add column if not exists file_name      text,
  add column if not exists staged_payload jsonb,   -- parsed rows, dropped on commit
  add column if not exists diff_summary   jsonb,   -- what the commit did / would do
  add column if not exists committed_at   timestamptz;

-- Everything seeded before this patch is already committed history.
update import_batches set status = 'committed' where status is null;

-- Which contact an unmatched row was finally tied to, when a human accepts the
-- best guess. Keeps the audit trail: the parked row is resolved, never deleted.
alter table unmatched_rows
  add column if not exists resolved_contact_id uuid references contacts (contact_id),
  add column if not exists resolved_by         text;

create index if not exists idx_import_batches_status on import_batches (status);
create index if not exists idx_unmatched_open
  on unmatched_rows (client_id) where resolved_at is null and auto_resolved = false;

-- The column mapping remembered per source: the most recent committed batch's map
-- is what the next import is checked against, so a renamed column breaks loudly
-- instead of importing a blank.
create or replace view v_column_map as
select distinct on (client_id, source)
  client_id, source, column_map, imported_at
from import_batches
where status = 'committed' and column_map is not null
order by client_id, source, imported_at desc;

-- Batches waiting for approval, for the Import screen.
create or replace view v_staged_batches as
select batch_id, client_id, source, file_name, row_count, imported_at,
       column_map, diff_summary
from import_batches
where status = 'staged'
order by imported_at desc;

grant select on v_column_map, v_staged_batches to anon, authenticated;
grant select on all tables in schema public to anon, authenticated;

-- ══════════════════════════════════════════════════════════════════════════
-- 0006_source.sql
-- ══════════════════════════════════════════════════════════════════════════

-- ═══════════════════════════════════════════════════════════════════════════
-- BY SOURCE  — Overview / By source
--
-- The master sheet splits every round into Total · Paid Ads · Previous Paid Ads
-- · AOAI · Organic. This is that split, as columns on the same spine as every
-- other view — same 29 metrics, same order, same blank-vs-zero rule.
--
-- The bucket is not a new concept: v_events already derives attribution_bucket,
-- including the Previous Paid Ads rule (a Paid Ads person whose closing round
-- isn't the round that produced the lead). This view only groups by it.
--
-- SPEND BELONGS TO PAID ADS, AND ONLY TO PAID ADS.
-- An AOAI member costs nothing to acquire and an organic lead costs nothing to
-- acquire, so their spend is not zero — it does not exist. fo_metrics is told
-- has_ads = false for those columns, which blanks spend, CPM, CPC, CPL, CPA and
-- both ROAS rows rather than dividing by zero. That matches the master sheet,
-- where those cells are empty and the ratios read #DIV/0!.
--
-- Run in the Supabase SQL editor. Creates views only — no table is touched.
-- ═══════════════════════════════════════════════════════════════════════════

-- Column order is fixed rather than data-driven: a column that appears and
-- disappears as rows land would move the others sideways between page loads.
create or replace view v_source_buckets as
select * from (values
  ('Paid Ads',          1, 'utm captured at opt-in'),
  ('Previous Paid Ads', 2, 'paid lead from an earlier round'),
  ('AOAI',              3, 'community member'),
  ('AI Community',      4, 'community member'),
  ('Organic',           5, 'no utm, no community tag'),
  ('Unattributed',      6, 'source not recorded')
) as t(bucket, ord, note);

create or replace view v_metrics_by_source as
with ev as (
  select
    client_id,
    coalesce(attribution_bucket, 'Unattributed') as bucket,
    count(*) filter (where event_type = 'lead')       as leads,
    count(*) filter (where event_type = 'attendance') as attendance,
    count(*) filter (where event_type = 'sale' and product = 'preview') as prev_buy,
    count(*) filter (where event_type = 'sale' and product = 'middle')  as mid_buy,
    sum(amount - coalesce(refund_amount, 0)) filter (where event_type = 'sale' and product = 'preview') as prev_rev,
    sum(amount - coalesce(refund_amount, 0)) filter (where event_type = 'sale' and product = 'middle')  as mid_rev
  from v_events
  group by client_id, coalesce(attribution_bucket, 'Unattributed')
),
ads as (
  select client_id, sum(spend) as spend, sum(reach) as reach,
         sum(impressions) as impressions, sum(clicks) as clicks,
         count(*) as ad_rows
  from v_ads group by client_id
),
share as (
  select client_id, sum(leads) as all_leads from ev group by client_id
)
select
  ev.client_id,
  ev.bucket                                   as cut_key,
  ev.bucket                                   as cut_label,
  case
    when share.all_leads > 0
      then to_char(round(100.0 * ev.leads / share.all_leads), 'FM999') || '% of leads'
    else coalesce(b.note, 'no leads')
  end                                         as cut_sub,
  coalesce(b.ord, 99)                         as ord,
  fo_metrics(
    -- only the paid column has spend behind it
    ev.bucket = 'Paid Ads' and coalesce(ads.ad_rows, 0) > 0,
    case when ev.bucket = 'Paid Ads' then ads.spend       end,
    case when ev.bucket = 'Paid Ads' then ads.reach       end,
    case when ev.bucket = 'Paid Ads' then ads.impressions end,
    case when ev.bucket = 'Paid Ads' then ads.clicks      end,
    ev.leads, ev.attendance,
    ev.prev_buy, ev.mid_buy, ev.prev_rev, ev.mid_rev,
    p.preview_price, p.middle_price
  ) as m
from ev
left join v_source_buckets b on b.bucket = ev.bucket
left join ads   on ads.client_id   = ev.client_id
left join share on share.client_id = ev.client_id
left join v_client_prices p on p.client_id = ev.client_id
order by ev.client_id, coalesce(b.ord, 99);

grant select on v_source_buckets to anon, authenticated;
grant select on v_metrics_by_source to anon, authenticated;

-- ══════════════════════════════════════════════════════════════════════════
-- 0007_round_source.sql
-- ══════════════════════════════════════════════════════════════════════════

-- ═══════════════════════════════════════════════════════════════════════════
-- ROUND × SOURCE  — Overview / Round × source
--
-- The master sheet's actual layout: rounds across the top, each split into
-- Total · Paid Ads · Previous Paid Ads · AOAI · Organic. Two dimensions at
-- once, on the same 29-metric spine as every other view.
--
-- Requires 0006_source.sql (v_source_buckets). Creates a view — no table is
-- touched.
--
-- The per-round Total column is selected straight out of v_metrics_by_round
-- rather than re-aggregated here. That isn't laziness: it makes the Total
-- column reconcile with the By round tab by construction, so the two screens
-- can never drift apart.
--
-- The same asymmetry as v_metrics_by_round is preserved deliberately:
--   leads + attendance count on round_id       — whose class was this?
--   revenue + purchases count on lead_round_id — whose spend produced it?
-- Splitting by bucket must not quietly change which round a sale belongs to.
--
-- Spend attaches to the Paid Ads column only, for the reason given in 0006:
-- an organic lead's acquisition cost is absent, not zero.
-- ═══════════════════════════════════════════════════════════════════════════

create or replace view v_metrics_by_round_source as
with ev as (
  select
    client_id, round_id,
    coalesce(attribution_bucket, 'Unattributed') as bucket,
    count(*) filter (where event_type = 'lead')       as leads,
    count(*) filter (where event_type = 'attendance') as attendance
  from v_events
  group by 1, 2, 3
),
sales as (
  select
    client_id, lead_round_id as round_id,
    coalesce(attribution_bucket, 'Unattributed') as bucket,
    count(*) filter (where product = 'preview') as prev_buy,
    count(*) filter (where product = 'middle')  as mid_buy,
    sum(amount - coalesce(refund_amount, 0)) filter (where product = 'preview') as prev_rev,
    sum(amount - coalesce(refund_amount, 0)) filter (where product = 'middle')  as mid_rev
  from v_events
  where event_type = 'sale' and lead_round_id is not null
  group by 1, 2, 3
),
ads as (
  select client_id, round_id, sum(spend) as spend, sum(reach) as reach,
         sum(impressions) as impressions, sum(clicks) as clicks,
         count(*) as ad_rows
  from v_ads group by 1, 2
),
-- a cell exists if either side has rows for it; a source with nothing in a
-- round gets no column in that round rather than a column of zeroes
cells as (
  select client_id, round_id, bucket from ev
  union
  select client_id, round_id, bucket from sales
)
select
  r.client_id,
  r.round_id || '·' || c.bucket                as cut_key,
  c.bucket                                     as cut_label,
  null::text                                   as cut_sub,
  r.round_id                                   as group_key,
  r.round_id                                   as group_label,
  to_char(r.start_date, 'Mon DD') || ' – ' || to_char(r.end_date, 'DD') as group_sub,
  r.start_date,
  coalesce(b.ord, 99)                          as ord,
  fo_metrics(
    c.bucket = 'Paid Ads' and coalesce(ads.ad_rows, 0) > 0,
    case when c.bucket = 'Paid Ads' then ads.spend       end,
    case when c.bucket = 'Paid Ads' then ads.reach       end,
    case when c.bucket = 'Paid Ads' then ads.impressions end,
    case when c.bucket = 'Paid Ads' then ads.clicks      end,
    ev.leads, ev.attendance,
    sales.prev_buy, sales.mid_buy, sales.prev_rev, sales.mid_rev,
    p.preview_price, p.middle_price
  ) as m
from cells c
join rounds r
  on r.round_id = c.round_id and r.client_id = c.client_id
left join ev
  on ev.client_id = c.client_id and ev.round_id = c.round_id and ev.bucket = c.bucket
left join sales
  on sales.client_id = c.client_id and sales.round_id = c.round_id and sales.bucket = c.bucket
left join ads
  on ads.client_id = c.client_id and ads.round_id = c.round_id
left join v_source_buckets b on b.bucket = c.bucket
left join v_client_prices p on p.client_id = c.client_id

union all

-- the per-round Total column, taken whole from By round so the two tabs agree
select
  client_id,
  cut_key || '·Total',
  'Total',
  null::text,
  cut_key,
  cut_key,
  cut_sub,
  start_date,
  0,
  m
from v_metrics_by_round
where (m->>'leads')::bigint > 0 or (m->>'rev')::numeric > 0 or (m->>'spend') is not null;

grant select on v_metrics_by_round_source to anon, authenticated;

-- ══════════════════════════════════════════════════════════════════════════
-- 0008_absent_not_zero.sql
-- ══════════════════════════════════════════════════════════════════════════

-- ═══════════════════════════════════════════════════════════════════════════
-- ABSENT IS NOT ZERO — for sales, and for spend that names no audience.
--
-- The footer of every screen promises "blank means absent, not zero". fo_metrics
-- kept that promise for ads (p_has_ads blanks spend, CPM, CPC, CPL) and broke it
-- for everything else, because it coalesced the people and money inputs to 0
-- before doing any arithmetic.
--
-- What that produced, on real data, with no payments file ever imported:
--
--     0526-02 → spend 1378.24 · rev 0 · roas 0 · cpa null
--
-- CPA went blank, correctly — no denominator. Revenue and ROAS read a hard ZERO,
-- which is a measurement: it says the round earned nothing. The master sheet says
-- that round returned 6.0×. Nobody had loaded a sale yet; the app was reporting a
-- number about data that did not exist, and reporting it in the direction that
-- makes the work look worthless.
--
-- Compare an empty round under the old rule and you can see the inconsistency in
-- one row: spend is null so it renders "—", rev is 0 so it renders "0.00". Two
-- absences, two different answers.
--
-- Two changes, same idea:
--
--   1. fo_metrics no longer coalesces. NULL in, NULL out — and because SQL
--      arithmetic propagates NULL, every rate and ratio derived from a missing
--      input goes blank on its own. Each view now decides for itself where 0 is
--      a real measurement, and passes coalesce(x, 0) only there.
--
--   2. Ad rows that name no ad set stop being an audience called "". They were
--      appearing on Targeted views as a column with an empty header holding
--      every dollar and zero leads — and a Lead Gen % of 0.00%, which claims
--      those 856 clicks produced nobody. They produced 306 people; we just can't
--      say which audience they came from. That column is now labelled, and its
--      people-derived rows are blank rather than zero.
--
-- Requires 0003, 0006, 0007. Creates views and replaces one function — no table
-- is touched, and no signature changes, so nothing needs dropping.
-- ═══════════════════════════════════════════════════════════════════════════

-- ── The spine ──────────────────────────────────────────────────────────────
-- Same 13 parameters as before, so this is a body-only replacement and the
-- dependent views survive it.
create or replace function fo_metrics(
  p_has_ads           boolean,          -- does this cut have ANY ads_performance rows?
  p_spend             numeric,
  p_reach             bigint,
  p_impressions       bigint,
  p_clicks            bigint,
  p_leads             bigint,
  p_attendance        bigint,
  p_preview_purchases bigint,
  p_middle_purchases  bigint,
  p_preview_revenue   numeric,
  p_middle_revenue    numeric,
  p_preview_price     numeric,          -- configured unit price, from client_journey_config
  p_middle_price      numeric
) returns jsonb
language sql
immutable
as $$
  with m as (
    select
      -- blank-vs-zero: no ads rows for this cut => the ads metrics do not exist
      case when p_has_ads then p_spend       end as spend,
      case when p_has_ads then p_reach       end as reach,
      case when p_has_ads then p_impressions end as impressions,
      case when p_has_ads then p_clicks      end as clicks,
      -- NO coalesce. A caller that means zero passes zero; a caller that means
      -- "this was never measured" passes NULL and every metric below it blanks
      -- itself, because NULL + anything is NULL and NULL / anything is NULL.
      p_leads             as leads,
      p_attendance        as attendance,
      p_preview_purchases as prev_buy,
      p_middle_purchases  as mid_buy,
      p_preview_revenue   as prev_rev,
      p_middle_revenue    as mid_rev
  )
  select jsonb_build_object(
    -- ── METRICS (1–14) ────────────────────────────────────────────────────
    'spend',      spend,
    'reach',      reach,
    'freq',       impressions::numeric / nullif(reach, 0),
    'impr',       impressions,
    'clicks',     clicks,
    'leads',      leads,
    'att',        attendance,
    'prevBuy',    prev_buy,
    'midBuy',     mid_buy,
    'prevRev',    prev_rev,
    'midRev',     mid_rev,
    -- selling price is the configured unit price, shown only where the cut
    -- actually has purchases of that product ('—' otherwise, per the mockup)
    'prevPrice',  case when prev_buy > 0 then p_preview_price end,
    'midPrice',   case when mid_buy  > 0 then p_middle_price  end,
    'rev',        prev_rev + mid_rev,

    -- ── FUNNEL METRICS (15–19) ────────────────────────────────────────────
    'ctr',        clicks::numeric  * 100 / nullif(impressions, 0),
    'leadgen',    leads::numeric   * 100 / nullif(clicks, 0),
    'attPct',     attendance::numeric * 100 / nullif(leads, 0),
    'prevPct',    prev_buy::numeric   * 100 / nullif(attendance, 0),
    'midPct',     mid_buy::numeric    * 100 / nullif(prev_buy, 0),

    -- ── UNIT OF ECONOMICS (20–29) ─────────────────────────────────────────
    'cpm',        spend * 1000 / nullif(impressions, 0),
    'cpc',        spend / nullif(clicks, 0),
    'cpl',        spend / nullif(leads, 0),
    'cpAtt',      spend / nullif(attendance, 0),
    -- CPA is cost per *acquired customer*, and the mockup measures that against
    -- preview purchases (12,897.14 / 39 = 330.70), not preview+middle. The middle
    -- offer is sold to people already acquired by the preview.
    'cpa',        spend / nullif(prev_buy, 0),
    'prevAov',    prev_rev / nullif(prev_buy, 0),
    'prevRoas',   prev_rev / nullif(spend, 0),
    'midAov',     mid_rev / nullif(mid_buy, 0),
    'midRoas',    mid_rev / nullif(spend, 0),
    'roas',       (prev_rev + mid_rev) / nullif(spend, 0)
  )
  from m;
$$;

-- Has this client ever had a sale land? Not "did this cut sell anything" — once
-- a payments file is in, a round that sold nothing really did sell nothing and
-- should read 0. Until then there is no evidence either way, and 0 is a lie.
--
-- Deliberately keyed on events rather than import_batches: a sales file whose
-- every row parked in Unmatched has been imported but has told us nothing.
create or replace view v_sales_seen as
select distinct client_id from v_events where event_type = 'sale';

-- ═══════════════════════════════════════════════════════════════════════════
-- BY ROUND
-- ═══════════════════════════════════════════════════════════════════════════
create or replace view v_metrics_by_round as
with ads as (
  select client_id, round_id,
         sum(spend) as spend, sum(reach) as reach,
         sum(impressions) as impressions, sum(clicks) as clicks,
         count(*) as ad_rows
  from v_ads group by client_id, round_id
),
ev as (
  select client_id, round_id,
         count(*) filter (where event_type = 'lead')       as leads,
         count(*) filter (where event_type = 'attendance') as attendance
  from v_events group by client_id, round_id
),
sales as (
  select client_id, lead_round_id as round_id,
         count(*) filter (where product = 'preview')                     as prev_buy,
         count(*) filter (where product = 'middle')                      as mid_buy,
         sum(amount - coalesce(refund_amount, 0)) filter (where product = 'preview') as prev_rev,
         sum(amount - coalesce(refund_amount, 0)) filter (where product = 'middle')  as mid_rev
  from v_events where event_type = 'sale' and lead_round_id is not null
  group by client_id, lead_round_id
)
select
  r.client_id,
  r.round_id                                  as cut_key,
  r.round_id                                  as cut_label,
  to_char(r.start_date, 'Mon DD') || ' – ' || to_char(r.end_date, 'DD') as cut_sub,
  r.start_date,
  fo_metrics(
    coalesce(ads.ad_rows, 0) > 0,
    ads.spend, ads.reach, ads.impressions, ads.clicks,
    -- leads and attendance are known: the files are in, this round had none
    coalesce(ev.leads, 0), coalesce(ev.attendance, 0),
    -- sales are known only once a sale exists for this client
    case when s.client_id is not null then coalesce(sales.prev_buy, 0) end,
    case when s.client_id is not null then coalesce(sales.mid_buy,  0) end,
    case when s.client_id is not null then coalesce(sales.prev_rev, 0) end,
    case when s.client_id is not null then coalesce(sales.mid_rev,  0) end,
    p.preview_price, p.middle_price
  ) as m
from rounds r
left join ads   on ads.client_id = r.client_id and ads.round_id = r.round_id
left join ev    on ev.client_id  = r.client_id and ev.round_id  = r.round_id
left join sales on sales.client_id = r.client_id and sales.round_id = r.round_id
left join v_sales_seen s on s.client_id = r.client_id
left join v_client_prices p on p.client_id = r.client_id
order by r.client_id, r.start_date;

-- ═══════════════════════════════════════════════════════════════════════════
-- TARGETED VIEWS
--
-- The bridge is events.utm_campaign -> ads_performance.ad_set. Two things get
-- normalised here that didn't before:
--
--   '' is not an ad set. A blank cell in a Meta export means the export didn't
--   say, and "didn't say" is not the name of an audience. Rows like that now
--   group into one labelled column instead of a column with an empty header.
--
--   That column gets NULL people, not zero. It has spend and clicks and no way
--   to know which leads they produced — so leads, attendance, CPL and Lead Gen %
--   are blank there. Reading 0 leads against 856 clicks would say the money
--   bought nobody, when what happened is that the export didn't record which
--   audience bought them.
-- ═══════════════════════════════════════════════════════════════════════════
create or replace view v_metrics_by_adset as
with ads as (
  select client_id, nullif(btrim(ad_set), '') as ad_set,
         sum(spend) as spend, sum(reach) as reach,
         sum(impressions) as impressions, sum(clicks) as clicks,
         count(*) as ad_rows
  from v_ads group by client_id, nullif(btrim(ad_set), '')
),
ev as (
  select client_id, nullif(btrim(utm_campaign), '') as ad_set,
         count(*) filter (where event_type = 'lead')       as leads,
         count(*) filter (where event_type = 'attendance') as attendance,
         count(*) filter (where event_type = 'sale' and product = 'preview') as prev_buy,
         count(*) filter (where event_type = 'sale' and product = 'middle')  as mid_buy,
         sum(amount - coalesce(refund_amount, 0)) filter (where event_type = 'sale' and product = 'preview') as prev_rev,
         sum(amount - coalesce(refund_amount, 0)) filter (where event_type = 'sale' and product = 'middle')  as mid_rev
  from v_events
  where nullif(btrim(utm_campaign), '') is not null
  group by client_id, nullif(btrim(utm_campaign), '')
)
select
  coalesce(ads.client_id, ev.client_id)                     as client_id,
  coalesce(ads.ad_set, ev.ad_set, '(unsplit)')              as cut_key,
  coalesce(ads.ad_set, ev.ad_set, 'Unsplit spend')          as cut_label,
  case when coalesce(ads.ad_set, ev.ad_set) is null
       then 'ads that name no ad set' end                   as cut_sub,
  fo_metrics(
    coalesce(ads.ad_rows, 0) > 0,
    ads.spend, ads.reach, ads.impressions, ads.clicks,
    case when coalesce(ads.ad_set, ev.ad_set) is not null then coalesce(ev.leads, 0)      end,
    case when coalesce(ads.ad_set, ev.ad_set) is not null then coalesce(ev.attendance, 0) end,
    case when coalesce(ads.ad_set, ev.ad_set) is not null and s.client_id is not null
         then coalesce(ev.prev_buy, 0) end,
    case when coalesce(ads.ad_set, ev.ad_set) is not null and s.client_id is not null
         then coalesce(ev.mid_buy, 0)  end,
    case when coalesce(ads.ad_set, ev.ad_set) is not null and s.client_id is not null
         then coalesce(ev.prev_rev, 0) end,
    case when coalesce(ads.ad_set, ev.ad_set) is not null and s.client_id is not null
         then coalesce(ev.mid_rev, 0)  end,
    p.preview_price, p.middle_price
  ) as m,
  -- the app sorts on this descending; unsplit spend is real but it isn't an
  -- audience, so it sits after every named one however large it is
  case when coalesce(ads.ad_set, ev.ad_set) is null then -1
       else coalesce(ads.spend, 0) end                      as sort_spend
from ads
full join ev on ev.client_id = ads.client_id and ev.ad_set = ads.ad_set
left join v_sales_seen s on s.client_id = coalesce(ads.client_id, ev.client_id)
left join v_client_prices p on p.client_id = coalesce(ads.client_id, ev.client_id)
order by 1, sort_spend desc;

-- ═══════════════════════════════════════════════════════════════════════════
-- CLIENT TOTAL
-- ═══════════════════════════════════════════════════════════════════════════
create or replace view v_metrics_total as
with ads as (
  select client_id, sum(spend) as spend, sum(reach) as reach,
         sum(impressions) as impressions, sum(clicks) as clicks, count(*) as ad_rows
  from v_ads group by client_id
),
ev as (
  select client_id,
         count(*) filter (where event_type = 'lead')       as leads,
         count(*) filter (where event_type = 'attendance') as attendance,
         count(*) filter (where event_type = 'sale' and product = 'preview') as prev_buy,
         count(*) filter (where event_type = 'sale' and product = 'middle')  as mid_buy,
         sum(amount - coalesce(refund_amount, 0)) filter (where event_type = 'sale' and product = 'preview') as prev_rev,
         sum(amount - coalesce(refund_amount, 0)) filter (where event_type = 'sale' and product = 'middle')  as mid_rev
  from v_events group by client_id
)
select
  c.client_id,
  'TOTAL'::text as cut_key,
  'Total'::text as cut_label,
  'all rounds'::text as cut_sub,
  fo_metrics(
    coalesce(ads.ad_rows, 0) > 0,
    ads.spend, ads.reach, ads.impressions, ads.clicks,
    coalesce(ev.leads, 0), coalesce(ev.attendance, 0),
    case when s.client_id is not null then coalesce(ev.prev_buy, 0) end,
    case when s.client_id is not null then coalesce(ev.mid_buy,  0) end,
    case when s.client_id is not null then coalesce(ev.prev_rev, 0) end,
    case when s.client_id is not null then coalesce(ev.mid_rev,  0) end,
    p.preview_price, p.middle_price
  ) as m
from v_clients c
left join ads on ads.client_id = c.client_id
left join ev  on ev.client_id  = c.client_id
left join v_sales_seen s on s.client_id = c.client_id
left join v_client_prices p on p.client_id = c.client_id;

-- ═══════════════════════════════════════════════════════════════════════════
-- BY SOURCE — spend still belongs to Paid Ads and only to Paid Ads.
-- ═══════════════════════════════════════════════════════════════════════════
create or replace view v_metrics_by_source as
with ev as (
  select
    client_id,
    coalesce(attribution_bucket, 'Unattributed') as bucket,
    count(*) filter (where event_type = 'lead')       as leads,
    count(*) filter (where event_type = 'attendance') as attendance,
    count(*) filter (where event_type = 'sale' and product = 'preview') as prev_buy,
    count(*) filter (where event_type = 'sale' and product = 'middle')  as mid_buy,
    sum(amount - coalesce(refund_amount, 0)) filter (where event_type = 'sale' and product = 'preview') as prev_rev,
    sum(amount - coalesce(refund_amount, 0)) filter (where event_type = 'sale' and product = 'middle')  as mid_rev
  from v_events
  group by client_id, coalesce(attribution_bucket, 'Unattributed')
),
ads as (
  select client_id, sum(spend) as spend, sum(reach) as reach,
         sum(impressions) as impressions, sum(clicks) as clicks,
         count(*) as ad_rows
  from v_ads group by client_id
),
share as (
  select client_id, sum(leads) as all_leads from ev group by client_id
)
select
  ev.client_id,
  ev.bucket                                   as cut_key,
  ev.bucket                                   as cut_label,
  case
    when share.all_leads > 0
      then to_char(round(100.0 * ev.leads / share.all_leads), 'FM999') || '% of leads'
    else coalesce(b.note, 'no leads')
  end                                         as cut_sub,
  coalesce(b.ord, 99)                         as ord,
  fo_metrics(
    -- only the paid column has spend behind it
    ev.bucket = 'Paid Ads' and coalesce(ads.ad_rows, 0) > 0,
    case when ev.bucket = 'Paid Ads' then ads.spend       end,
    case when ev.bucket = 'Paid Ads' then ads.reach       end,
    case when ev.bucket = 'Paid Ads' then ads.impressions end,
    case when ev.bucket = 'Paid Ads' then ads.clicks      end,
    coalesce(ev.leads, 0), coalesce(ev.attendance, 0),
    case when s.client_id is not null then coalesce(ev.prev_buy, 0) end,
    case when s.client_id is not null then coalesce(ev.mid_buy,  0) end,
    case when s.client_id is not null then coalesce(ev.prev_rev, 0) end,
    case when s.client_id is not null then coalesce(ev.mid_rev,  0) end,
    p.preview_price, p.middle_price
  ) as m
from ev
left join v_source_buckets b on b.bucket = ev.bucket
left join ads   on ads.client_id   = ev.client_id
left join share on share.client_id = ev.client_id
left join v_sales_seen s on s.client_id = ev.client_id
left join v_client_prices p on p.client_id = ev.client_id
order by ev.client_id, coalesce(b.ord, 99);

-- ═══════════════════════════════════════════════════════════════════════════
-- ROUND × SOURCE — per-round Total still lifted whole out of By round, so the
-- two tabs cannot drift.
-- ═══════════════════════════════════════════════════════════════════════════
create or replace view v_metrics_by_round_source as
with ev as (
  select
    client_id, round_id,
    coalesce(attribution_bucket, 'Unattributed') as bucket,
    count(*) filter (where event_type = 'lead')       as leads,
    count(*) filter (where event_type = 'attendance') as attendance
  from v_events
  group by 1, 2, 3
),
sales as (
  select
    client_id, lead_round_id as round_id,
    coalesce(attribution_bucket, 'Unattributed') as bucket,
    count(*) filter (where product = 'preview') as prev_buy,
    count(*) filter (where product = 'middle')  as mid_buy,
    sum(amount - coalesce(refund_amount, 0)) filter (where product = 'preview') as prev_rev,
    sum(amount - coalesce(refund_amount, 0)) filter (where product = 'middle')  as mid_rev
  from v_events
  where event_type = 'sale' and lead_round_id is not null
  group by 1, 2, 3
),
ads as (
  select client_id, round_id, sum(spend) as spend, sum(reach) as reach,
         sum(impressions) as impressions, sum(clicks) as clicks,
         count(*) as ad_rows
  from v_ads group by 1, 2
),
-- a cell exists if either side has rows for it; a source with nothing in a
-- round gets no column in that round rather than a column of zeroes
cells as (
  select client_id, round_id, bucket from ev
  union
  select client_id, round_id, bucket from sales
)
select
  r.client_id,
  r.round_id || '·' || c.bucket                as cut_key,
  c.bucket                                     as cut_label,
  null::text                                   as cut_sub,
  r.round_id                                   as group_key,
  r.round_id                                   as group_label,
  to_char(r.start_date, 'Mon DD') || ' – ' || to_char(r.end_date, 'DD') as group_sub,
  r.start_date,
  coalesce(b.ord, 99)                          as ord,
  fo_metrics(
    c.bucket = 'Paid Ads' and coalesce(ads.ad_rows, 0) > 0,
    case when c.bucket = 'Paid Ads' then ads.spend       end,
    case when c.bucket = 'Paid Ads' then ads.reach       end,
    case when c.bucket = 'Paid Ads' then ads.impressions end,
    case when c.bucket = 'Paid Ads' then ads.clicks      end,
    coalesce(ev.leads, 0), coalesce(ev.attendance, 0),
    case when s.client_id is not null then coalesce(sales.prev_buy, 0) end,
    case when s.client_id is not null then coalesce(sales.mid_buy,  0) end,
    case when s.client_id is not null then coalesce(sales.prev_rev, 0) end,
    case when s.client_id is not null then coalesce(sales.mid_rev,  0) end,
    p.preview_price, p.middle_price
  ) as m
from cells c
join rounds r
  on r.round_id = c.round_id and r.client_id = c.client_id
left join ev
  on ev.client_id = c.client_id and ev.round_id = c.round_id and ev.bucket = c.bucket
left join sales
  on sales.client_id = c.client_id and sales.round_id = c.round_id and sales.bucket = c.bucket
left join ads
  on ads.client_id = c.client_id and ads.round_id = c.round_id
left join v_source_buckets b on b.bucket = c.bucket
left join v_sales_seen s on s.client_id = c.client_id
left join v_client_prices p on p.client_id = c.client_id

union all

-- the per-round Total column, taken whole from By round so the two tabs agree.
-- rev is NULL until a sale exists, so it is coalesced here rather than compared
-- directly — a NULL comparison would make the whole OR-chain NULL and drop the
-- round out of the tab.
select
  client_id,
  cut_key || '·Total',
  'Total',
  null::text,
  cut_key,
  cut_key,
  cut_sub,
  start_date,
  0,
  m
from v_metrics_by_round
where (m->>'leads')::bigint > 0
   or coalesce((m->>'rev')::numeric, 0) > 0
   or (m->>'spend') is not null;

-- ═══════════════════════════════════════════════════════════════════════════
-- BASELINE — the pinned reference column. Same rule, NULL-safe: a client with
-- no sales yet simply has no baseline, rather than the comparison silently
-- vanishing on a NULL.
-- ═══════════════════════════════════════════════════════════════════════════
create or replace view v_metrics_baseline as
select distinct on (client_id)
  client_id, cut_key, cut_label, cut_sub, m
from v_metrics_by_round
where (m->>'spend') is not null and coalesce((m->>'rev')::numeric, 0) > 0
order by client_id, start_date;

grant select on v_sales_seen to anon, authenticated;
grant select on v_metrics_by_round to anon, authenticated;
grant select on v_metrics_by_adset to anon, authenticated;
grant select on v_metrics_total to anon, authenticated;
grant select on v_metrics_baseline to anon, authenticated;
grant select on v_metrics_by_source to anon, authenticated;
grant select on v_metrics_by_round_source to anon, authenticated;

-- ══════════════════════════════════════════════════════════════════════════
-- 0009_audience_and_reasons.sql
-- ══════════════════════════════════════════════════════════════════════════

-- ═══════════════════════════════════════════════════════════════════════════
-- WHICH AUDIENCE CONVERTS — and saying why a row was parked.
--
-- Three fixes, found by checking the live app after the first real sales import.
--
-- 1. TARGETED VIEWS DIED BELOW THE LEADS ROW.
--
--        lead        306 rows, 292 with utm_campaign
--        attendance   40 rows,   0 with utm_campaign
--        sale          2 rows,   0 with utm_campaign
--
--    The importer writes utm_campaign onto lead events and nowhere else, so
--    joining attendance and sales on the event's own utm found nothing and every
--    audience reported 0 attendees and 0 buyers. Those 44 Cold_Broad leads
--    certainly produced some of the 40 attendees; printing 0 claims otherwise.
--
--    The app already solved this problem once. lead_round_id exists because a
--    sale belongs to the round that ACQUIRED the person, not the round it
--    happened in. Audiences get the same treatment here: a person's attendance
--    and purchases are attributed to the audience their lead came from. Without
--    it the tab can only ever report cost per lead, when the question it is
--    named for is which audience converts.
--
-- 2. THE COLUMNS SHUFFLED BETWEEN PAGE LOADS. With no per-audience spend,
--    sort_spend was 0 for all eight audiences and Postgres returned them in
--    whatever order it liked. v_metrics_by_source fixes its column order on
--    purpose so a column doesn't slide sideways; this view now does too, via an
--    explicit `ord` the app reads instead of a spend that is often a tie.
--
-- 3. "NAME ONLY, NO CONTACT DETAIL" WAS GROUPING ROWS THAT HAD CONTACT DETAIL.
--    The importer reused reason = 'name_only' for rows it couldn't use for
--    completely different causes — no opt-in date, no round, an unrecognised
--    product. limpljanet@gmail.com sat under "no contact detail" with its email
--    right there in the row. Two new reasons split that apart, and they map to
--    two different actions: fix the file, or create the round.
--
-- Requires 0008. Adds a check constraint value and re-labels 9 existing rows;
-- creates no tables.
-- ═══════════════════════════════════════════════════════════════════════════

-- ── 3. Reasons ─────────────────────────────────────────────────────────────
alter table unmatched_rows drop constraint if exists unmatched_rows_reason_check;
alter table unmatched_rows add constraint unmatched_rows_reason_check
  check (reason in (
    'same_person_two_addresses',
    'phone_format',
    'name_only',          -- we know the row, we don't know the person
    'bought_without_lead',
    'incomplete_row',     -- the row is missing something the app needs
    'no_matching_round',  -- the row is fine; there is no round to attach it to
    'unknown_person'      -- contact detail we have, a person we don't
  ));

-- Re-label only rows whose guess_method already names the real cause. Rows
-- parked by the identity matcher have a null guess_method and really are
-- name_only — the 121 Zoom attendees with no email, and the 7 sales rows with
-- no email, are correctly filed and are left alone.
update unmatched_rows
   set reason = 'incomplete_row'
 where reason = 'name_only'
   and guess_method in ('no usable opt-in date', 'missing date or amount');

update unmatched_rows
   set reason = 'no_matching_round'
 where reason = 'name_only'
   and (guess_method like 'no round covers%' or guess_method like 'no round matches%');

-- ═══════════════════════════════════════════════════════════════════════════
-- 1 + 2. TARGETED VIEWS
-- ═══════════════════════════════════════════════════════════════════════════
create or replace view v_metrics_by_adset as
with ads as (
  select client_id, nullif(btrim(ad_set), '') as ad_set,
         sum(spend) as spend, sum(reach) as reach,
         sum(impressions) as impressions, sum(clicks) as clicks,
         count(*) as ad_rows
  from v_ads group by client_id, nullif(btrim(ad_set), '')
),
-- The audience that ACQUIRED each person: the earliest lead of theirs that
-- carries a utm. A contact with no tagged lead has no audience and stays out of
-- every audience column, which is the existing rule and still correct — an
-- organic lead cost nothing, so it belongs to no ad set.
lead_audience as (
  select distinct on (client_id, contact_id)
         client_id, contact_id, nullif(btrim(utm_campaign), '') as ad_set
  from v_events
  where event_type = 'lead'
    and contact_id is not null
    and nullif(btrim(utm_campaign), '') is not null
  order by client_id, contact_id, event_date
),
-- A LEAD is counted on its OWN tag, not on the acquiring lead's. The two differ
-- for anyone who opted in twice: 40 contacts here have a second lead, and
-- routing those through the first audience inflated the lead total from 828 to
-- 868. That second opt-in genuinely came from the second ad set — it is the
-- events with no tag of their own that need the detour.
ev_leads as (
  select client_id, nullif(btrim(utm_campaign), '') as ad_set, count(*) as leads
  from v_events
  where event_type = 'lead' and nullif(btrim(utm_campaign), '') is not null
  group by 1, 2
),
ev_after as (
  select
    la.client_id, la.ad_set,
    count(*) filter (where e.event_type = 'attendance') as attendance,
    count(*) filter (where e.event_type = 'sale' and e.product = 'preview') as prev_buy,
    count(*) filter (where e.event_type = 'sale' and e.product = 'middle')  as mid_buy,
    sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.event_type = 'sale' and e.product = 'preview') as prev_rev,
    sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.event_type = 'sale' and e.product = 'middle')  as mid_rev
  from v_events e
  join lead_audience la
    on la.client_id = e.client_id and la.contact_id = e.contact_id
  where e.event_type <> 'lead'
  group by la.client_id, la.ad_set
),
ev as (
  select
    coalesce(l.client_id, a.client_id) as client_id,
    coalesce(l.ad_set, a.ad_set)       as ad_set,
    l.leads, a.attendance, a.prev_buy, a.mid_buy, a.prev_rev, a.mid_rev
  from ev_leads l
  full join ev_after a on a.client_id = l.client_id and a.ad_set = l.ad_set
)
select
  coalesce(ads.client_id, ev.client_id)                     as client_id,
  coalesce(ads.ad_set, ev.ad_set, '(unsplit)')              as cut_key,
  coalesce(ads.ad_set, ev.ad_set, 'Unsplit spend')          as cut_label,
  case when coalesce(ads.ad_set, ev.ad_set) is null
       then 'ads that name no ad set' end                   as cut_sub,
  fo_metrics(
    coalesce(ads.ad_rows, 0) > 0,
    ads.spend, ads.reach, ads.impressions, ads.clicks,
    case when coalesce(ads.ad_set, ev.ad_set) is not null then coalesce(ev.leads, 0)      end,
    case when coalesce(ads.ad_set, ev.ad_set) is not null then coalesce(ev.attendance, 0) end,
    case when coalesce(ads.ad_set, ev.ad_set) is not null and s.client_id is not null
         then coalesce(ev.prev_buy, 0) end,
    case when coalesce(ads.ad_set, ev.ad_set) is not null and s.client_id is not null
         then coalesce(ev.mid_buy, 0)  end,
    case when coalesce(ads.ad_set, ev.ad_set) is not null and s.client_id is not null
         then coalesce(ev.prev_rev, 0) end,
    case when coalesce(ads.ad_set, ev.ad_set) is not null and s.client_id is not null
         then coalesce(ev.mid_rev, 0)  end,
    p.preview_price, p.middle_price
  ) as m,
  case when coalesce(ads.ad_set, ev.ad_set) is null then -1
       else coalesce(ads.spend, 0) end                      as sort_spend,
  -- Fixed column order. Spend first because that's the size of the bet, leads
  -- as the tiebreaker when no spend is attributable, then the name so the order
  -- is total rather than merely mostly-decided. Unsplit spend always last: it is
  -- real money but it isn't an audience.
  row_number() over (
    partition by coalesce(ads.client_id, ev.client_id)
    order by
      case when coalesce(ads.ad_set, ev.ad_set) is null then 1 else 0 end,
      coalesce(ads.spend, 0) desc,
      coalesce(ev.leads, 0) desc,
      coalesce(ads.ad_set, ev.ad_set)
  )::int                                                    as ord
from ads
full join ev on ev.client_id = ads.client_id and ev.ad_set = ads.ad_set
left join v_sales_seen s on s.client_id = coalesce(ads.client_id, ev.client_id)
left join v_client_prices p on p.client_id = coalesce(ads.client_id, ev.client_id)
order by 1, ord;

grant select on v_metrics_by_adset to anon, authenticated;

-- ══════════════════════════════════════════════════════════════════════════
-- 0010_price_and_untagged_paid.sql
-- ══════════════════════════════════════════════════════════════════════════

-- ═══════════════════════════════════════════════════════════════════════════
-- THE MIDDLE OFFER HAS NO SINGLE PRICE — and untagged paid leads are not free.
--
-- 1. middle_price was configured as 3,000. The master sheet shows May's middle
--    ticket closing at 1,197 · 1,298.50 · 1,400 · 1,700 · 2,000 and never once
--    at 3,000. There is no single number that is right, so the honest value is
--    no number: Middle Selling Price renders '—' and Middle Offer AOV, which is
--    computed from money that actually moved, carries the truth.
--
--    Preview stays 297. That one really is fixed for everyone.
--
--    If the business does have a list price it discounts from, set it here and
--    Middle Selling Price starts reading again. Absent is a statement, not a
--    placeholder.
--
-- 2. FOURTEEN PAID LEADS WITH NO AD SET WERE FALLING OUT OF TARGETED VIEWS
--    ENTIRELY — including both buyers.
--
--        SALE 297 preview → their lead: {"utm_campaign": null, "source": "Paid Ads"}
--        SALE 297 preview → their lead: {"utm_campaign": null, "source": "Paid Ads"}
--
--    They are Paid Ads because their GoHighLevel campaign says so
--    (DF_SG_Preview_Sprint1_0526_02 is a Meta campaign). They have no ad set
--    because 23 people in the master export never appear in either round file,
--    and utm_term only exists there. No ad set is not the same as no ad.
--
--    Calling them Organic would say they cost nothing to acquire, which would
--    move 594.00 of revenue out of Paid Ads, blank the paid ROAS and invent an
--    organic return on spend that never happened. So they stay Paid Ads — but
--    they stop vanishing. The 'Unsplit spend' column already holds ad money
--    that names no audience; it now holds the paid people who name none either.
--    Same column, same reason: real, paid, unsplittable.
--
--    Organic and community leads still belong to no audience column, because
--    for them there genuinely was no ad.
--
-- Requires 0009. Changes one config value and one view.
-- ═══════════════════════════════════════════════════════════════════════════

update client_journey_config
   set unit_price = null
 where stage_slug = 'middle' and client_id = 'shely';

create or replace view v_metrics_by_adset as
with ads as (
  select client_id, nullif(btrim(ad_set), '') as ad_set,
         sum(spend) as spend, sum(reach) as reach,
         sum(impressions) as impressions, sum(clicks) as clicks,
         count(*) as ad_rows
  from v_ads group by client_id, nullif(btrim(ad_set), '')
),
-- The audience that ACQUIRED each person: the earliest lead of theirs carrying
-- a utm. Paid leads with no utm resolve to the unsplit bucket instead of to
-- nothing, so their attendance and purchases stay attached to paid money.
lead_audience as (
  select distinct on (client_id, contact_id)
         client_id, contact_id,
         coalesce(nullif(btrim(utm_campaign), ''),
                  case when source = 'Paid Ads' then '(unsplit)' end) as ad_set
  from v_events
  where event_type = 'lead'
    and contact_id is not null
    and (nullif(btrim(utm_campaign), '') is not null or source = 'Paid Ads')
  order by client_id, contact_id, event_date
),
-- A LEAD is counted on its OWN tag, not on the acquiring lead's. The two differ
-- for anyone who opted in twice, and routing those through the first audience
-- inflated the lead total. That second opt-in really did come from the second
-- ad set — it is the events with no tag of their own that need the detour.
ev_leads as (
  select client_id,
         coalesce(nullif(btrim(utm_campaign), ''),
                  case when source = 'Paid Ads' then '(unsplit)' end) as ad_set,
         count(*) as leads
  from v_events
  where event_type = 'lead'
    and (nullif(btrim(utm_campaign), '') is not null or source = 'Paid Ads')
  group by 1, 2
),
ev_after as (
  select
    la.client_id, la.ad_set,
    count(*) filter (where e.event_type = 'attendance') as attendance,
    count(*) filter (where e.event_type = 'sale' and e.product = 'preview') as prev_buy,
    count(*) filter (where e.event_type = 'sale' and e.product = 'middle')  as mid_buy,
    sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.event_type = 'sale' and e.product = 'preview') as prev_rev,
    sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.event_type = 'sale' and e.product = 'middle')  as mid_rev
  from v_events e
  join lead_audience la
    on la.client_id = e.client_id and la.contact_id = e.contact_id
  where e.event_type <> 'lead'
  group by la.client_id, la.ad_set
),
ev as (
  select
    coalesce(l.client_id, a.client_id) as client_id,
    coalesce(l.ad_set, a.ad_set)       as ad_set,
    l.leads, a.attendance, a.prev_buy, a.mid_buy, a.prev_rev, a.mid_rev
  from ev_leads l
  full join ev_after a on a.client_id = l.client_id and a.ad_set = l.ad_set
),
-- ads with no ad set and paid people with no ad set are the same column
cut as (
  select
    coalesce(ads.client_id, ev.client_id) as client_id,
    case when ads.ad_set is null and ev.ad_set is null then '(unsplit)'
         else coalesce(ads.ad_set, ev.ad_set) end as ad_set,
    ads.spend, ads.reach, ads.impressions, ads.clicks, ads.ad_rows,
    ev.leads, ev.attendance, ev.prev_buy, ev.mid_buy, ev.prev_rev, ev.mid_rev
  from ads
  full join ev on ev.client_id = ads.client_id and ev.ad_set = ads.ad_set
),
-- sum() widens bigint to numeric, and fo_metrics is typed on bigint for the
-- counts. Cast back explicitly rather than letting the call fail to resolve.
rolled as (
  select client_id, ad_set,
         sum(spend)::numeric      as spend,
         sum(reach)::bigint       as reach,
         sum(impressions)::bigint as impressions,
         sum(clicks)::bigint      as clicks,
         sum(ad_rows)::bigint     as ad_rows,
         sum(leads)::bigint       as leads,
         sum(attendance)::bigint  as attendance,
         sum(prev_buy)::bigint    as prev_buy,
         sum(mid_buy)::bigint     as mid_buy,
         sum(prev_rev)::numeric   as prev_rev,
         sum(mid_rev)::numeric    as mid_rev
  from cut group by client_id, ad_set
)
select
  r.client_id,
  r.ad_set                                                  as cut_key,
  case when r.ad_set = '(unsplit)' then 'Unsplit spend' else r.ad_set end as cut_label,
  case when r.ad_set = '(unsplit)'
       then 'paid, no ad set recorded' end                  as cut_sub,
  fo_metrics(
    coalesce(r.ad_rows, 0) > 0,
    r.spend, r.reach, r.impressions, r.clicks,
    coalesce(r.leads, 0), coalesce(r.attendance, 0),
    case when s.client_id is not null then coalesce(r.prev_buy, 0) end,
    case when s.client_id is not null then coalesce(r.mid_buy,  0) end,
    case when s.client_id is not null then coalesce(r.prev_rev, 0) end,
    case when s.client_id is not null then coalesce(r.mid_rev,  0) end,
    p.preview_price, p.middle_price
  ) as m,
  case when r.ad_set = '(unsplit)' then -1 else coalesce(r.spend, 0) end as sort_spend,
  -- Fixed column order: spend, then leads, then name, so it is total rather
  -- than merely mostly-decided. Unsplit always last — real money, not an
  -- audience.
  row_number() over (
    partition by r.client_id
    order by
      case when r.ad_set = '(unsplit)' then 1 else 0 end,
      coalesce(r.spend, 0) desc,
      coalesce(r.leads, 0) desc,
      r.ad_set
  )::int                                                    as ord
from rolled r
left join v_sales_seen s on s.client_id = r.client_id
left join v_client_prices p on p.client_id = r.client_id
order by 1, ord;

grant select on v_metrics_by_adset to anon, authenticated;

-- ══════════════════════════════════════════════════════════════════════════
-- 0011_lead_adset_and_ad.sql
-- ══════════════════════════════════════════════════════════════════════════

-- ═══════════════════════════════════════════════════════════════════════════
-- A LEAD CARRIES AN AUDIENCE AND AN AD, NOT ONE FIELD DOING BOTH JOBS.
--
-- GoHighLevel writes three tracking tags at opt-in and they mean three
-- different things:
--
--   utm_term     the AUDIENCE   Cold_BusinessOwners
--   utm_content  the AD         Static_LetAISellYourProducts
--   utm_campaign the ROUND      DF_SG_Preview_Sprint1_0526_02
--
-- The app only ever read one column, called it utm_campaign, and expected the
-- AUDIENCE in it. So the raw GHL export imported perfectly and attributed
-- nothing: every lead arrived carrying a round name where an ad set was
-- expected, matched no audience, and silently fell back to date-window
-- attribution. The only reason the numbers are right today is that leads.csv
-- was hand-edited to move utm_term into the utm_campaign column — a manual step
-- that would eventually be forgotten with nothing to warn anyone.
--
-- events now stores what it actually has: ad_set and ad, named after the same
-- things ads_performance names them, so both sides of the bridge match.
--
-- The 17 leads whose utm_content is a raw numeric Ad ID rather than a name are
-- stored as-is. An id is a better key than a name — names get edited in Ads
-- Manager and silently break the join — and this is where that will be resolved
-- when ad-level Meta data arrives.
--
-- Requires 0010. Adds two columns, backfills them, replaces one view.
-- ═══════════════════════════════════════════════════════════════════════════

alter table events add column if not exists ad_set text;
alter table events add column if not exists ad     text;

create index if not exists idx_events_adset on events (ad_set);

-- Everything already imported put the audience in utm_campaign, because that is
-- the only column the importer read. Move it, don't reinterpret it: whatever is
-- in there today IS what the audience bridge has been matching on, so copying it
-- across preserves every number on screen exactly.
update events
   set ad_set = nullif(btrim(utm_campaign), '')
 where event_type = 'lead'
   and ad_set is null
   and nullif(btrim(utm_campaign), '') is not null;

-- v_events was written as `select r.client_id, e.*, … as attribution_bucket`,
-- and `e.*` is expanded ONCE, when the view is created. Adding a column to
-- events therefore does not reach the view — every downstream query would fail
-- with "column ad_set does not exist" while the column plainly exists.
--
-- The columns are listed out here rather than starred, in their table order,
-- with the two new ones appended AFTER attribution_bucket. Appending is the only
-- edit CREATE OR REPLACE VIEW accepts; had they landed mid-list (where `*` would
-- have put them) this would need a drop-cascade and a rebuild of all seven
-- dependent views.
create or replace view v_events as
select
  r.client_id,
  e.event_id, e.contact_id, e.round_id, e.event_type, e.event_date,
  e.lead_round_id, e.close_round_id, e.attribution_method, e.utm_campaign,
  e.source, e.match_status, e.product, e.minutes_watched,
  e.amount, e.refund_amount, e.refund_date, e.is_lead, e.import_batch_id,
  case
    when e.source = 'Paid Ads'
     and coalesce(e.close_round_id, e.round_id) is distinct from e.lead_round_id
      then 'Previous Paid Ads'
    else e.source
  end as attribution_bucket,
  e.ad_set,
  e.ad
from events e
join rounds r on r.round_id = e.round_id;

grant select on v_events to anon, authenticated;

-- ═══════════════════════════════════════════════════════════════════════════
-- TARGETED VIEWS — same view as 0010, bridging on ad_set instead of on a
-- column named after a different tag.
-- ═══════════════════════════════════════════════════════════════════════════
create or replace view v_metrics_by_adset as
with ads as (
  select client_id, nullif(btrim(ad_set), '') as ad_set,
         sum(spend) as spend, sum(reach) as reach,
         sum(impressions) as impressions, sum(clicks) as clicks,
         count(*) as ad_rows
  from v_ads group by client_id, nullif(btrim(ad_set), '')
),
-- The audience that ACQUIRED each person: the earliest lead of theirs carrying
-- one. Paid leads with no audience resolve to the unsplit bucket rather than to
-- nothing, so their attendance and purchases stay attached to paid money.
lead_audience as (
  select distinct on (client_id, contact_id)
         client_id, contact_id,
         coalesce(nullif(btrim(ad_set), ''),
                  case when source = 'Paid Ads' then '(unsplit)' end) as ad_set
  from v_events
  where event_type = 'lead'
    and contact_id is not null
    and (nullif(btrim(ad_set), '') is not null or source = 'Paid Ads')
  order by client_id, contact_id, event_date
),
-- A LEAD counts on its OWN audience, not on the acquiring lead's. The two
-- differ for anyone who opted in twice, and routing those through the first
-- audience inflates the lead total — that second opt-in really did come from
-- the second ad set. It is the events with no tag of their own that need the
-- detour.
ev_leads as (
  select client_id,
         coalesce(nullif(btrim(ad_set), ''),
                  case when source = 'Paid Ads' then '(unsplit)' end) as ad_set,
         count(*) as leads
  from v_events
  where event_type = 'lead'
    and (nullif(btrim(ad_set), '') is not null or source = 'Paid Ads')
  group by 1, 2
),
ev_after as (
  select
    la.client_id, la.ad_set,
    count(*) filter (where e.event_type = 'attendance') as attendance,
    count(*) filter (where e.event_type = 'sale' and e.product = 'preview') as prev_buy,
    count(*) filter (where e.event_type = 'sale' and e.product = 'middle')  as mid_buy,
    sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.event_type = 'sale' and e.product = 'preview') as prev_rev,
    sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.event_type = 'sale' and e.product = 'middle')  as mid_rev
  from v_events e
  join lead_audience la
    on la.client_id = e.client_id and la.contact_id = e.contact_id
  where e.event_type <> 'lead'
  group by la.client_id, la.ad_set
),
ev as (
  select
    coalesce(l.client_id, a.client_id) as client_id,
    coalesce(l.ad_set, a.ad_set)       as ad_set,
    l.leads, a.attendance, a.prev_buy, a.mid_buy, a.prev_rev, a.mid_rev
  from ev_leads l
  full join ev_after a on a.client_id = l.client_id and a.ad_set = l.ad_set
),
cut as (
  select
    coalesce(ads.client_id, ev.client_id) as client_id,
    case when ads.ad_set is null and ev.ad_set is null then '(unsplit)'
         else coalesce(ads.ad_set, ev.ad_set) end as ad_set,
    ads.spend, ads.reach, ads.impressions, ads.clicks, ads.ad_rows,
    ev.leads, ev.attendance, ev.prev_buy, ev.mid_buy, ev.prev_rev, ev.mid_rev
  from ads
  full join ev on ev.client_id = ads.client_id and ev.ad_set = ads.ad_set
),
rolled as (
  select client_id, ad_set,
         sum(spend)::numeric      as spend,
         sum(reach)::bigint       as reach,
         sum(impressions)::bigint as impressions,
         sum(clicks)::bigint      as clicks,
         sum(ad_rows)::bigint     as ad_rows,
         sum(leads)::bigint       as leads,
         sum(attendance)::bigint  as attendance,
         sum(prev_buy)::bigint    as prev_buy,
         sum(mid_buy)::bigint     as mid_buy,
         sum(prev_rev)::numeric   as prev_rev,
         sum(mid_rev)::numeric    as mid_rev
  from cut group by client_id, ad_set
)
select
  r.client_id,
  r.ad_set                                                  as cut_key,
  case when r.ad_set = '(unsplit)' then 'Unsplit spend' else r.ad_set end as cut_label,
  case when r.ad_set = '(unsplit)'
       then 'paid, no ad set recorded' end                  as cut_sub,
  fo_metrics(
    coalesce(r.ad_rows, 0) > 0,
    r.spend, r.reach, r.impressions, r.clicks,
    coalesce(r.leads, 0), coalesce(r.attendance, 0),
    case when s.client_id is not null then coalesce(r.prev_buy, 0) end,
    case when s.client_id is not null then coalesce(r.mid_buy,  0) end,
    case when s.client_id is not null then coalesce(r.prev_rev, 0) end,
    case when s.client_id is not null then coalesce(r.mid_rev,  0) end,
    p.preview_price, p.middle_price
  ) as m,
  case when r.ad_set = '(unsplit)' then -1 else coalesce(r.spend, 0) end as sort_spend,
  row_number() over (
    partition by r.client_id
    order by
      case when r.ad_set = '(unsplit)' then 1 else 0 end,
      coalesce(r.spend, 0) desc,
      coalesce(r.leads, 0) desc,
      r.ad_set
  )::int                                                    as ord
from rolled r
left join v_sales_seen s on s.client_id = r.client_id
left join v_client_prices p on p.client_id = r.client_id
order by 1, ord;

grant select on v_metrics_by_adset to anon, authenticated;

-- ══════════════════════════════════════════════════════════════════════════
-- 0012_by_month.sql
-- ══════════════════════════════════════════════════════════════════════════

-- ═══════════════════════════════════════════════════════════════════════════
-- BY MONTH — management's first question, and the last unwired overview tab.
--
-- Every other comparison view already exists; this one was the only tab whose
-- SQL had never been written, so the app said "not wired yet" rather than
-- showing an answer to the question it is most often asked.
--
-- The cut is rounds.start_date grouped to a calendar month. A month is not a
-- new dimension — it is rounds, rolled up one level. That matters, because it
-- means every number on this tab is the same number as on By round, added the
-- same way, and the two tabs cannot disagree.
--
-- Three decisions worth stating, because each one could reasonably have gone
-- the other way:
--
--   1. A round belongs to the month it STARTED in, not to the month each ad
--      impression or opt-in happened in. 0526-02 ran 13–19 May and is May.
--      A round straddling a month boundary lands whole in its opening month
--      rather than being split — splitting it would put spend in one month and
--      the class that spend paid for in another, and every closing rate would
--      then be measured against a denominator from a different column.
--
--   2. Revenue counts on the month of the round that PRODUCED the lead, exactly
--      as By round counts it on lead_round_id. A June buyer whose lead came from
--      a May ad is May's return on May's spend. This is the whole reason the app
--      exists, and it must not change just because the columns got wider.
--
--   3. Reach is summed across the rounds in a month, which double-counts anyone
--      Meta showed the ads to in both. That is already true of the Total column
--      on every other tab — reach cannot be added, and Meta only reports it
--      per query. Consistent-and-known beats a different wrong number here.
--
-- A month appears if it contains a round, even when that round has no data yet:
-- By round shows the empty rounds, so By month shows the empty months. A tab
-- that quietly hid them would be claiming those months don't exist.
--
-- Requires 0008 (fo_metrics without coalesce, v_sales_seen). Creates one view.
-- ═══════════════════════════════════════════════════════════════════════════

create or replace view v_metrics_by_month as
with months as (
  select client_id,
         date_trunc('month', start_date)::date as month_start,
         count(*)::int                         as round_count
  from rounds
  group by 1, 2
),
ads as (
  select r.client_id,
         date_trunc('month', r.start_date)::date as month_start,
         sum(a.spend)       as spend,
         sum(a.reach)       as reach,
         sum(a.impressions) as impressions,
         sum(a.clicks)      as clicks,
         count(*)           as ad_rows
  from v_ads a
  join rounds r on r.round_id = a.round_id
  group by 1, 2
),
ev as (
  select r.client_id,
         date_trunc('month', r.start_date)::date as month_start,
         count(*) filter (where e.event_type = 'lead')       as leads,
         count(*) filter (where e.event_type = 'attendance') as attendance
  from v_events e
  join rounds r on r.round_id = e.round_id
  group by 1, 2
),
-- lead_round_id, not round_id: see decision 2 above.
sales as (
  select r.client_id,
         date_trunc('month', r.start_date)::date as month_start,
         count(*) filter (where e.product = 'preview') as prev_buy,
         count(*) filter (where e.product = 'middle')  as mid_buy,
         sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.product = 'preview') as prev_rev,
         sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.product = 'middle')  as mid_rev
  from v_events e
  join rounds r on r.round_id = e.lead_round_id
  where e.event_type = 'sale' and e.lead_round_id is not null
  group by 1, 2
)
select
  m.client_id,
  to_char(m.month_start, 'YYYY-MM')                       as cut_key,
  to_char(m.month_start, 'Mon YYYY')                      as cut_label,
  m.round_count || ' round' || case when m.round_count = 1 then '' else 's' end as cut_sub,
  m.month_start,
  fo_metrics(
    coalesce(ads.ad_rows, 0) > 0,
    ads.spend, ads.reach, ads.impressions, ads.clicks,
    -- leads and attendance are known: the files are in, this month had none
    coalesce(ev.leads, 0), coalesce(ev.attendance, 0),
    -- sales are known only once a sale exists for this client
    case when s.client_id is not null then coalesce(sales.prev_buy, 0) end,
    case when s.client_id is not null then coalesce(sales.mid_buy,  0) end,
    case when s.client_id is not null then coalesce(sales.prev_rev, 0) end,
    case when s.client_id is not null then coalesce(sales.mid_rev,  0) end,
    p.preview_price, p.middle_price
  ) as m
from months m
left join ads   on ads.client_id   = m.client_id and ads.month_start   = m.month_start
left join ev    on ev.client_id    = m.client_id and ev.month_start    = m.month_start
left join sales on sales.client_id = m.client_id and sales.month_start = m.month_start
left join v_sales_seen s   on s.client_id = m.client_id
left join v_client_prices p on p.client_id = m.client_id
order by m.client_id, m.month_start;

grant select on v_metrics_by_month to anon, authenticated;

-- ══════════════════════════════════════════════════════════════════════════
-- 0013_unsplit_has_no_delivery.sql
-- ══════════════════════════════════════════════════════════════════════════

-- ═══════════════════════════════════════════════════════════════════════════
-- "UNSPLIT SPEND" HAS NO CTR, BECAUSE IT IS NOT AN AUDIENCE.
--
-- Targeted views ends in a column called Unsplit spend. It holds the money that
-- moved without naming an ad set — a campaign exported without an ad-set
-- breakdown, or a round-level correction row. The column exists so that spend
-- lands SOMEWHERE rather than vanishing, and its label says exactly that.
--
-- It was also printing delivery metrics, and they were nonsense:
--
--     Unsplit spend    reach 22,803   impressions 1,566   clicks 856
--                      Outbound CTR 54.66%   Lead Gen % 1.05%   Frequency 0.07
--
-- 54.66% is not a click-through rate anyone has ever seen. It is 856 clicks —
-- the whole account's outbound clicks for two rounds — divided by 1,566
-- impressions, which belong only to the one campaign that had no ad-set
-- breakdown. Two different populations, one fraction. Frequency 0.07 says every
-- person saw the ad a fourteenth of a time.
--
-- The cause is not arithmetic. Meta's ad-set-level export gives spend and
-- impressions per ad set and does NOT give reach (deduplicated people cannot be
-- summed) or outbound clicks (the Outbound CTR column comes back empty on every
-- row). So those two figures are only available for the account as a whole and
-- have to enter as rows that name no ad set — landing, correctly, in the only
-- bucket for rows that name no ad set.
--
-- Every other view is unaffected and already right: By round, By source and the
-- Total column group by round, so they read reach 12,672 and clicks 479 for
-- 0526-02, matching the master sheet to the unit.
--
-- The rule this applies:
--
--   Reach, impressions and clicks describe how an AUDIENCE was delivered to.
--   Spend describes a payment. In the bucket whose entire meaning is "we cannot
--   say which audience", the delivery metrics have no subject, so they are
--   absent rather than zero and rather than wrong. Spend, leads, attendance and
--   revenue stay — those are real facts about the bucket.
--
-- After this the column reads: spend 84.20 · leads 9 · CPL 9.36 · attendance 2
-- · CP Attendance 42.10 · revenue 594.00 · ROAS 7.1, and a dash everywhere the
-- number would have been a fabrication.
--
-- THE REAL FIX IS UPSTREAM. Re-export the ad-set report from Meta with Reach
-- and Outbound clicks included as columns. Then every audience carries its own
-- CTR and CPC, the correction rows stop being necessary, and this bucket goes
-- back to holding nothing but genuinely unattributable spend.
--
-- Requires 0011. Replaces one view; no table is touched.
-- ═══════════════════════════════════════════════════════════════════════════

create or replace view v_metrics_by_adset as
with ads as (
  select client_id, nullif(btrim(ad_set), '') as ad_set,
         sum(spend) as spend, sum(reach) as reach,
         sum(impressions) as impressions, sum(clicks) as clicks,
         count(*) as ad_rows
  from v_ads group by client_id, nullif(btrim(ad_set), '')
),
-- The audience that ACQUIRED each person: the earliest lead of theirs carrying
-- one. Paid leads with no audience resolve to the unsplit bucket rather than to
-- nothing, so their attendance and purchases stay attached to paid money.
lead_audience as (
  select distinct on (client_id, contact_id)
         client_id, contact_id,
         coalesce(nullif(btrim(ad_set), ''),
                  case when source = 'Paid Ads' then '(unsplit)' end) as ad_set
  from v_events
  where event_type = 'lead'
    and contact_id is not null
    and (nullif(btrim(ad_set), '') is not null or source = 'Paid Ads')
  order by client_id, contact_id, event_date
),
-- A LEAD counts on its OWN audience, not on the acquiring lead's. The two
-- differ for anyone who opted in twice, and routing those through the first
-- audience inflates the lead total — that second opt-in really did come from
-- the second ad set. It is the events with no tag of their own that need the
-- detour.
ev_leads as (
  select client_id,
         coalesce(nullif(btrim(ad_set), ''),
                  case when source = 'Paid Ads' then '(unsplit)' end) as ad_set,
         count(*) as leads
  from v_events
  where event_type = 'lead'
    and (nullif(btrim(ad_set), '') is not null or source = 'Paid Ads')
  group by 1, 2
),
ev_after as (
  select
    la.client_id, la.ad_set,
    count(*) filter (where e.event_type = 'attendance') as attendance,
    count(*) filter (where e.event_type = 'sale' and e.product = 'preview') as prev_buy,
    count(*) filter (where e.event_type = 'sale' and e.product = 'middle')  as mid_buy,
    sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.event_type = 'sale' and e.product = 'preview') as prev_rev,
    sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.event_type = 'sale' and e.product = 'middle')  as mid_rev
  from v_events e
  join lead_audience la
    on la.client_id = e.client_id and la.contact_id = e.contact_id
  where e.event_type <> 'lead'
  group by la.client_id, la.ad_set
),
ev as (
  select
    coalesce(l.client_id, a.client_id) as client_id,
    coalesce(l.ad_set, a.ad_set)       as ad_set,
    l.leads, a.attendance, a.prev_buy, a.mid_buy, a.prev_rev, a.mid_rev
  from ev_leads l
  full join ev_after a on a.client_id = l.client_id and a.ad_set = l.ad_set
),
cut as (
  select
    coalesce(ads.client_id, ev.client_id) as client_id,
    case when ads.ad_set is null and ev.ad_set is null then '(unsplit)'
         else coalesce(ads.ad_set, ev.ad_set) end as ad_set,
    ads.spend, ads.reach, ads.impressions, ads.clicks, ads.ad_rows,
    ev.leads, ev.attendance, ev.prev_buy, ev.mid_buy, ev.prev_rev, ev.mid_rev
  from ads
  full join ev on ev.client_id = ads.client_id and ev.ad_set = ads.ad_set
),
rolled as (
  select client_id, ad_set,
         sum(spend)::numeric      as spend,
         sum(reach)::bigint       as reach,
         sum(impressions)::bigint as impressions,
         sum(clicks)::bigint      as clicks,
         sum(ad_rows)::bigint     as ad_rows,
         sum(leads)::bigint       as leads,
         sum(attendance)::bigint  as attendance,
         sum(prev_buy)::bigint    as prev_buy,
         sum(mid_buy)::bigint     as mid_buy,
         sum(prev_rev)::numeric   as prev_rev,
         sum(mid_rev)::numeric    as mid_rev
  from cut group by client_id, ad_set
)
select
  r.client_id,
  r.ad_set                                                  as cut_key,
  case when r.ad_set = '(unsplit)' then 'Unsplit spend' else r.ad_set end as cut_label,
  case when r.ad_set = '(unsplit)'
       then 'paid, no ad set recorded' end                  as cut_sub,
  fo_metrics(
    coalesce(r.ad_rows, 0) > 0,
    r.spend,
    -- Delivery has no subject in the bucket that means "audience unknown".
    -- Passing NULL blanks reach, impressions, clicks and — because SQL
    -- arithmetic propagates NULL — Frequency, CTR, Lead Gen %, CPM and CPC
    -- along with them, without any of those needing to be special-cased.
    case when r.ad_set <> '(unsplit)' then r.reach       end,
    case when r.ad_set <> '(unsplit)' then r.impressions end,
    case when r.ad_set <> '(unsplit)' then r.clicks      end,
    coalesce(r.leads, 0), coalesce(r.attendance, 0),
    case when s.client_id is not null then coalesce(r.prev_buy, 0) end,
    case when s.client_id is not null then coalesce(r.mid_buy,  0) end,
    case when s.client_id is not null then coalesce(r.prev_rev, 0) end,
    case when s.client_id is not null then coalesce(r.mid_rev,  0) end,
    p.preview_price, p.middle_price
  ) as m,
  case when r.ad_set = '(unsplit)' then -1 else coalesce(r.spend, 0) end as sort_spend,
  row_number() over (
    partition by r.client_id
    order by
      case when r.ad_set = '(unsplit)' then 1 else 0 end,
      coalesce(r.spend, 0) desc,
      coalesce(r.leads, 0) desc,
      r.ad_set
  )::int                                                    as ord
from rolled r
left join v_sales_seen s on s.client_id = r.client_id
left join v_client_prices p on p.client_id = r.client_id
order by 1, ord;

grant select on v_metrics_by_adset to anon, authenticated;

-- ══════════════════════════════════════════════════════════════════════════
-- 0014_import_status_is_one_row.sql
-- ══════════════════════════════════════════════════════════════════════════

-- ═══════════════════════════════════════════════════════════════════════════
-- THE IMPORT TAB SHOULD DESCRIBE THE LAST IMPORT, NOT EVERY ATTEMPT AT ONE.
--
-- v_import_status read `from import_batches` with no filter and no grouping,
-- so it returned every batch a client had ever produced — one row per source
-- was the intent, nine rows was the result:
--
--     ads         committed   03:11
--     ads         committed   03:28
--     attendance  DISCARDED   03:13     <-- an import that was cancelled
--     attendance  committed   03:13
--     attendance  committed   03:28
--     ...
--
-- Two things wrong with that, and the second is the serious one.
--
--   Which row wins is undefined. The Import tab and the header staleness pills
--   both read this view and take what arrives first. PostgREST does not promise
--   a view's own ORDER BY survives, so "Last import" could name an older batch
--   than the one whose rows are actually in the database.
--
--   A DISCARDED batch is reported as an import. Someone drops a file, reads the
--   diff, decides it is wrong and presses Discard — and the tab then tells them
--   that source was imported, with that file's row count and coverage. The one
--   action whose entire meaning is "this did not happen" was being recorded as
--   though it had. v_column_map already filtered on status; this view did not.
--
-- Now: one row per client and source, the newest COMMITTED batch, chosen by
-- distinct on rather than by hope.
--
-- ─── And a second fix, to what "stale" means ───────────────────────────────
--
-- It was: the last import is older than twice its expected cadence. Since the
-- cadence is written as '1 day' for every source, that reduced to "nothing has
-- been imported in the last two days" — which for an account whose most recent
-- round ended in May is true, permanent, and useless. The header read
--
--     Ads 2d stale · Attendance 2d stale · Leads 2d stale · Sales 2d stale
--
-- on a database whose figures were completely up to date. Four warnings that
-- are always on are the same as no warning at all, and they crowd out the one
-- that matters.
--
-- Stale now means: THIS SOURCE STOPS BEFORE THE ROUNDS DO. A source is stale
-- when its coverage ends before the last round that has already finished — that
-- is, when there is a round on the books for which we are missing data. Time
-- passing is not the signal; missing data is.
--
-- On the current database that turns four permanent warnings into one true one:
-- sales covers to 20 May while rounds run to 27 May, so 0526-03 has no sales
-- data — which is exactly the thing worth saying, and it was invisible before
-- because everything was shouting.
--
-- days_since is kept as it was, for the "3 days ago" label. It is a fact about
-- the clock and makes no claim.
--
-- Requires 0005 (status column). Replaces one view; no table is touched.
-- ═══════════════════════════════════════════════════════════════════════════

create or replace view v_import_status as
with latest as (
  -- one batch per source: the most recent one that actually landed
  select distinct on (client_id, source)
    client_id, source, imported_at, coverage_start, coverage_end,
    row_count, column_map, expected_cadence, stale_flag
  from import_batches
  where status = 'committed'
  order by client_id, source, imported_at desc
),
-- The last round that has already ended. A round still running is not evidence
-- of missing data — its files are not due yet.
horizon as (
  select client_id, max(end_date) as covered_through
  from rounds
  where end_date <= current_date
  group by client_id
)
select
  l.client_id, l.source, l.imported_at, l.coverage_start, l.coverage_end,
  l.row_count, l.column_map, l.expected_cadence,
  -- stale_flag stays respected: a batch explicitly marked stale is stale
  -- whatever the dates say.
  l.stale_flag
    or l.coverage_end is null
    or (h.covered_through is not null and l.coverage_end < h.covered_through)
    as is_stale,
  extract(day from now() - l.imported_at)::int as days_since
from latest l
left join horizon h on h.client_id = l.client_id
order by l.client_id, l.source;

grant select on v_import_status to anon, authenticated;

-- ══════════════════════════════════════════════════════════════════════════
-- 0015_wire_the_stage_tabs.sql
-- ══════════════════════════════════════════════════════════════════════════

-- ═══════════════════════════════════════════════════════════════════════════
-- THE JOURNEY-STAGE TABS, WIRED TO THE CUTS THE JOURNEY CONFIG ALREADY NAMES.
--
-- client_journey_config has carried a compare_dimension for every stage since
-- Sprint 2. Five of them had no view behind them, so the tabs said "not wired
-- yet" while the database already knew what they were supposed to cut by:
--
--     ads       ads_performance.ad        the creative
--     lp        (none)                    <- still nothing to cut by
--     class     rounds.session_label      Class A vs Class B
--     preview   events.round_id           rounds, preview offer only
--     middle    events.round_id           rounds, middle offer only
--
-- Landing page stays unwired, and deliberately. Its compare_dimension is null —
-- no dimension has been decided and no column exists to hold one. Guessing it
-- would put a number on screen that nobody chose.
--
-- Plus "This round", which is not a journey stage: the newest round that has
-- started, next to the one before it.
--
-- Every view here builds its columns with the same fo_metrics call as By round,
-- so a metric cannot mean one thing on one tab and something else on another,
-- and none of them touch a table. Requires 0013.
-- ═══════════════════════════════════════════════════════════════════════════

-- ═══════════════════════════════════════════════════════════════════════════
-- ADS — the creative, not the audience.
--
-- Same bridge as Targeted views, one level down: events.ad against
-- ads_performance.ad. The people half is real — 18 creatives arrive on leads
-- from GoHighLevel's utm_content. The money half is empty, because the Meta
-- export we have is at ad-set level and its ad column is null on all 62 rows,
-- so every dollar lands in Unsplit spend until an ad-level export exists.
--
-- That is worth showing rather than hiding. "Which creative produced the most
-- leads" is answerable today; "what did it cost" is not, and a dash says so.
--
-- 17 leads carry a numeric Ad ID instead of a name, because a second tracking
-- template passes utm_content={{ad.id}}. They get their own columns rather than
-- being merged or dropped — an ID is a better join key than a name, and this is
-- where they resolve when ad-level spend arrives.
-- ═══════════════════════════════════════════════════════════════════════════
create or replace view v_metrics_by_ad as
with ads as (
  select client_id, nullif(btrim(ad), '') as ad,
         sum(spend) as spend, sum(reach) as reach,
         sum(impressions) as impressions, sum(clicks) as clicks,
         count(*) as ad_rows
  from v_ads group by client_id, nullif(btrim(ad), '')
),
-- the creative that ACQUIRED each person: their earliest lead carrying one
lead_ad as (
  select distinct on (client_id, contact_id)
         client_id, contact_id,
         coalesce(nullif(btrim(ad), ''),
                  case when source = 'Paid Ads' then '(unsplit)' end) as ad
  from v_events
  where event_type = 'lead' and contact_id is not null
    and (nullif(btrim(ad), '') is not null or source = 'Paid Ads')
  order by client_id, contact_id, event_date
),
-- a lead counts on its OWN creative; only later events need the detour
ev_leads as (
  select client_id,
         coalesce(nullif(btrim(ad), ''),
                  case when source = 'Paid Ads' then '(unsplit)' end) as ad,
         count(*) as leads
  from v_events
  where event_type = 'lead'
    and (nullif(btrim(ad), '') is not null or source = 'Paid Ads')
  group by 1, 2
),
ev_after as (
  select la.client_id, la.ad,
    count(*) filter (where e.event_type = 'attendance') as attendance,
    count(*) filter (where e.event_type = 'sale' and e.product = 'preview') as prev_buy,
    count(*) filter (where e.event_type = 'sale' and e.product = 'middle')  as mid_buy,
    sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.event_type = 'sale' and e.product = 'preview') as prev_rev,
    sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.event_type = 'sale' and e.product = 'middle')  as mid_rev
  from v_events e
  join lead_ad la on la.client_id = e.client_id and la.contact_id = e.contact_id
  where e.event_type <> 'lead'
  group by la.client_id, la.ad
),
ev as (
  select coalesce(l.client_id, a.client_id) as client_id,
         coalesce(l.ad, a.ad)               as ad,
         l.leads, a.attendance, a.prev_buy, a.mid_buy, a.prev_rev, a.mid_rev
  from ev_leads l
  full join ev_after a on a.client_id = l.client_id and a.ad = l.ad
),
cut as (
  select coalesce(ads.client_id, ev.client_id) as client_id,
         case when ads.ad is null and ev.ad is null then '(unsplit)'
              else coalesce(ads.ad, ev.ad) end as ad,
         ads.spend, ads.reach, ads.impressions, ads.clicks, ads.ad_rows,
         ev.leads, ev.attendance, ev.prev_buy, ev.mid_buy, ev.prev_rev, ev.mid_rev
  from ads full join ev on ev.client_id = ads.client_id and ev.ad = ads.ad
),
rolled as (
  select client_id, ad,
         sum(spend)::numeric as spend, sum(reach)::bigint as reach,
         sum(impressions)::bigint as impressions, sum(clicks)::bigint as clicks,
         sum(ad_rows)::bigint as ad_rows, sum(leads)::bigint as leads,
         sum(attendance)::bigint as attendance, sum(prev_buy)::bigint as prev_buy,
         sum(mid_buy)::bigint as mid_buy, sum(prev_rev)::numeric as prev_rev,
         sum(mid_rev)::numeric as mid_rev
  from cut group by client_id, ad
)
select
  r.client_id,
  r.ad                                                        as cut_key,
  case when r.ad = '(unsplit)' then 'Unsplit spend' else r.ad end as cut_label,
  case when r.ad = '(unsplit)' then 'paid, no ad recorded'
       when r.ad ~ '^[0-9]+$' then 'Ad ID, no name in the export' end as cut_sub,
  fo_metrics(
    coalesce(r.ad_rows, 0) > 0,
    r.spend,
    -- same rule as 0013: delivery has no subject in the unattributable bucket
    case when r.ad <> '(unsplit)' then r.reach       end,
    case when r.ad <> '(unsplit)' then r.impressions end,
    case when r.ad <> '(unsplit)' then r.clicks      end,
    coalesce(r.leads, 0), coalesce(r.attendance, 0),
    case when s.client_id is not null then coalesce(r.prev_buy, 0) end,
    case when s.client_id is not null then coalesce(r.mid_buy,  0) end,
    case when s.client_id is not null then coalesce(r.prev_rev, 0) end,
    case when s.client_id is not null then coalesce(r.mid_rev,  0) end,
    p.preview_price, p.middle_price
  ) as m,
  row_number() over (
    partition by r.client_id
    order by case when r.ad = '(unsplit)' then 1 else 0 end,
             coalesce(r.leads, 0) desc, coalesce(r.spend, 0) desc, r.ad
  )::int as ord
from rolled r
left join v_sales_seen s on s.client_id = r.client_id
left join v_client_prices p on p.client_id = r.client_id
order by 1, ord;

grant select on v_metrics_by_ad to anon, authenticated;

-- ═══════════════════════════════════════════════════════════════════════════
-- ATTEND CLASS — rounds grouped by session_label, Class A against Class B.
--
-- Spend is kept, not blanked. A class variant does not buy traffic itself, but
-- the rounds that ran it did, and cost per attendee by class is the entire
-- reason this comparison is worth having: the old sheet protected the class
-- format and could not see what it cost. Reach is summed across the label's
-- rounds and double-counts anyone in both, exactly as it does on By month and
-- in every Total column — Meta only reports reach per query.
--
-- Both of Shely's May rounds are Class A, so this renders one column today and
-- splits the moment a Class B round is imported. One column is the true answer,
-- not a broken one.
-- ═══════════════════════════════════════════════════════════════════════════
create or replace view v_metrics_by_session as
with labels as (
  select client_id, coalesce(nullif(btrim(session_label), ''), '(unlabelled)') as label,
         count(*)::int as round_count, min(start_date) as first_start
  from rounds group by 1, 2
),
ads as (
  select r.client_id, coalesce(nullif(btrim(r.session_label), ''), '(unlabelled)') as label,
         sum(a.spend) as spend, sum(a.reach) as reach,
         sum(a.impressions) as impressions, sum(a.clicks) as clicks, count(*) as ad_rows
  from v_ads a join rounds r on r.round_id = a.round_id group by 1, 2
),
ev as (
  select r.client_id, coalesce(nullif(btrim(r.session_label), ''), '(unlabelled)') as label,
         count(*) filter (where e.event_type = 'lead')       as leads,
         count(*) filter (where e.event_type = 'attendance') as attendance
  from v_events e join rounds r on r.round_id = e.round_id group by 1, 2
),
sales as (
  select r.client_id, coalesce(nullif(btrim(r.session_label), ''), '(unlabelled)') as label,
         count(*) filter (where e.product = 'preview') as prev_buy,
         count(*) filter (where e.product = 'middle')  as mid_buy,
         sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.product = 'preview') as prev_rev,
         sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.product = 'middle')  as mid_rev
  from v_events e join rounds r on r.round_id = e.lead_round_id
  where e.event_type = 'sale' and e.lead_round_id is not null
  group by 1, 2
)
select
  l.client_id,
  l.label                                                     as cut_key,
  l.label                                                     as cut_label,
  l.round_count || ' round' || case when l.round_count = 1 then '' else 's' end as cut_sub,
  fo_metrics(
    coalesce(ads.ad_rows, 0) > 0,
    ads.spend, ads.reach, ads.impressions, ads.clicks,
    coalesce(ev.leads, 0), coalesce(ev.attendance, 0),
    case when s.client_id is not null then coalesce(sales.prev_buy, 0) end,
    case when s.client_id is not null then coalesce(sales.mid_buy,  0) end,
    case when s.client_id is not null then coalesce(sales.prev_rev, 0) end,
    case when s.client_id is not null then coalesce(sales.mid_rev,  0) end,
    p.preview_price, p.middle_price
  ) as m,
  row_number() over (partition by l.client_id order by l.first_start, l.label)::int as ord
from labels l
left join ads   on ads.client_id   = l.client_id and ads.label   = l.label
left join ev    on ev.client_id    = l.client_id and ev.label    = l.label
left join sales on sales.client_id = l.client_id and sales.label = l.label
left join v_sales_seen s    on s.client_id = l.client_id
left join v_client_prices p on p.client_id = l.client_id
order by 1, ord;

grant select on v_metrics_by_session to anon, authenticated;

-- ═══════════════════════════════════════════════════════════════════════════
-- PREVIEW OFFER and MIDDLE OFFER — rounds across, one offer at a time.
--
-- Same columns as By round. The difference is which offer's rows are filled:
-- on Preview the middle rows are NULL and on Middle the preview rows are, so
-- the take-up and ROAS lines read for the offer the tab is named after and
-- nothing else competes for attention.
--
-- NULL and not zero, deliberately. A round with no middle purchases and a round
-- whose middle numbers are simply not this tab's subject are different things,
-- and only one of them is a measurement. Both tabs' totals still agree with By
-- round because they are the same rows, filtered rather than recomputed.
--
-- Built as one view with a `product` column so the two tabs cannot drift apart.
-- ═══════════════════════════════════════════════════════════════════════════
create or replace view v_metrics_by_offer as
with offers as (select unnest(array['preview', 'middle']) as product),
ads as (
  select client_id, round_id, sum(spend) as spend, sum(reach) as reach,
         sum(impressions) as impressions, sum(clicks) as clicks, count(*) as ad_rows
  from v_ads group by 1, 2
),
ev as (
  select client_id, round_id,
         count(*) filter (where event_type = 'lead')       as leads,
         count(*) filter (where event_type = 'attendance') as attendance
  from v_events group by 1, 2
),
sales as (
  select client_id, lead_round_id as round_id, product,
         count(*) as buys,
         sum(amount - coalesce(refund_amount, 0)) as rev
  from v_events
  where event_type = 'sale' and lead_round_id is not null and product is not null
  group by 1, 2, 3
)
select
  r.client_id,
  o.product,
  r.round_id                                  as cut_key,
  r.round_id                                  as cut_label,
  to_char(r.start_date, 'Mon DD') || ' – ' || to_char(r.end_date, 'DD') as cut_sub,
  r.start_date,
  fo_metrics(
    coalesce(ads.ad_rows, 0) > 0,
    ads.spend, ads.reach, ads.impressions, ads.clicks,
    coalesce(ev.leads, 0), coalesce(ev.attendance, 0),
    -- only this tab's offer carries numbers; the other is absent, not zero
    case when o.product = 'preview' and s.client_id is not null then coalesce(sp.buys, 0) end,
    case when o.product = 'middle'  and s.client_id is not null then coalesce(sm.buys, 0) end,
    case when o.product = 'preview' and s.client_id is not null then coalesce(sp.rev,  0) end,
    case when o.product = 'middle'  and s.client_id is not null then coalesce(sm.rev,  0) end,
    p.preview_price, p.middle_price
  ) as m
from rounds r
cross join offers o
left join ads on ads.client_id = r.client_id and ads.round_id = r.round_id
left join ev  on ev.client_id  = r.client_id and ev.round_id  = r.round_id
left join sales sp on sp.client_id = r.client_id and sp.round_id = r.round_id and sp.product = 'preview'
left join sales sm on sm.client_id = r.client_id and sm.round_id = r.round_id and sm.product = 'middle'
left join v_sales_seen s    on s.client_id = r.client_id
left join v_client_prices p on p.client_id = r.client_id
order by r.client_id, o.product, r.start_date;

grant select on v_metrics_by_offer to anon, authenticated;

-- ═══════════════════════════════════════════════════════════════════════════
-- THIS ROUND — the newest round that has started, beside the one before it.
--
-- "While it runs" is the intent, but a tab that empties itself the day a round
-- ends is a tab nobody trusts. The rule is the newest round whose start_date
-- has passed, which IS the live one while a round is running and is the one
-- just finished otherwise — and the previous round alongside it, because a
-- single number with nothing to compare it to is not analysis.
--
-- Rounds that have not started yet are excluded: a scheduled round has no
-- figures, and putting it here would answer "how is it going" with a blank.
-- ═══════════════════════════════════════════════════════════════════════════
create or replace view v_metrics_this_round as
select
  client_id, cut_key, cut_label, cut_sub, start_date, m,
  case when rn = 1 then 'this round' else 'previous' end as period,
  rn::int as ord
from (
  select b.*, row_number() over (partition by b.client_id order by b.start_date desc) as rn
  from v_metrics_by_round b
  join rounds r on r.round_id = b.cut_key
  where r.start_date <= current_date
) ranked
where rn <= 2
order by client_id, start_date;

grant select on v_metrics_this_round to anon, authenticated;

-- ══════════════════════════════════════════════════════════════════════════
-- 0016_reach_is_not_additive.sql
-- ══════════════════════════════════════════════════════════════════════════

-- ═══════════════════════════════════════════════════════════════════════════
-- REACH IS DEDUPLICATED PEOPLE, SO IT IS TAKEN FROM THE COARSEST ROW AVAILABLE
-- RATHER THAN ADDED UP.
--
-- Every other number in ads_performance is additive. Reach is not: it counts
-- distinct people, and the same person is reached by more than one ad set. The
-- May export proves the size of it —
--
--     DF_SG_Preview_Sprint1_0526_02   its six ad sets sum to  20,665
--                                     the campaign's own row   11,380
--
-- — so adding the ad-set rows overstates by 82%, and drags Frequency with it.
--
-- Until now the app avoided this by simply not having per-ad-set reach: the
-- daily export could not give a usable one, so reach entered on two hand-built
-- rows carrying the round totals and every audience showed a dash. The
-- period-level export changes that. Each ad set now has a real, deduplicated
-- reach for its own audience — 4,083 for Cold_Broad in 0526-02 — which is worth
-- having, and which must not be summed.
--
-- The rule, applied wherever rounds are rolled up:
--
--     A row that names no ad set is a COARSER measurement — a campaign or
--     account line. Where such rows exist they are the reach, because they are
--     already deduplicated across everything below them. Only when none exists
--     does the app fall back to adding the ad-set rows, and that sum is an
--     over-count it has no way to avoid.
--
-- Impressions, clicks and spend keep summing, because they are counts of events
-- rather than of people and adding them is correct.
--
-- Note this does NOT make a round's reach right when two campaigns ran in it —
-- 0526-03's two campaigns report 7,902 and 4,863 and the true figure is 10,131,
-- because the same person saw both. No per-campaign export can produce that; it
-- takes a query at the level you want the answer for. That is what the ads
-- file's round-level correction rows are, and why they still exist.
--
-- Requires 0015. Replaces four views; no table is touched.
-- ═══════════════════════════════════════════════════════════════════════════

-- ═══════════════════════════════════════════════════════════════════════════
-- BY ROUND
-- ═══════════════════════════════════════════════════════════════════════════
create or replace view v_metrics_by_round as
with ads as (
  select client_id, round_id,
         sum(spend) as spend,
         coalesce(sum(reach) filter (where nullif(btrim(ad_set), '') is null),
                  sum(reach)) as reach,
         sum(impressions) as impressions, sum(clicks) as clicks,
         count(*) as ad_rows
  from v_ads group by client_id, round_id
),
ev as (
  select client_id, round_id,
         count(*) filter (where event_type = 'lead')       as leads,
         count(*) filter (where event_type = 'attendance') as attendance
  from v_events group by client_id, round_id
),
sales as (
  select client_id, lead_round_id as round_id,
         count(*) filter (where product = 'preview')                     as prev_buy,
         count(*) filter (where product = 'middle')                      as mid_buy,
         sum(amount - coalesce(refund_amount, 0)) filter (where product = 'preview') as prev_rev,
         sum(amount - coalesce(refund_amount, 0)) filter (where product = 'middle')  as mid_rev
  from v_events where event_type = 'sale' and lead_round_id is not null
  group by client_id, lead_round_id
)
select
  r.client_id,
  r.round_id                                  as cut_key,
  r.round_id                                  as cut_label,
  to_char(r.start_date, 'Mon DD') || ' – ' || to_char(r.end_date, 'DD') as cut_sub,
  r.start_date,
  fo_metrics(
    coalesce(ads.ad_rows, 0) > 0,
    ads.spend, ads.reach::bigint, ads.impressions, ads.clicks,
    coalesce(ev.leads, 0), coalesce(ev.attendance, 0),
    case when s.client_id is not null then coalesce(sales.prev_buy, 0) end,
    case when s.client_id is not null then coalesce(sales.mid_buy,  0) end,
    case when s.client_id is not null then coalesce(sales.prev_rev, 0) end,
    case when s.client_id is not null then coalesce(sales.mid_rev,  0) end,
    p.preview_price, p.middle_price
  ) as m
from rounds r
left join ads   on ads.client_id = r.client_id and ads.round_id = r.round_id
left join ev    on ev.client_id  = r.client_id and ev.round_id  = r.round_id
left join sales on sales.client_id = r.client_id and sales.round_id = r.round_id
left join v_sales_seen s on s.client_id = r.client_id
left join v_client_prices p on p.client_id = r.client_id
order by r.client_id, r.start_date;

grant select on v_metrics_by_round to anon, authenticated;

-- ═══════════════════════════════════════════════════════════════════════════
-- CLIENT TOTAL
-- ═══════════════════════════════════════════════════════════════════════════
create or replace view v_metrics_total as
with ads as (
  select client_id, sum(spend) as spend,
         coalesce(sum(reach) filter (where nullif(btrim(ad_set), '') is null),
                  sum(reach)) as reach,
         sum(impressions) as impressions, sum(clicks) as clicks, count(*) as ad_rows
  from v_ads group by client_id
),
ev as (
  select client_id,
         count(*) filter (where event_type = 'lead')       as leads,
         count(*) filter (where event_type = 'attendance') as attendance,
         count(*) filter (where event_type = 'sale' and product = 'preview') as prev_buy,
         count(*) filter (where event_type = 'sale' and product = 'middle')  as mid_buy,
         sum(amount - coalesce(refund_amount, 0)) filter (where event_type = 'sale' and product = 'preview') as prev_rev,
         sum(amount - coalesce(refund_amount, 0)) filter (where event_type = 'sale' and product = 'middle')  as mid_rev
  from v_events group by client_id
)
select
  c.client_id,
  'TOTAL'::text as cut_key,
  'Total'::text as cut_label,
  'all rounds'::text as cut_sub,
  fo_metrics(
    coalesce(ads.ad_rows, 0) > 0,
    ads.spend, ads.reach::bigint, ads.impressions, ads.clicks,
    coalesce(ev.leads, 0), coalesce(ev.attendance, 0),
    case when s.client_id is not null then coalesce(ev.prev_buy, 0) end,
    case when s.client_id is not null then coalesce(ev.mid_buy,  0) end,
    case when s.client_id is not null then coalesce(ev.prev_rev, 0) end,
    case when s.client_id is not null then coalesce(ev.mid_rev,  0) end,
    p.preview_price, p.middle_price
  ) as m
from v_clients c
left join ads on ads.client_id = c.client_id
left join ev  on ev.client_id  = c.client_id
left join v_sales_seen s on s.client_id = c.client_id
left join v_client_prices p on p.client_id = c.client_id;

grant select on v_metrics_total to anon, authenticated;

-- ═══════════════════════════════════════════════════════════════════════════
-- BY MONTH
-- ═══════════════════════════════════════════════════════════════════════════
create or replace view v_metrics_by_month as
with months as (
  select client_id, date_trunc('month', start_date)::date as month_start,
         count(*)::int as round_count
  from rounds group by 1, 2
),
ads as (
  select r.client_id, date_trunc('month', r.start_date)::date as month_start,
         sum(a.spend) as spend,
         coalesce(sum(a.reach) filter (where nullif(btrim(a.ad_set), '') is null),
                  sum(a.reach)) as reach,
         sum(a.impressions) as impressions, sum(a.clicks) as clicks, count(*) as ad_rows
  from v_ads a join rounds r on r.round_id = a.round_id group by 1, 2
),
ev as (
  select r.client_id, date_trunc('month', r.start_date)::date as month_start,
         count(*) filter (where e.event_type = 'lead')       as leads,
         count(*) filter (where e.event_type = 'attendance') as attendance
  from v_events e join rounds r on r.round_id = e.round_id group by 1, 2
),
sales as (
  select r.client_id, date_trunc('month', r.start_date)::date as month_start,
         count(*) filter (where e.product = 'preview') as prev_buy,
         count(*) filter (where e.product = 'middle')  as mid_buy,
         sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.product = 'preview') as prev_rev,
         sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.product = 'middle')  as mid_rev
  from v_events e join rounds r on r.round_id = e.lead_round_id
  where e.event_type = 'sale' and e.lead_round_id is not null
  group by 1, 2
)
select
  m.client_id,
  to_char(m.month_start, 'YYYY-MM')  as cut_key,
  to_char(m.month_start, 'Mon YYYY') as cut_label,
  m.round_count || ' round' || case when m.round_count = 1 then '' else 's' end as cut_sub,
  m.month_start,
  fo_metrics(
    coalesce(ads.ad_rows, 0) > 0,
    ads.spend, ads.reach::bigint, ads.impressions, ads.clicks,
    coalesce(ev.leads, 0), coalesce(ev.attendance, 0),
    case when s.client_id is not null then coalesce(sales.prev_buy, 0) end,
    case when s.client_id is not null then coalesce(sales.mid_buy,  0) end,
    case when s.client_id is not null then coalesce(sales.prev_rev, 0) end,
    case when s.client_id is not null then coalesce(sales.mid_rev,  0) end,
    p.preview_price, p.middle_price
  ) as m
from months m
left join ads   on ads.client_id   = m.client_id and ads.month_start   = m.month_start
left join ev    on ev.client_id    = m.client_id and ev.month_start    = m.month_start
left join sales on sales.client_id = m.client_id and sales.month_start = m.month_start
left join v_sales_seen s    on s.client_id = m.client_id
left join v_client_prices p on p.client_id = m.client_id
order by m.client_id, m.month_start;

grant select on v_metrics_by_month to anon, authenticated;

-- ═══════════════════════════════════════════════════════════════════════════
-- ATTEND CLASS
-- ═══════════════════════════════════════════════════════════════════════════
create or replace view v_metrics_by_session as
with labels as (
  select client_id, coalesce(nullif(btrim(session_label), ''), '(unlabelled)') as label,
         count(*)::int as round_count, min(start_date) as first_start
  from rounds group by 1, 2
),
ads as (
  select r.client_id, coalesce(nullif(btrim(r.session_label), ''), '(unlabelled)') as label,
         sum(a.spend) as spend,
         coalesce(sum(a.reach) filter (where nullif(btrim(a.ad_set), '') is null),
                  sum(a.reach)) as reach,
         sum(a.impressions) as impressions, sum(a.clicks) as clicks, count(*) as ad_rows
  from v_ads a join rounds r on r.round_id = a.round_id group by 1, 2
),
ev as (
  select r.client_id, coalesce(nullif(btrim(r.session_label), ''), '(unlabelled)') as label,
         count(*) filter (where e.event_type = 'lead')       as leads,
         count(*) filter (where e.event_type = 'attendance') as attendance
  from v_events e join rounds r on r.round_id = e.round_id group by 1, 2
),
sales as (
  select r.client_id, coalesce(nullif(btrim(r.session_label), ''), '(unlabelled)') as label,
         count(*) filter (where e.product = 'preview') as prev_buy,
         count(*) filter (where e.product = 'middle')  as mid_buy,
         sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.product = 'preview') as prev_rev,
         sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.product = 'middle')  as mid_rev
  from v_events e join rounds r on r.round_id = e.lead_round_id
  where e.event_type = 'sale' and e.lead_round_id is not null
  group by 1, 2
)
select
  l.client_id,
  l.label as cut_key,
  l.label as cut_label,
  l.round_count || ' round' || case when l.round_count = 1 then '' else 's' end as cut_sub,
  fo_metrics(
    coalesce(ads.ad_rows, 0) > 0,
    ads.spend, ads.reach::bigint, ads.impressions, ads.clicks,
    coalesce(ev.leads, 0), coalesce(ev.attendance, 0),
    case when s.client_id is not null then coalesce(sales.prev_buy, 0) end,
    case when s.client_id is not null then coalesce(sales.mid_buy,  0) end,
    case when s.client_id is not null then coalesce(sales.prev_rev, 0) end,
    case when s.client_id is not null then coalesce(sales.mid_rev,  0) end,
    p.preview_price, p.middle_price
  ) as m,
  row_number() over (partition by l.client_id order by l.first_start, l.label)::int as ord
from labels l
left join ads   on ads.client_id   = l.client_id and ads.label   = l.label
left join ev    on ev.client_id    = l.client_id and ev.label    = l.label
left join sales on sales.client_id = l.client_id and sales.label = l.label
left join v_sales_seen s    on s.client_id = l.client_id
left join v_client_prices p on p.client_id = l.client_id
order by 1, ord;

grant select on v_metrics_by_session to anon, authenticated;

-- ═══════════════════════════════════════════════════════════════════════════
-- AND ZERO SPEND IN THE UNSPLIT BUCKET IS NOT FREE LEADS.
--
-- The bucket that means "we cannot say which audience" now collects the
-- round-level reach rows, which carry no spend of their own. sum() of nothing
-- but zeroes is 0, so the column read
--
--     Unsplit spend    spend 0.00    leads 9    CPL 0.00
--
-- and CPL 0.00 says those nine leads were free. They were not; nobody knows
-- what they cost, which is the entire reason they are in this bucket.
--
-- Exactly-zero spend here becomes NULL, and CPL, CPA and ROAS blank themselves
-- with it. Real unsplit spend — a campaign exported without an ad-set
-- breakdown — is a positive number and still shows, which is the case this
-- column was built for. Same rule as 0013, applied to the one metric it left.
-- ═══════════════════════════════════════════════════════════════════════════

create or replace view v_metrics_by_adset as
with ads as (
  select client_id, nullif(btrim(ad_set), '') as ad_set,
         sum(spend) as spend, sum(reach) as reach,
         sum(impressions) as impressions, sum(clicks) as clicks,
         count(*) as ad_rows
  from v_ads group by client_id, nullif(btrim(ad_set), '')
),
-- The audience that ACQUIRED each person: the earliest lead of theirs carrying
-- one. Paid leads with no audience resolve to the unsplit bucket rather than to
-- nothing, so their attendance and purchases stay attached to paid money.
lead_audience as (
  select distinct on (client_id, contact_id)
         client_id, contact_id,
         coalesce(nullif(btrim(ad_set), ''),
                  case when source = 'Paid Ads' then '(unsplit)' end) as ad_set
  from v_events
  where event_type = 'lead'
    and contact_id is not null
    and (nullif(btrim(ad_set), '') is not null or source = 'Paid Ads')
  order by client_id, contact_id, event_date
),
-- A LEAD counts on its OWN audience, not on the acquiring lead's. The two
-- differ for anyone who opted in twice, and routing those through the first
-- audience inflates the lead total — that second opt-in really did come from
-- the second ad set. It is the events with no tag of their own that need the
-- detour.
ev_leads as (
  select client_id,
         coalesce(nullif(btrim(ad_set), ''),
                  case when source = 'Paid Ads' then '(unsplit)' end) as ad_set,
         count(*) as leads
  from v_events
  where event_type = 'lead'
    and (nullif(btrim(ad_set), '') is not null or source = 'Paid Ads')
  group by 1, 2
),
ev_after as (
  select
    la.client_id, la.ad_set,
    count(*) filter (where e.event_type = 'attendance') as attendance,
    count(*) filter (where e.event_type = 'sale' and e.product = 'preview') as prev_buy,
    count(*) filter (where e.event_type = 'sale' and e.product = 'middle')  as mid_buy,
    sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.event_type = 'sale' and e.product = 'preview') as prev_rev,
    sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.event_type = 'sale' and e.product = 'middle')  as mid_rev
  from v_events e
  join lead_audience la
    on la.client_id = e.client_id and la.contact_id = e.contact_id
  where e.event_type <> 'lead'
  group by la.client_id, la.ad_set
),
ev as (
  select
    coalesce(l.client_id, a.client_id) as client_id,
    coalesce(l.ad_set, a.ad_set)       as ad_set,
    l.leads, a.attendance, a.prev_buy, a.mid_buy, a.prev_rev, a.mid_rev
  from ev_leads l
  full join ev_after a on a.client_id = l.client_id and a.ad_set = l.ad_set
),
cut as (
  select
    coalesce(ads.client_id, ev.client_id) as client_id,
    case when ads.ad_set is null and ev.ad_set is null then '(unsplit)'
         else coalesce(ads.ad_set, ev.ad_set) end as ad_set,
    ads.spend, ads.reach, ads.impressions, ads.clicks, ads.ad_rows,
    ev.leads, ev.attendance, ev.prev_buy, ev.mid_buy, ev.prev_rev, ev.mid_rev
  from ads
  full join ev on ev.client_id = ads.client_id and ev.ad_set = ads.ad_set
),
rolled as (
  select client_id, ad_set,
         sum(spend)::numeric      as spend,
         sum(reach)::bigint       as reach,
         sum(impressions)::bigint as impressions,
         sum(clicks)::bigint      as clicks,
         sum(ad_rows)::bigint     as ad_rows,
         sum(leads)::bigint       as leads,
         sum(attendance)::bigint  as attendance,
         sum(prev_buy)::bigint    as prev_buy,
         sum(mid_buy)::bigint     as mid_buy,
         sum(prev_rev)::numeric   as prev_rev,
         sum(mid_rev)::numeric    as mid_rev
  from cut group by client_id, ad_set
)
select
  r.client_id,
  r.ad_set                                                  as cut_key,
  case when r.ad_set = '(unsplit)' then 'Unsplit spend' else r.ad_set end as cut_label,
  case when r.ad_set = '(unsplit)'
       then 'paid, no ad set recorded' end                  as cut_sub,
  fo_metrics(
    coalesce(r.ad_rows, 0) > 0,
    -- 0 here means "no spend was recorded against unknown audiences", not
    -- "those leads cost nothing" — see the note above.
    case when r.ad_set = '(unsplit)' then nullif(r.spend, 0) else r.spend end,
    -- Delivery has no subject in the bucket that means "audience unknown".
    -- Passing NULL blanks reach, impressions, clicks and — because SQL
    -- arithmetic propagates NULL — Frequency, CTR, Lead Gen %, CPM and CPC
    -- along with them, without any of those needing to be special-cased.
    case when r.ad_set <> '(unsplit)' then r.reach       end,
    case when r.ad_set <> '(unsplit)' then r.impressions end,
    case when r.ad_set <> '(unsplit)' then r.clicks      end,
    coalesce(r.leads, 0), coalesce(r.attendance, 0),
    case when s.client_id is not null then coalesce(r.prev_buy, 0) end,
    case when s.client_id is not null then coalesce(r.mid_buy,  0) end,
    case when s.client_id is not null then coalesce(r.prev_rev, 0) end,
    case when s.client_id is not null then coalesce(r.mid_rev,  0) end,
    p.preview_price, p.middle_price
  ) as m,
  case when r.ad_set = '(unsplit)' then -1 else coalesce(r.spend, 0) end as sort_spend,
  row_number() over (
    partition by r.client_id
    order by
      case when r.ad_set = '(unsplit)' then 1 else 0 end,
      coalesce(r.spend, 0) desc,
      coalesce(r.leads, 0) desc,
      r.ad_set
  )::int                                                    as ord
from rolled r
left join v_sales_seen s on s.client_id = r.client_id
left join v_client_prices p on p.client_id = r.client_id
order by 1, ord;

grant select on v_metrics_by_adset to anon, authenticated;

-- ══════════════════════════════════════════════════════════════════════════
-- 0017_unsplit_has_no_spend_on_ads.sql
-- ══════════════════════════════════════════════════════════════════════════

-- ═══════════════════════════════════════════════════════════════════════════
-- 0017 — the Ads tab's Unsplit row must not claim it spent nothing.
--
-- 0016 taught v_metrics_by_adset that the (unsplit) bucket has no spend of its
-- own: the rows that land there are correction rows carrying reach and clicks
-- with spend 0.00, and 0.00 is not the same statement as "no spend recorded".
-- Left as 0.00 it also poisons CPL, which divided 0.00 by 9 leads and printed
-- "CPL 0.00" — a cost of nothing, on nine real people.
--
-- v_metrics_by_ad has exactly the same bucket and never got the same fix. Every
-- ad-set row and every round row in the ads file has a null `ad`, so all twenty
-- of them fold into (unsplit) there, and their spends are all 0.00.
--
-- The only change is nullif(spend, 0) on that one bucket, matching 0016 line
-- for line. Reach, impressions and clicks were already blanked in 0015 for the
-- same reason — delivery has no subject when nobody knows which creative it
-- was — so this closes the last column that was still answering.
--
-- Named creatives are untouched: a creative that genuinely spent 0.00 in a
-- round still reports 0.00, because it has ad rows and the bucket test is on
-- the literal '(unsplit)' key, not on the amount.
-- ═══════════════════════════════════════════════════════════════════════════
create or replace view v_metrics_by_ad as
with ads as (
  select client_id, nullif(btrim(ad), '') as ad,
         sum(spend) as spend, sum(reach) as reach,
         sum(impressions) as impressions, sum(clicks) as clicks,
         count(*) as ad_rows
  from v_ads group by client_id, nullif(btrim(ad), '')
),
-- the creative that ACQUIRED each person: their earliest lead carrying one
lead_ad as (
  select distinct on (client_id, contact_id)
         client_id, contact_id,
         coalesce(nullif(btrim(ad), ''),
                  case when source = 'Paid Ads' then '(unsplit)' end) as ad
  from v_events
  where event_type = 'lead' and contact_id is not null
    and (nullif(btrim(ad), '') is not null or source = 'Paid Ads')
  order by client_id, contact_id, event_date
),
-- a lead counts on its OWN creative; only later events need the detour
ev_leads as (
  select client_id,
         coalesce(nullif(btrim(ad), ''),
                  case when source = 'Paid Ads' then '(unsplit)' end) as ad,
         count(*) as leads
  from v_events
  where event_type = 'lead'
    and (nullif(btrim(ad), '') is not null or source = 'Paid Ads')
  group by 1, 2
),
ev_after as (
  select la.client_id, la.ad,
    count(*) filter (where e.event_type = 'attendance') as attendance,
    count(*) filter (where e.event_type = 'sale' and e.product = 'preview') as prev_buy,
    count(*) filter (where e.event_type = 'sale' and e.product = 'middle')  as mid_buy,
    sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.event_type = 'sale' and e.product = 'preview') as prev_rev,
    sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.event_type = 'sale' and e.product = 'middle')  as mid_rev
  from v_events e
  join lead_ad la on la.client_id = e.client_id and la.contact_id = e.contact_id
  where e.event_type <> 'lead'
  group by la.client_id, la.ad
),
ev as (
  select coalesce(l.client_id, a.client_id) as client_id,
         coalesce(l.ad, a.ad)               as ad,
         l.leads, a.attendance, a.prev_buy, a.mid_buy, a.prev_rev, a.mid_rev
  from ev_leads l
  full join ev_after a on a.client_id = l.client_id and a.ad = l.ad
),
cut as (
  select coalesce(ads.client_id, ev.client_id) as client_id,
         case when ads.ad is null and ev.ad is null then '(unsplit)'
              else coalesce(ads.ad, ev.ad) end as ad,
         ads.spend, ads.reach, ads.impressions, ads.clicks, ads.ad_rows,
         ev.leads, ev.attendance, ev.prev_buy, ev.mid_buy, ev.prev_rev, ev.mid_rev
  from ads full join ev on ev.client_id = ads.client_id and ev.ad = ads.ad
),
rolled as (
  select client_id, ad,
         sum(spend)::numeric as spend, sum(reach)::bigint as reach,
         sum(impressions)::bigint as impressions, sum(clicks)::bigint as clicks,
         sum(ad_rows)::bigint as ad_rows, sum(leads)::bigint as leads,
         sum(attendance)::bigint as attendance, sum(prev_buy)::bigint as prev_buy,
         sum(mid_buy)::bigint as mid_buy, sum(prev_rev)::numeric as prev_rev,
         sum(mid_rev)::numeric as mid_rev
  from cut group by client_id, ad
)
select
  r.client_id,
  r.ad                                                        as cut_key,
  case when r.ad = '(unsplit)' then 'Unsplit spend' else r.ad end as cut_label,
  case when r.ad = '(unsplit)' then 'paid, no ad recorded'
       when r.ad ~ '^[0-9]+$' then 'Ad ID, no name in the export' end as cut_sub,
  fo_metrics(
    coalesce(r.ad_rows, 0) > 0,
    -- the one change: 0.00 in this bucket means "not recorded", not "free"
    case when r.ad = '(unsplit)' then nullif(r.spend, 0) else r.spend end,
    -- same rule as 0013: delivery has no subject in the unattributable bucket
    case when r.ad <> '(unsplit)' then r.reach       end,
    case when r.ad <> '(unsplit)' then r.impressions end,
    case when r.ad <> '(unsplit)' then r.clicks      end,
    coalesce(r.leads, 0), coalesce(r.attendance, 0),
    case when s.client_id is not null then coalesce(r.prev_buy, 0) end,
    case when s.client_id is not null then coalesce(r.mid_buy,  0) end,
    case when s.client_id is not null then coalesce(r.prev_rev, 0) end,
    case when s.client_id is not null then coalesce(r.mid_rev,  0) end,
    p.preview_price, p.middle_price
  ) as m,
  row_number() over (
    partition by r.client_id
    order by case when r.ad = '(unsplit)' then 1 else 0 end,
             coalesce(r.leads, 0) desc, coalesce(r.spend, 0) desc, r.ad
  )::int as ord
from rolled r
left join v_sales_seen s on s.client_id = r.client_id
left join v_client_prices p on p.client_id = r.client_id
order by 1, ord;

grant select on v_metrics_by_ad to anon, authenticated;

-- ══════════════════════════════════════════════════════════════════════════
-- 0018_leads_are_absent_not_zero.sql
-- ══════════════════════════════════════════════════════════════════════════

-- ═══════════════════════════════════════════════════════════════════════════
-- 0018 — two things the screen was stating that nobody had measured.
--
-- ONE. Reach was still being added up in three views.
--
-- 0016 established that reach cannot be summed — it counts deduplicated people,
-- so adding two rows counts anyone in both twice — and taught By round, Total,
-- By month and Attend class to read it off the coarsest row instead. Three
-- views never got the rule: Preview offer, Middle offer (one view), By source
-- and Round × source. They were reading 33,337 for a round whose real reach is
-- 12,672, and 62,279 for a client whose real reach is 22,803.
--
-- The tell was Frequency, which is impressions ÷ reach and therefore cannot be
-- below 1: nobody sees an ad less than once. Those tabs were printing 0.86 and
-- 0.78. An impossible number is the cheapest kind of bug to believe, because it
-- looks like a small one.
--
-- TWO. Leads and attendance read 0 before their file had ever been imported.
--
-- The app already knows the difference between a measurement and an absence,
-- and already applies it to money: revenue reads "—" rather than 0.00 until
-- some sale exists, because "this round earned nothing" is a claim nobody has
-- evidence for. Leads and attendance were exempt from their own rule. With only
-- the ads file imported, every tab showed "Leads 0" and "Lead Gen % 0.00%" —
-- which does not say "no leads file yet", it says the advertising produced
-- nobody. That is the strongest claim on the screen and it was made up.
--
-- v_leads_seen and v_attendance_seen mirror v_sales_seen exactly, keyed on
-- events rather than on import_batches for the same reason given there: a file
-- whose every row parked in Unmatched has been imported and has told us
-- nothing. Once one lead lands, a cut with no leads correctly reads 0 again.
--
-- The journey strip needs no change: it reads v_metrics_total, so its cards go
-- blank and its rates disappear along with the tab they summarise.
-- ═══════════════════════════════════════════════════════════════════════════

-- Has a lead ever landed for this client? Same shape and same reasoning as
-- v_sales_seen in 0008 — see the note there.
create or replace view v_leads_seen as
select distinct client_id from v_events where event_type = 'lead';

grant select on v_leads_seen to anon, authenticated;

-- Has an attendance row ever landed? Gated separately from leads, because the
-- Zoom export can be missing while the CRM export is not.
create or replace view v_attendance_seen as
select distinct client_id from v_events where event_type = 'attendance';

grant select on v_attendance_seen to anon, authenticated;

create or replace view v_metrics_by_round as
with ads as (
  select client_id, round_id,
         sum(spend) as spend,
         coalesce(sum(reach) filter (where nullif(btrim(ad_set), '') is null),
                  sum(reach)) as reach,
         sum(impressions) as impressions, sum(clicks) as clicks,
         count(*) as ad_rows
  from v_ads group by client_id, round_id
),
ev as (
  select client_id, round_id,
         count(*) filter (where event_type = 'lead')       as leads,
         count(*) filter (where event_type = 'attendance') as attendance
  from v_events group by client_id, round_id
),
sales as (
  select client_id, lead_round_id as round_id,
         count(*) filter (where product = 'preview')                     as prev_buy,
         count(*) filter (where product = 'middle')                      as mid_buy,
         sum(amount - coalesce(refund_amount, 0)) filter (where product = 'preview') as prev_rev,
         sum(amount - coalesce(refund_amount, 0)) filter (where product = 'middle')  as mid_rev
  from v_events where event_type = 'sale' and lead_round_id is not null
  group by client_id, lead_round_id
)
select
  r.client_id,
  r.round_id                                  as cut_key,
  r.round_id                                  as cut_label,
  to_char(r.start_date, 'Mon DD') || ' – ' || to_char(r.end_date, 'DD') as cut_sub,
  r.start_date,
  fo_metrics(
    coalesce(ads.ad_rows, 0) > 0,
    ads.spend, ads.reach::bigint, ads.impressions, ads.clicks,
    case when exists (select 1 from v_leads_seen z where z.client_id = r.client_id)
         then coalesce(ev.leads, 0) end,
    case when exists (select 1 from v_attendance_seen z where z.client_id = r.client_id)
         then coalesce(ev.attendance, 0) end,
    case when s.client_id is not null then coalesce(sales.prev_buy, 0) end,
    case when s.client_id is not null then coalesce(sales.mid_buy,  0) end,
    case when s.client_id is not null then coalesce(sales.prev_rev, 0) end,
    case when s.client_id is not null then coalesce(sales.mid_rev,  0) end,
    p.preview_price, p.middle_price
  ) as m
from rounds r
left join ads   on ads.client_id = r.client_id and ads.round_id = r.round_id
left join ev    on ev.client_id  = r.client_id and ev.round_id  = r.round_id
left join sales on sales.client_id = r.client_id and sales.round_id = r.round_id
left join v_sales_seen s on s.client_id = r.client_id
left join v_client_prices p on p.client_id = r.client_id
order by r.client_id, r.start_date;

grant select on v_metrics_by_round to anon, authenticated;

create or replace view v_metrics_total as
with ads as (
  select client_id, sum(spend) as spend,
         coalesce(sum(reach) filter (where nullif(btrim(ad_set), '') is null),
                  sum(reach)) as reach,
         sum(impressions) as impressions, sum(clicks) as clicks, count(*) as ad_rows
  from v_ads group by client_id
),
ev as (
  select client_id,
         count(*) filter (where event_type = 'lead')       as leads,
         count(*) filter (where event_type = 'attendance') as attendance,
         count(*) filter (where event_type = 'sale' and product = 'preview') as prev_buy,
         count(*) filter (where event_type = 'sale' and product = 'middle')  as mid_buy,
         sum(amount - coalesce(refund_amount, 0)) filter (where event_type = 'sale' and product = 'preview') as prev_rev,
         sum(amount - coalesce(refund_amount, 0)) filter (where event_type = 'sale' and product = 'middle')  as mid_rev
  from v_events group by client_id
)
select
  c.client_id,
  'TOTAL'::text as cut_key,
  'Total'::text as cut_label,
  'all rounds'::text as cut_sub,
  fo_metrics(
    coalesce(ads.ad_rows, 0) > 0,
    ads.spend, ads.reach::bigint, ads.impressions, ads.clicks,
    case when exists (select 1 from v_leads_seen z where z.client_id = c.client_id)
         then coalesce(ev.leads, 0) end,
    case when exists (select 1 from v_attendance_seen z where z.client_id = c.client_id)
         then coalesce(ev.attendance, 0) end,
    case when s.client_id is not null then coalesce(ev.prev_buy, 0) end,
    case when s.client_id is not null then coalesce(ev.mid_buy,  0) end,
    case when s.client_id is not null then coalesce(ev.prev_rev, 0) end,
    case when s.client_id is not null then coalesce(ev.mid_rev,  0) end,
    p.preview_price, p.middle_price
  ) as m
from v_clients c
left join ads on ads.client_id = c.client_id
left join ev  on ev.client_id  = c.client_id
left join v_sales_seen s on s.client_id = c.client_id
left join v_client_prices p on p.client_id = c.client_id;

grant select on v_metrics_total to anon, authenticated;

create or replace view v_metrics_by_month as
with months as (
  select client_id, date_trunc('month', start_date)::date as month_start,
         count(*)::int as round_count
  from rounds group by 1, 2
),
ads as (
  select r.client_id, date_trunc('month', r.start_date)::date as month_start,
         sum(a.spend) as spend,
         coalesce(sum(a.reach) filter (where nullif(btrim(a.ad_set), '') is null),
                  sum(a.reach)) as reach,
         sum(a.impressions) as impressions, sum(a.clicks) as clicks, count(*) as ad_rows
  from v_ads a join rounds r on r.round_id = a.round_id group by 1, 2
),
ev as (
  select r.client_id, date_trunc('month', r.start_date)::date as month_start,
         count(*) filter (where e.event_type = 'lead')       as leads,
         count(*) filter (where e.event_type = 'attendance') as attendance
  from v_events e join rounds r on r.round_id = e.round_id group by 1, 2
),
sales as (
  select r.client_id, date_trunc('month', r.start_date)::date as month_start,
         count(*) filter (where e.product = 'preview') as prev_buy,
         count(*) filter (where e.product = 'middle')  as mid_buy,
         sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.product = 'preview') as prev_rev,
         sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.product = 'middle')  as mid_rev
  from v_events e join rounds r on r.round_id = e.lead_round_id
  where e.event_type = 'sale' and e.lead_round_id is not null
  group by 1, 2
)
select
  m.client_id,
  to_char(m.month_start, 'YYYY-MM')  as cut_key,
  to_char(m.month_start, 'Mon YYYY') as cut_label,
  m.round_count || ' round' || case when m.round_count = 1 then '' else 's' end as cut_sub,
  m.month_start,
  fo_metrics(
    coalesce(ads.ad_rows, 0) > 0,
    ads.spend, ads.reach::bigint, ads.impressions, ads.clicks,
    case when exists (select 1 from v_leads_seen z where z.client_id = m.client_id)
         then coalesce(ev.leads, 0) end,
    case when exists (select 1 from v_attendance_seen z where z.client_id = m.client_id)
         then coalesce(ev.attendance, 0) end,
    case when s.client_id is not null then coalesce(sales.prev_buy, 0) end,
    case when s.client_id is not null then coalesce(sales.mid_buy,  0) end,
    case when s.client_id is not null then coalesce(sales.prev_rev, 0) end,
    case when s.client_id is not null then coalesce(sales.mid_rev,  0) end,
    p.preview_price, p.middle_price
  ) as m
from months m
left join ads   on ads.client_id   = m.client_id and ads.month_start   = m.month_start
left join ev    on ev.client_id    = m.client_id and ev.month_start    = m.month_start
left join sales on sales.client_id = m.client_id and sales.month_start = m.month_start
left join v_sales_seen s    on s.client_id = m.client_id
left join v_client_prices p on p.client_id = m.client_id
order by m.client_id, m.month_start;

grant select on v_metrics_by_month to anon, authenticated;

create or replace view v_metrics_by_session as
with labels as (
  select client_id, coalesce(nullif(btrim(session_label), ''), '(unlabelled)') as label,
         count(*)::int as round_count, min(start_date) as first_start
  from rounds group by 1, 2
),
ads as (
  select r.client_id, coalesce(nullif(btrim(r.session_label), ''), '(unlabelled)') as label,
         sum(a.spend) as spend,
         coalesce(sum(a.reach) filter (where nullif(btrim(a.ad_set), '') is null),
                  sum(a.reach)) as reach,
         sum(a.impressions) as impressions, sum(a.clicks) as clicks, count(*) as ad_rows
  from v_ads a join rounds r on r.round_id = a.round_id group by 1, 2
),
ev as (
  select r.client_id, coalesce(nullif(btrim(r.session_label), ''), '(unlabelled)') as label,
         count(*) filter (where e.event_type = 'lead')       as leads,
         count(*) filter (where e.event_type = 'attendance') as attendance
  from v_events e join rounds r on r.round_id = e.round_id group by 1, 2
),
sales as (
  select r.client_id, coalesce(nullif(btrim(r.session_label), ''), '(unlabelled)') as label,
         count(*) filter (where e.product = 'preview') as prev_buy,
         count(*) filter (where e.product = 'middle')  as mid_buy,
         sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.product = 'preview') as prev_rev,
         sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.product = 'middle')  as mid_rev
  from v_events e join rounds r on r.round_id = e.lead_round_id
  where e.event_type = 'sale' and e.lead_round_id is not null
  group by 1, 2
)
select
  l.client_id,
  l.label as cut_key,
  l.label as cut_label,
  l.round_count || ' round' || case when l.round_count = 1 then '' else 's' end as cut_sub,
  fo_metrics(
    coalesce(ads.ad_rows, 0) > 0,
    ads.spend, ads.reach::bigint, ads.impressions, ads.clicks,
    case when exists (select 1 from v_leads_seen z where z.client_id = l.client_id)
         then coalesce(ev.leads, 0) end,
    case when exists (select 1 from v_attendance_seen z where z.client_id = l.client_id)
         then coalesce(ev.attendance, 0) end,
    case when s.client_id is not null then coalesce(sales.prev_buy, 0) end,
    case when s.client_id is not null then coalesce(sales.mid_buy,  0) end,
    case when s.client_id is not null then coalesce(sales.prev_rev, 0) end,
    case when s.client_id is not null then coalesce(sales.mid_rev,  0) end,
    p.preview_price, p.middle_price
  ) as m,
  row_number() over (partition by l.client_id order by l.first_start, l.label)::int as ord
from labels l
left join ads   on ads.client_id   = l.client_id and ads.label   = l.label
left join ev    on ev.client_id    = l.client_id and ev.label    = l.label
left join sales on sales.client_id = l.client_id and sales.label = l.label
left join v_sales_seen s    on s.client_id = l.client_id
left join v_client_prices p on p.client_id = l.client_id
order by 1, ord;

grant select on v_metrics_by_session to anon, authenticated;

create or replace view v_metrics_by_adset as
with ads as (
  select client_id, nullif(btrim(ad_set), '') as ad_set,
         sum(spend) as spend, sum(reach) as reach,
         sum(impressions) as impressions, sum(clicks) as clicks,
         count(*) as ad_rows
  from v_ads group by client_id, nullif(btrim(ad_set), '')
),
-- The audience that ACQUIRED each person: the earliest lead of theirs carrying
-- one. Paid leads with no audience resolve to the unsplit bucket rather than to
-- nothing, so their attendance and purchases stay attached to paid money.
lead_audience as (
  select distinct on (client_id, contact_id)
         client_id, contact_id,
         coalesce(nullif(btrim(ad_set), ''),
                  case when source = 'Paid Ads' then '(unsplit)' end) as ad_set
  from v_events
  where event_type = 'lead'
    and contact_id is not null
    and (nullif(btrim(ad_set), '') is not null or source = 'Paid Ads')
  order by client_id, contact_id, event_date
),
-- A LEAD counts on its OWN audience, not on the acquiring lead's. The two
-- differ for anyone who opted in twice, and routing those through the first
-- audience inflates the lead total — that second opt-in really did come from
-- the second ad set. It is the events with no tag of their own that need the
-- detour.
ev_leads as (
  select client_id,
         coalesce(nullif(btrim(ad_set), ''),
                  case when source = 'Paid Ads' then '(unsplit)' end) as ad_set,
         count(*) as leads
  from v_events
  where event_type = 'lead'
    and (nullif(btrim(ad_set), '') is not null or source = 'Paid Ads')
  group by 1, 2
),
ev_after as (
  select
    la.client_id, la.ad_set,
    count(*) filter (where e.event_type = 'attendance') as attendance,
    count(*) filter (where e.event_type = 'sale' and e.product = 'preview') as prev_buy,
    count(*) filter (where e.event_type = 'sale' and e.product = 'middle')  as mid_buy,
    sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.event_type = 'sale' and e.product = 'preview') as prev_rev,
    sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.event_type = 'sale' and e.product = 'middle')  as mid_rev
  from v_events e
  join lead_audience la
    on la.client_id = e.client_id and la.contact_id = e.contact_id
  where e.event_type <> 'lead'
  group by la.client_id, la.ad_set
),
ev as (
  select
    coalesce(l.client_id, a.client_id) as client_id,
    coalesce(l.ad_set, a.ad_set)       as ad_set,
    l.leads, a.attendance, a.prev_buy, a.mid_buy, a.prev_rev, a.mid_rev
  from ev_leads l
  full join ev_after a on a.client_id = l.client_id and a.ad_set = l.ad_set
),
cut as (
  select
    coalesce(ads.client_id, ev.client_id) as client_id,
    case when ads.ad_set is null and ev.ad_set is null then '(unsplit)'
         else coalesce(ads.ad_set, ev.ad_set) end as ad_set,
    ads.spend, ads.reach, ads.impressions, ads.clicks, ads.ad_rows,
    ev.leads, ev.attendance, ev.prev_buy, ev.mid_buy, ev.prev_rev, ev.mid_rev
  from ads
  full join ev on ev.client_id = ads.client_id and ev.ad_set = ads.ad_set
),
rolled as (
  select client_id, ad_set,
         sum(spend)::numeric      as spend,
         sum(reach)::bigint       as reach,
         sum(impressions)::bigint as impressions,
         sum(clicks)::bigint      as clicks,
         sum(ad_rows)::bigint     as ad_rows,
         sum(leads)::bigint       as leads,
         sum(attendance)::bigint  as attendance,
         sum(prev_buy)::bigint    as prev_buy,
         sum(mid_buy)::bigint     as mid_buy,
         sum(prev_rev)::numeric   as prev_rev,
         sum(mid_rev)::numeric    as mid_rev
  from cut group by client_id, ad_set
)
select
  r.client_id,
  r.ad_set                                                  as cut_key,
  case when r.ad_set = '(unsplit)' then 'Unsplit spend' else r.ad_set end as cut_label,
  case when r.ad_set = '(unsplit)'
       then 'paid, no ad set recorded' end                  as cut_sub,
  fo_metrics(
    coalesce(r.ad_rows, 0) > 0,
    -- 0 here means "no spend was recorded against unknown audiences", not
    -- "those leads cost nothing" — see the note above.
    case when r.ad_set = '(unsplit)' then nullif(r.spend, 0) else r.spend end,
    -- Delivery has no subject in the bucket that means "audience unknown".
    -- Passing NULL blanks reach, impressions, clicks and — because SQL
    -- arithmetic propagates NULL — Frequency, CTR, Lead Gen %, CPM and CPC
    -- along with them, without any of those needing to be special-cased.
    case when r.ad_set <> '(unsplit)' then r.reach       end,
    case when r.ad_set <> '(unsplit)' then r.impressions end,
    case when r.ad_set <> '(unsplit)' then r.clicks      end,
    case when exists (select 1 from v_leads_seen z where z.client_id = r.client_id)
         then coalesce(r.leads, 0) end,
    case when exists (select 1 from v_attendance_seen z where z.client_id = r.client_id)
         then coalesce(r.attendance, 0) end,
    case when s.client_id is not null then coalesce(r.prev_buy, 0) end,
    case when s.client_id is not null then coalesce(r.mid_buy,  0) end,
    case when s.client_id is not null then coalesce(r.prev_rev, 0) end,
    case when s.client_id is not null then coalesce(r.mid_rev,  0) end,
    p.preview_price, p.middle_price
  ) as m,
  case when r.ad_set = '(unsplit)' then -1 else coalesce(r.spend, 0) end as sort_spend,
  row_number() over (
    partition by r.client_id
    order by
      case when r.ad_set = '(unsplit)' then 1 else 0 end,
      coalesce(r.spend, 0) desc,
      coalesce(r.leads, 0) desc,
      r.ad_set
  )::int                                                    as ord
from rolled r
left join v_sales_seen s on s.client_id = r.client_id
left join v_client_prices p on p.client_id = r.client_id
order by 1, ord;

grant select on v_metrics_by_adset to anon, authenticated;

create or replace view v_metrics_by_ad as
with ads as (
  select client_id, nullif(btrim(ad), '') as ad,
         sum(spend) as spend, sum(reach) as reach,
         sum(impressions) as impressions, sum(clicks) as clicks,
         count(*) as ad_rows
  from v_ads group by client_id, nullif(btrim(ad), '')
),
-- the creative that ACQUIRED each person: their earliest lead carrying one
lead_ad as (
  select distinct on (client_id, contact_id)
         client_id, contact_id,
         coalesce(nullif(btrim(ad), ''),
                  case when source = 'Paid Ads' then '(unsplit)' end) as ad
  from v_events
  where event_type = 'lead' and contact_id is not null
    and (nullif(btrim(ad), '') is not null or source = 'Paid Ads')
  order by client_id, contact_id, event_date
),
-- a lead counts on its OWN creative; only later events need the detour
ev_leads as (
  select client_id,
         coalesce(nullif(btrim(ad), ''),
                  case when source = 'Paid Ads' then '(unsplit)' end) as ad,
         count(*) as leads
  from v_events
  where event_type = 'lead'
    and (nullif(btrim(ad), '') is not null or source = 'Paid Ads')
  group by 1, 2
),
ev_after as (
  select la.client_id, la.ad,
    count(*) filter (where e.event_type = 'attendance') as attendance,
    count(*) filter (where e.event_type = 'sale' and e.product = 'preview') as prev_buy,
    count(*) filter (where e.event_type = 'sale' and e.product = 'middle')  as mid_buy,
    sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.event_type = 'sale' and e.product = 'preview') as prev_rev,
    sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.event_type = 'sale' and e.product = 'middle')  as mid_rev
  from v_events e
  join lead_ad la on la.client_id = e.client_id and la.contact_id = e.contact_id
  where e.event_type <> 'lead'
  group by la.client_id, la.ad
),
ev as (
  select coalesce(l.client_id, a.client_id) as client_id,
         coalesce(l.ad, a.ad)               as ad,
         l.leads, a.attendance, a.prev_buy, a.mid_buy, a.prev_rev, a.mid_rev
  from ev_leads l
  full join ev_after a on a.client_id = l.client_id and a.ad = l.ad
),
cut as (
  select coalesce(ads.client_id, ev.client_id) as client_id,
         case when ads.ad is null and ev.ad is null then '(unsplit)'
              else coalesce(ads.ad, ev.ad) end as ad,
         ads.spend, ads.reach, ads.impressions, ads.clicks, ads.ad_rows,
         ev.leads, ev.attendance, ev.prev_buy, ev.mid_buy, ev.prev_rev, ev.mid_rev
  from ads full join ev on ev.client_id = ads.client_id and ev.ad = ads.ad
),
rolled as (
  select client_id, ad,
         sum(spend)::numeric as spend, sum(reach)::bigint as reach,
         sum(impressions)::bigint as impressions, sum(clicks)::bigint as clicks,
         sum(ad_rows)::bigint as ad_rows, sum(leads)::bigint as leads,
         sum(attendance)::bigint as attendance, sum(prev_buy)::bigint as prev_buy,
         sum(mid_buy)::bigint as mid_buy, sum(prev_rev)::numeric as prev_rev,
         sum(mid_rev)::numeric as mid_rev
  from cut group by client_id, ad
)
select
  r.client_id,
  r.ad                                                        as cut_key,
  case when r.ad = '(unsplit)' then 'Unsplit spend' else r.ad end as cut_label,
  case when r.ad = '(unsplit)' then 'paid, no ad recorded'
       when r.ad ~ '^[0-9]+$' then 'Ad ID, no name in the export' end as cut_sub,
  fo_metrics(
    coalesce(r.ad_rows, 0) > 0,
    -- the one change: 0.00 in this bucket means "not recorded", not "free"
    case when r.ad = '(unsplit)' then nullif(r.spend, 0) else r.spend end,
    -- same rule as 0013: delivery has no subject in the unattributable bucket
    case when r.ad <> '(unsplit)' then r.reach       end,
    case when r.ad <> '(unsplit)' then r.impressions end,
    case when r.ad <> '(unsplit)' then r.clicks      end,
    case when exists (select 1 from v_leads_seen z where z.client_id = r.client_id)
         then coalesce(r.leads, 0) end,
    case when exists (select 1 from v_attendance_seen z where z.client_id = r.client_id)
         then coalesce(r.attendance, 0) end,
    case when s.client_id is not null then coalesce(r.prev_buy, 0) end,
    case when s.client_id is not null then coalesce(r.mid_buy,  0) end,
    case when s.client_id is not null then coalesce(r.prev_rev, 0) end,
    case when s.client_id is not null then coalesce(r.mid_rev,  0) end,
    p.preview_price, p.middle_price
  ) as m,
  row_number() over (
    partition by r.client_id
    order by case when r.ad = '(unsplit)' then 1 else 0 end,
             coalesce(r.leads, 0) desc, coalesce(r.spend, 0) desc, r.ad
  )::int as ord
from rolled r
left join v_sales_seen s on s.client_id = r.client_id
left join v_client_prices p on p.client_id = r.client_id
order by 1, ord;

grant select on v_metrics_by_ad to anon, authenticated;

create or replace view v_metrics_by_offer as
with offers as (select unnest(array['preview', 'middle']) as product),
ads as (
  select client_id, round_id, sum(spend) as spend,
         -- 0016's rule, which this view never got: read reach off the coarsest
         -- row rather than adding the tiers, or a round claims 33,337 people
         -- when 12,672 saw it and Frequency drops below 1.
         coalesce(sum(reach) filter (where nullif(btrim(ad_set), '') is null),
                  sum(reach)) as reach,
         sum(impressions) as impressions, sum(clicks) as clicks, count(*) as ad_rows
  from v_ads group by 1, 2
),
ev as (
  select client_id, round_id,
         count(*) filter (where event_type = 'lead')       as leads,
         count(*) filter (where event_type = 'attendance') as attendance
  from v_events group by 1, 2
),
sales as (
  select client_id, lead_round_id as round_id, product,
         count(*) as buys,
         sum(amount - coalesce(refund_amount, 0)) as rev
  from v_events
  where event_type = 'sale' and lead_round_id is not null and product is not null
  group by 1, 2, 3
)
select
  r.client_id,
  o.product,
  r.round_id                                  as cut_key,
  r.round_id                                  as cut_label,
  to_char(r.start_date, 'Mon DD') || ' – ' || to_char(r.end_date, 'DD') as cut_sub,
  r.start_date,
  fo_metrics(
    coalesce(ads.ad_rows, 0) > 0,
    ads.spend, ads.reach, ads.impressions, ads.clicks,
    case when exists (select 1 from v_leads_seen z where z.client_id = r.client_id)
         then coalesce(ev.leads, 0) end,
    case when exists (select 1 from v_attendance_seen z where z.client_id = r.client_id)
         then coalesce(ev.attendance, 0) end,
    -- only this tab's offer carries numbers; the other is absent, not zero
    case when o.product = 'preview' and s.client_id is not null then coalesce(sp.buys, 0) end,
    case when o.product = 'middle'  and s.client_id is not null then coalesce(sm.buys, 0) end,
    case when o.product = 'preview' and s.client_id is not null then coalesce(sp.rev,  0) end,
    case when o.product = 'middle'  and s.client_id is not null then coalesce(sm.rev,  0) end,
    p.preview_price, p.middle_price
  ) as m
from rounds r
cross join offers o
left join ads on ads.client_id = r.client_id and ads.round_id = r.round_id
left join ev  on ev.client_id  = r.client_id and ev.round_id  = r.round_id
left join sales sp on sp.client_id = r.client_id and sp.round_id = r.round_id and sp.product = 'preview'
left join sales sm on sm.client_id = r.client_id and sm.round_id = r.round_id and sm.product = 'middle'
left join v_sales_seen s    on s.client_id = r.client_id
left join v_client_prices p on p.client_id = r.client_id
order by r.client_id, o.product, r.start_date;

grant select on v_metrics_by_offer to anon, authenticated;

create or replace view v_metrics_by_source as
with ev as (
  select
    client_id,
    coalesce(attribution_bucket, 'Unattributed') as bucket,
    count(*) filter (where event_type = 'lead')       as leads,
    count(*) filter (where event_type = 'attendance') as attendance,
    count(*) filter (where event_type = 'sale' and product = 'preview') as prev_buy,
    count(*) filter (where event_type = 'sale' and product = 'middle')  as mid_buy,
    sum(amount - coalesce(refund_amount, 0)) filter (where event_type = 'sale' and product = 'preview') as prev_rev,
    sum(amount - coalesce(refund_amount, 0)) filter (where event_type = 'sale' and product = 'middle')  as mid_rev
  from v_events
  group by client_id, coalesce(attribution_bucket, 'Unattributed')
),
ads as (
  select client_id, sum(spend) as spend,
         -- 0016's rule, which this view never got — see the note in By round.
         coalesce(sum(reach) filter (where nullif(btrim(ad_set), '') is null),
                  sum(reach)) as reach,
         sum(impressions) as impressions, sum(clicks) as clicks,
         count(*) as ad_rows
  from v_ads group by client_id
),
share as (
  select client_id, sum(leads) as all_leads from ev group by client_id
)
select
  ev.client_id,
  ev.bucket                                   as cut_key,
  ev.bucket                                   as cut_label,
  case
    when share.all_leads > 0
      then to_char(round(100.0 * ev.leads / share.all_leads), 'FM999') || '% of leads'
    else coalesce(b.note, 'no leads')
  end                                         as cut_sub,
  coalesce(b.ord, 99)                         as ord,
  fo_metrics(
    -- only the paid column has spend behind it
    ev.bucket = 'Paid Ads' and coalesce(ads.ad_rows, 0) > 0,
    case when ev.bucket = 'Paid Ads' then ads.spend       end,
    case when ev.bucket = 'Paid Ads' then ads.reach       end,
    case when ev.bucket = 'Paid Ads' then ads.impressions end,
    case when ev.bucket = 'Paid Ads' then ads.clicks      end,
    case when exists (select 1 from v_leads_seen z where z.client_id = ev.client_id)
         then coalesce(ev.leads, 0) end,
    case when exists (select 1 from v_attendance_seen z where z.client_id = ev.client_id)
         then coalesce(ev.attendance, 0) end,
    case when s.client_id is not null then coalesce(ev.prev_buy, 0) end,
    case when s.client_id is not null then coalesce(ev.mid_buy,  0) end,
    case when s.client_id is not null then coalesce(ev.prev_rev, 0) end,
    case when s.client_id is not null then coalesce(ev.mid_rev,  0) end,
    p.preview_price, p.middle_price
  ) as m
from ev
left join v_source_buckets b on b.bucket = ev.bucket
left join ads   on ads.client_id   = ev.client_id
left join share on share.client_id = ev.client_id
left join v_sales_seen s on s.client_id = ev.client_id
left join v_client_prices p on p.client_id = ev.client_id
order by ev.client_id, coalesce(b.ord, 99);

-- ═══════════════════════════════════════════════════════════════════════════
-- ROUND × SOURCE — per-round Total still lifted whole out of By round, so the
-- two tabs cannot drift.
-- ═══════════════════════════════════════════════════════════════════════════

grant select on v_metrics_by_source to anon, authenticated;

create or replace view v_metrics_by_round_source as
with ev as (
  select
    client_id, round_id,
    coalesce(attribution_bucket, 'Unattributed') as bucket,
    count(*) filter (where event_type = 'lead')       as leads,
    count(*) filter (where event_type = 'attendance') as attendance
  from v_events
  group by 1, 2, 3
),
sales as (
  select
    client_id, lead_round_id as round_id,
    coalesce(attribution_bucket, 'Unattributed') as bucket,
    count(*) filter (where product = 'preview') as prev_buy,
    count(*) filter (where product = 'middle')  as mid_buy,
    sum(amount - coalesce(refund_amount, 0)) filter (where product = 'preview') as prev_rev,
    sum(amount - coalesce(refund_amount, 0)) filter (where product = 'middle')  as mid_rev
  from v_events
  where event_type = 'sale' and lead_round_id is not null
  group by 1, 2, 3
),
ads as (
  select client_id, round_id, sum(spend) as spend,
         -- 0016's rule, which this view never got: read reach off the coarsest
         -- row rather than adding the tiers, or a round claims 33,337 people
         -- when 12,672 saw it and Frequency drops below 1.
         coalesce(sum(reach) filter (where nullif(btrim(ad_set), '') is null),
                  sum(reach)) as reach,
         sum(impressions) as impressions, sum(clicks) as clicks,
         count(*) as ad_rows
  from v_ads group by 1, 2
),
-- a cell exists if either side has rows for it; a source with nothing in a
-- round gets no column in that round rather than a column of zeroes
cells as (
  select client_id, round_id, bucket from ev
  union
  select client_id, round_id, bucket from sales
)
select
  r.client_id,
  r.round_id || '·' || c.bucket                as cut_key,
  c.bucket                                     as cut_label,
  null::text                                   as cut_sub,
  r.round_id                                   as group_key,
  r.round_id                                   as group_label,
  to_char(r.start_date, 'Mon DD') || ' – ' || to_char(r.end_date, 'DD') as group_sub,
  r.start_date,
  coalesce(b.ord, 99)                          as ord,
  fo_metrics(
    c.bucket = 'Paid Ads' and coalesce(ads.ad_rows, 0) > 0,
    case when c.bucket = 'Paid Ads' then ads.spend       end,
    case when c.bucket = 'Paid Ads' then ads.reach       end,
    case when c.bucket = 'Paid Ads' then ads.impressions end,
    case when c.bucket = 'Paid Ads' then ads.clicks      end,
    case when exists (select 1 from v_leads_seen z where z.client_id = r.client_id)
         then coalesce(ev.leads, 0) end,
    case when exists (select 1 from v_attendance_seen z where z.client_id = r.client_id)
         then coalesce(ev.attendance, 0) end,
    case when s.client_id is not null then coalesce(sales.prev_buy, 0) end,
    case when s.client_id is not null then coalesce(sales.mid_buy,  0) end,
    case when s.client_id is not null then coalesce(sales.prev_rev, 0) end,
    case when s.client_id is not null then coalesce(sales.mid_rev,  0) end,
    p.preview_price, p.middle_price
  ) as m
from cells c
join rounds r
  on r.round_id = c.round_id and r.client_id = c.client_id
left join ev
  on ev.client_id = c.client_id and ev.round_id = c.round_id and ev.bucket = c.bucket
left join sales
  on sales.client_id = c.client_id and sales.round_id = c.round_id and sales.bucket = c.bucket
left join ads
  on ads.client_id = c.client_id and ads.round_id = c.round_id
left join v_source_buckets b on b.bucket = c.bucket
left join v_sales_seen s on s.client_id = c.client_id
left join v_client_prices p on p.client_id = c.client_id

union all

-- the per-round Total column, taken whole from By round so the two tabs agree.
-- rev is NULL until a sale exists, so it is coalesced here rather than compared
-- directly — a NULL comparison would make the whole OR-chain NULL and drop the
-- round out of the tab.
select
  client_id,
  cut_key || '·Total',
  'Total',
  null::text,
  cut_key,
  cut_key,
  cut_sub,
  start_date,
  0,
  m
from v_metrics_by_round
where (m->>'leads')::bigint > 0
   or coalesce((m->>'rev')::numeric, 0) > 0
   or (m->>'spend') is not null;

-- ═══════════════════════════════════════════════════════════════════════════
-- BASELINE — the pinned reference column. Same rule, NULL-safe: a client with
-- no sales yet simply has no baseline, rather than the comparison silently
-- vanishing on a NULL.
-- ═══════════════════════════════════════════════════════════════════════════

grant select on v_metrics_by_round_source to anon, authenticated;

-- ══════════════════════════════════════════════════════════════════════════
-- 0019_stale_counts_the_gap_not_the_clock.sql
-- ══════════════════════════════════════════════════════════════════════════

-- ═══════════════════════════════════════════════════════════════════════════
-- 0019 — "Sales 0d stale" is a sentence that argues with itself.
--
-- 0014 got the RULE right: a source is stale when its coverage ends before the
-- last round that has already finished, because time passing is not evidence of
-- missing data — missing data is. Sales covers 20 May, rounds run to 27 May, so
-- 0526-03 has no sales and the flag is correct.
--
-- The header then printed that flag next to `days_since`, which counts days
-- since the file was imported. Import it this morning and the pill reads
-- "Sales 0d stale": stale, and zero days so. Two true facts about two different
-- clocks, glued into one number that means nothing. It has now sent two people
-- looking for a bug that isn't there.
--
-- days_behind is the number the sentence was always trying to say: how many
-- days of finished rounds this source says nothing about. It is exactly the
-- distance the staleness test itself measures, so the pill and the rule can no
-- longer disagree.
--
-- NULL when the source is not behind. A source that is stale only because
-- someone set stale_flag by hand has no gap to report, and the header prints
-- "Sales stale" with no number rather than inventing a zero — the same reason
-- every other absent figure on the screen reads "—".
--
-- days_since stays exactly as it was. It is a fact about the clock, it makes no
-- claim, and the Import tab still shows it as "Last import".
--
-- Appended, not replaced: create or replace view only permits adding columns at
-- the end, so days_behind goes last and every existing reader is untouched.
-- ═══════════════════════════════════════════════════════════════════════════
create or replace view v_import_status as
with latest as (
  -- one batch per source: the most recent one that actually landed
  select distinct on (client_id, source)
    client_id, source, imported_at, coverage_start, coverage_end,
    row_count, column_map, expected_cadence, stale_flag
  from import_batches
  where status = 'committed'
  order by client_id, source, imported_at desc
),
-- The last round that has already ended. A round still running is not evidence
-- of missing data — its files are not due yet.
horizon as (
  select client_id, max(end_date) as covered_through
  from rounds
  where end_date <= current_date
  group by client_id
)
select
  l.client_id, l.source, l.imported_at, l.coverage_start, l.coverage_end,
  l.row_count, l.column_map, l.expected_cadence,
  -- stale_flag stays respected: a batch explicitly marked stale is stale
  -- whatever the dates say.
  l.stale_flag
    or l.coverage_end is null
    or (h.covered_through is not null and l.coverage_end < h.covered_through)
    as is_stale,
  extract(day from now() - l.imported_at)::int as days_since,
  -- how far short of the finished rounds this source stops, in days
  case
    when h.covered_through is not null
     and l.coverage_end is not null
     and l.coverage_end < h.covered_through
    then (h.covered_through - l.coverage_end)::int
  end as days_behind
from latest l
left join horizon h on h.client_id = l.client_id
order by l.client_id, l.source;

grant select on v_import_status to anon, authenticated;

-- ══════════════════════════════════════════════════════════════════════════
-- 0020_roas_counts_only_what_ads_produced.sql
-- ══════════════════════════════════════════════════════════════════════════

-- ═══════════════════════════════════════════════════════════════════════════
-- 0020 — ROAS and CPA must divide ad spend into what advertising produced.
--
-- 0526-03 spent 1,153.22 and reported ROAS 3.62, highlighted green as a win.
-- Every cent of that round's 4,176.00 came from two AOAI members and four AI
-- Community members — people already in the room, who cost nothing to acquire.
-- Not one ad-sourced person bought in that round. The true answer is 0.00, and
-- the screen was saying the opposite as loudly as it could.
--
-- The rule already exists everywhere else. 0006 established that spend belongs
-- to Paid Ads and only to Paid Ads, which is why the AOAI column carries no
-- CPM, no CPL and no ROAS. The round tabs were the one place it was never
-- applied, so one app printed 2.07 and 0.36 for the same period on two tabs.
--
-- WHAT COUNTS AS AD-PRODUCED. Paid Ads and Previous Paid Ads — both are paid
-- leads, and on By round a Previous Paid Ads sale already lands on the round
-- whose spend produced the lead. Unattributed does NOT count: nothing evidences
-- it was paid, and this app understates rather than overstates.
--
-- CPA GOES WITH IT, by the same argument. It is ad spend divided by acquired
-- customers, and counting customers the ads did not acquire makes acquisition
-- look cheaper than it was. 0526-03 read CPA 192.20 as though advertising had
-- bought six customers. It bought none, so that cell now reads '—'.
--
-- WHAT DOES NOT CHANGE. Total Revenue, Preview/Middle Offer Revenue, the
-- purchase counts and both AOV rows still count every sale — they are facts
-- about the round, not about advertising. So ROAS can no longer be derived from
-- the revenue row above it. That is a real cost of this change, and the reason
-- the round tabs now say in words which revenue ROAS is counting.
--
-- HOW. fo_metrics is left alone — eleven views depend on it, so its signature
-- cannot change without dropping every one of them. Instead the four affected
-- keys are recomputed by one helper, in one place, and only the six views that
-- can tell paid revenue from community revenue call it. By audience and By
-- creative need no change: a person with no ad set and no creative has no
-- column there, so their revenue is already ad-only.
-- ═══════════════════════════════════════════════════════════════════════════

-- The four figures whose denominator is ad spend, recomputed against the slice
-- of revenue advertising actually produced.
--
-- Reads spend back out of the metrics object rather than taking it as its own
-- argument, so it cannot disagree with the Ads Spent row on the same screen.
-- When a cut has no ads at all, spend is NULL there and all four of these blank
-- themselves — the same behaviour as before, arrived at the same way.
create or replace function fo_paid_returns(
  m               jsonb,
  p_paid_prev_buy bigint,     -- customers advertising acquired
  p_paid_prev_rev numeric,    -- preview revenue advertising produced
  p_paid_mid_rev  numeric     -- middle revenue advertising produced
) returns jsonb
language sql
immutable
as $$
  select m || jsonb_build_object(
    'cpa',      (m->>'spend')::numeric / nullif(p_paid_prev_buy, 0),
    'prevRoas', p_paid_prev_rev / nullif((m->>'spend')::numeric, 0),
    'midRoas',  p_paid_mid_rev  / nullif((m->>'spend')::numeric, 0),
    'roas',     (p_paid_prev_rev + p_paid_mid_rev) / nullif((m->>'spend')::numeric, 0)
  );
$$;

grant execute on function fo_paid_returns(jsonb, bigint, numeric, numeric) to anon, authenticated;

create or replace view v_metrics_by_round as
with ads as (
  select client_id, round_id,
         sum(spend) as spend,
         coalesce(sum(reach) filter (where nullif(btrim(ad_set), '') is null),
                  sum(reach)) as reach,
         sum(impressions) as impressions, sum(clicks) as clicks,
         count(*) as ad_rows
  from v_ads group by client_id, round_id
),
ev as (
  select client_id, round_id,
         count(*) filter (where event_type = 'lead')       as leads,
         count(*) filter (where event_type = 'attendance') as attendance
  from v_events group by client_id, round_id
),
sales as (
  select client_id, lead_round_id as round_id,
         count(*) filter (where product = 'preview')                     as prev_buy,
         count(*) filter (where product = 'middle')                      as mid_buy,
         sum(amount - coalesce(refund_amount, 0)) filter (where product = 'preview') as prev_rev,
         sum(amount - coalesce(refund_amount, 0)) filter (where product = 'middle')  as mid_rev,
         -- the ad-produced slice, for ROAS and CPA (0020)
         count(*) filter (where product = 'preview' and attribution_bucket in ('Paid Ads', 'Previous Paid Ads')) as paid_prev_buy,
         sum(amount - coalesce(refund_amount, 0)) filter (where product = 'preview' and attribution_bucket in ('Paid Ads', 'Previous Paid Ads')) as paid_prev_rev,
         sum(amount - coalesce(refund_amount, 0)) filter (where product = 'middle'  and attribution_bucket in ('Paid Ads', 'Previous Paid Ads')) as paid_mid_rev
  from v_events where event_type = 'sale' and lead_round_id is not null
  group by client_id, lead_round_id
)
select
  r.client_id,
  r.round_id                                  as cut_key,
  r.round_id                                  as cut_label,
  to_char(r.start_date, 'Mon DD') || ' – ' || to_char(r.end_date, 'DD') as cut_sub,
  r.start_date,
  fo_paid_returns(
    fo_metrics(
      coalesce(ads.ad_rows, 0) > 0,
      ads.spend, ads.reach::bigint, ads.impressions, ads.clicks,
      case when exists (select 1 from v_leads_seen z where z.client_id = r.client_id)
           then coalesce(ev.leads, 0) end,
      case when exists (select 1 from v_attendance_seen z where z.client_id = r.client_id)
           then coalesce(ev.attendance, 0) end,
      case when s.client_id is not null then coalesce(sales.prev_buy, 0) end,
      case when s.client_id is not null then coalesce(sales.mid_buy,  0) end,
      case when s.client_id is not null then coalesce(sales.prev_rev, 0) end,
      case when s.client_id is not null then coalesce(sales.mid_rev,  0) end,
      p.preview_price, p.middle_price
    ),
    case when s.client_id is not null then coalesce(sales.paid_prev_buy, 0) end,
    case when s.client_id is not null then coalesce(sales.paid_prev_rev, 0) end,
    case when s.client_id is not null then coalesce(sales.paid_mid_rev,  0) end
  ) as m
from rounds r
left join ads   on ads.client_id = r.client_id and ads.round_id = r.round_id
left join ev    on ev.client_id  = r.client_id and ev.round_id  = r.round_id
left join sales on sales.client_id = r.client_id and sales.round_id = r.round_id
left join v_sales_seen s on s.client_id = r.client_id
left join v_client_prices p on p.client_id = r.client_id
order by r.client_id, r.start_date;

grant select on v_metrics_by_round to anon, authenticated;


create or replace view v_metrics_by_round_source as
with ev as (
  select
    client_id, round_id,
    coalesce(attribution_bucket, 'Unattributed') as bucket,
    count(*) filter (where event_type = 'lead')       as leads,
    count(*) filter (where event_type = 'attendance') as attendance
  from v_events
  group by 1, 2, 3
),
sales as (
  select
    client_id, lead_round_id as round_id,
    coalesce(attribution_bucket, 'Unattributed') as bucket,
    count(*) filter (where product = 'preview') as prev_buy,
    count(*) filter (where product = 'middle')  as mid_buy,
    sum(amount - coalesce(refund_amount, 0)) filter (where product = 'preview') as prev_rev,
    sum(amount - coalesce(refund_amount, 0)) filter (where product = 'middle')  as mid_rev,
    -- the ad-produced slice, for ROAS and CPA (0020)
    count(*) filter (where product = 'preview' and attribution_bucket in ('Paid Ads', 'Previous Paid Ads')) as paid_prev_buy,
    sum(amount - coalesce(refund_amount, 0)) filter (where product = 'preview' and attribution_bucket in ('Paid Ads', 'Previous Paid Ads')) as paid_prev_rev,
    sum(amount - coalesce(refund_amount, 0)) filter (where product = 'middle'  and attribution_bucket in ('Paid Ads', 'Previous Paid Ads')) as paid_mid_rev
  from v_events
  where event_type = 'sale' and lead_round_id is not null
  group by 1, 2, 3
),
ads as (
  select client_id, round_id, sum(spend) as spend,
         -- 0016's rule, which this view never got: read reach off the coarsest
         -- row rather than adding the tiers, or a round claims 33,337 people
         -- when 12,672 saw it and Frequency drops below 1.
         coalesce(sum(reach) filter (where nullif(btrim(ad_set), '') is null),
                  sum(reach)) as reach,
         sum(impressions) as impressions, sum(clicks) as clicks,
         count(*) as ad_rows
  from v_ads group by 1, 2
),
-- a cell exists if either side has rows for it; a source with nothing in a
-- round gets no column in that round rather than a column of zeroes
cells as (
  select client_id, round_id, bucket from ev
  union
  select client_id, round_id, bucket from sales
)
select
  r.client_id,
  r.round_id || '·' || c.bucket                as cut_key,
  c.bucket                                     as cut_label,
  null::text                                   as cut_sub,
  r.round_id                                   as group_key,
  r.round_id                                   as group_label,
  to_char(r.start_date, 'Mon DD') || ' – ' || to_char(r.end_date, 'DD') as group_sub,
  r.start_date,
  coalesce(b.ord, 99)                          as ord,
  fo_paid_returns(
    fo_metrics(
      c.bucket = 'Paid Ads' and coalesce(ads.ad_rows, 0) > 0,
      case when c.bucket = 'Paid Ads' then ads.spend       end,
      case when c.bucket = 'Paid Ads' then ads.reach       end,
      case when c.bucket = 'Paid Ads' then ads.impressions end,
      case when c.bucket = 'Paid Ads' then ads.clicks      end,
      case when exists (select 1 from v_leads_seen z where z.client_id = r.client_id)
           then coalesce(ev.leads, 0) end,
      case when exists (select 1 from v_attendance_seen z where z.client_id = r.client_id)
           then coalesce(ev.attendance, 0) end,
      case when s.client_id is not null then coalesce(sales.prev_buy, 0) end,
      case when s.client_id is not null then coalesce(sales.mid_buy,  0) end,
      case when s.client_id is not null then coalesce(sales.prev_rev, 0) end,
      case when s.client_id is not null then coalesce(sales.mid_rev,  0) end,
      p.preview_price, p.middle_price
    ),
    case when s.client_id is not null then coalesce(sales.paid_prev_buy, 0) end,
    case when s.client_id is not null then coalesce(sales.paid_prev_rev, 0) end,
    case when s.client_id is not null then coalesce(sales.paid_mid_rev,  0) end
  ) as m
from cells c
join rounds r
  on r.round_id = c.round_id and r.client_id = c.client_id
left join ev
  on ev.client_id = c.client_id and ev.round_id = c.round_id and ev.bucket = c.bucket
left join sales
  on sales.client_id = c.client_id and sales.round_id = c.round_id and sales.bucket = c.bucket
left join ads
  on ads.client_id = c.client_id and ads.round_id = c.round_id
left join v_source_buckets b on b.bucket = c.bucket
left join v_sales_seen s on s.client_id = c.client_id
left join v_client_prices p on p.client_id = c.client_id

union all

-- the per-round Total column, taken whole from By round so the two tabs agree.
-- rev is NULL until a sale exists, so it is coalesced here rather than compared
-- directly — a NULL comparison would make the whole OR-chain NULL and drop the
-- round out of the tab.
select
  client_id,
  cut_key || '·Total',
  'Total',
  null::text,
  cut_key,
  cut_key,
  cut_sub,
  start_date,
  0,
  m
from v_metrics_by_round
where (m->>'leads')::bigint > 0
   or coalesce((m->>'rev')::numeric, 0) > 0
   or (m->>'spend') is not null;

-- ═══════════════════════════════════════════════════════════════════════════
-- BASELINE — the pinned reference column. Same rule, NULL-safe: a client with
-- no sales yet simply has no baseline, rather than the comparison silently
-- vanishing on a NULL.
-- ═══════════════════════════════════════════════════════════════════════════

grant select on v_metrics_by_round_source to anon, authenticated;


create or replace view v_metrics_by_month as
with months as (
  select client_id, date_trunc('month', start_date)::date as month_start,
         count(*)::int as round_count
  from rounds group by 1, 2
),
ads as (
  select r.client_id, date_trunc('month', r.start_date)::date as month_start,
         sum(a.spend) as spend,
         coalesce(sum(a.reach) filter (where nullif(btrim(a.ad_set), '') is null),
                  sum(a.reach)) as reach,
         sum(a.impressions) as impressions, sum(a.clicks) as clicks, count(*) as ad_rows
  from v_ads a join rounds r on r.round_id = a.round_id group by 1, 2
),
ev as (
  select r.client_id, date_trunc('month', r.start_date)::date as month_start,
         count(*) filter (where e.event_type = 'lead')       as leads,
         count(*) filter (where e.event_type = 'attendance') as attendance
  from v_events e join rounds r on r.round_id = e.round_id group by 1, 2
),
sales as (
  select r.client_id, date_trunc('month', r.start_date)::date as month_start,
         count(*) filter (where e.product = 'preview') as prev_buy,
         count(*) filter (where e.product = 'middle')  as mid_buy,
         sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.product = 'preview') as prev_rev,
         sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.product = 'middle')  as mid_rev,
         -- the ad-produced slice, for ROAS and CPA (0020)
         count(*) filter (where e.product = 'preview' and e.attribution_bucket in ('Paid Ads', 'Previous Paid Ads')) as paid_prev_buy,
         sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.product = 'preview' and e.attribution_bucket in ('Paid Ads', 'Previous Paid Ads')) as paid_prev_rev,
         sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.product = 'middle'  and e.attribution_bucket in ('Paid Ads', 'Previous Paid Ads')) as paid_mid_rev
  from v_events e join rounds r on r.round_id = e.lead_round_id
  where e.event_type = 'sale' and e.lead_round_id is not null
  group by 1, 2
)
select
  m.client_id,
  to_char(m.month_start, 'YYYY-MM')  as cut_key,
  to_char(m.month_start, 'Mon YYYY') as cut_label,
  m.round_count || ' round' || case when m.round_count = 1 then '' else 's' end as cut_sub,
  m.month_start,
  fo_paid_returns(
    fo_metrics(
      coalesce(ads.ad_rows, 0) > 0,
      ads.spend, ads.reach::bigint, ads.impressions, ads.clicks,
      case when exists (select 1 from v_leads_seen z where z.client_id = m.client_id)
           then coalesce(ev.leads, 0) end,
      case when exists (select 1 from v_attendance_seen z where z.client_id = m.client_id)
           then coalesce(ev.attendance, 0) end,
      case when s.client_id is not null then coalesce(sales.prev_buy, 0) end,
      case when s.client_id is not null then coalesce(sales.mid_buy,  0) end,
      case when s.client_id is not null then coalesce(sales.prev_rev, 0) end,
      case when s.client_id is not null then coalesce(sales.mid_rev,  0) end,
      p.preview_price, p.middle_price
    ),
    case when s.client_id is not null then coalesce(sales.paid_prev_buy, 0) end,
    case when s.client_id is not null then coalesce(sales.paid_prev_rev, 0) end,
    case when s.client_id is not null then coalesce(sales.paid_mid_rev,  0) end
  ) as m
from months m
left join ads   on ads.client_id   = m.client_id and ads.month_start   = m.month_start
left join ev    on ev.client_id    = m.client_id and ev.month_start    = m.month_start
left join sales on sales.client_id = m.client_id and sales.month_start = m.month_start
left join v_sales_seen s    on s.client_id = m.client_id
left join v_client_prices p on p.client_id = m.client_id
order by m.client_id, m.month_start;

grant select on v_metrics_by_month to anon, authenticated;


create or replace view v_metrics_by_session as
with labels as (
  select client_id, coalesce(nullif(btrim(session_label), ''), '(unlabelled)') as label,
         count(*)::int as round_count, min(start_date) as first_start
  from rounds group by 1, 2
),
ads as (
  select r.client_id, coalesce(nullif(btrim(r.session_label), ''), '(unlabelled)') as label,
         sum(a.spend) as spend,
         coalesce(sum(a.reach) filter (where nullif(btrim(a.ad_set), '') is null),
                  sum(a.reach)) as reach,
         sum(a.impressions) as impressions, sum(a.clicks) as clicks, count(*) as ad_rows
  from v_ads a join rounds r on r.round_id = a.round_id group by 1, 2
),
ev as (
  select r.client_id, coalesce(nullif(btrim(r.session_label), ''), '(unlabelled)') as label,
         count(*) filter (where e.event_type = 'lead')       as leads,
         count(*) filter (where e.event_type = 'attendance') as attendance
  from v_events e join rounds r on r.round_id = e.round_id group by 1, 2
),
sales as (
  select r.client_id, coalesce(nullif(btrim(r.session_label), ''), '(unlabelled)') as label,
         count(*) filter (where e.product = 'preview') as prev_buy,
         count(*) filter (where e.product = 'middle')  as mid_buy,
         sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.product = 'preview') as prev_rev,
         sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.product = 'middle')  as mid_rev,
         -- the ad-produced slice, for ROAS and CPA (0020)
         count(*) filter (where e.product = 'preview' and e.attribution_bucket in ('Paid Ads', 'Previous Paid Ads')) as paid_prev_buy,
         sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.product = 'preview' and e.attribution_bucket in ('Paid Ads', 'Previous Paid Ads')) as paid_prev_rev,
         sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.product = 'middle'  and e.attribution_bucket in ('Paid Ads', 'Previous Paid Ads')) as paid_mid_rev
  from v_events e join rounds r on r.round_id = e.lead_round_id
  where e.event_type = 'sale' and e.lead_round_id is not null
  group by 1, 2
)
select
  l.client_id,
  l.label as cut_key,
  l.label as cut_label,
  l.round_count || ' round' || case when l.round_count = 1 then '' else 's' end as cut_sub,
  fo_paid_returns(
    fo_metrics(
      coalesce(ads.ad_rows, 0) > 0,
      ads.spend, ads.reach::bigint, ads.impressions, ads.clicks,
      case when exists (select 1 from v_leads_seen z where z.client_id = l.client_id)
           then coalesce(ev.leads, 0) end,
      case when exists (select 1 from v_attendance_seen z where z.client_id = l.client_id)
           then coalesce(ev.attendance, 0) end,
      case when s.client_id is not null then coalesce(sales.prev_buy, 0) end,
      case when s.client_id is not null then coalesce(sales.mid_buy,  0) end,
      case when s.client_id is not null then coalesce(sales.prev_rev, 0) end,
      case when s.client_id is not null then coalesce(sales.mid_rev,  0) end,
      p.preview_price, p.middle_price
    ),
    case when s.client_id is not null then coalesce(sales.paid_prev_buy, 0) end,
    case when s.client_id is not null then coalesce(sales.paid_prev_rev, 0) end,
    case when s.client_id is not null then coalesce(sales.paid_mid_rev,  0) end
  ) as m,
  row_number() over (partition by l.client_id order by l.first_start, l.label)::int as ord
from labels l
left join ads   on ads.client_id   = l.client_id and ads.label   = l.label
left join ev    on ev.client_id    = l.client_id and ev.label    = l.label
left join sales on sales.client_id = l.client_id and sales.label = l.label
left join v_sales_seen s    on s.client_id = l.client_id
left join v_client_prices p on p.client_id = l.client_id
order by 1, ord;

grant select on v_metrics_by_session to anon, authenticated;


create or replace view v_metrics_total as
with ads as (
  select client_id, sum(spend) as spend,
         coalesce(sum(reach) filter (where nullif(btrim(ad_set), '') is null),
                  sum(reach)) as reach,
         sum(impressions) as impressions, sum(clicks) as clicks, count(*) as ad_rows
  from v_ads group by client_id
),
ev as (
  select client_id,
         count(*) filter (where event_type = 'lead')       as leads,
         count(*) filter (where event_type = 'attendance') as attendance,
         count(*) filter (where event_type = 'sale' and product = 'preview') as prev_buy,
         count(*) filter (where event_type = 'sale' and product = 'middle')  as mid_buy,
         sum(amount - coalesce(refund_amount, 0)) filter (where event_type = 'sale' and product = 'preview') as prev_rev,
         sum(amount - coalesce(refund_amount, 0)) filter (where event_type = 'sale' and product = 'middle')  as mid_rev,
         -- the ad-produced slice, for ROAS and CPA (0020)
         count(*) filter (where event_type = 'sale' and product = 'preview' and attribution_bucket in ('Paid Ads', 'Previous Paid Ads')) as paid_prev_buy,
         sum(amount - coalesce(refund_amount, 0)) filter (where event_type = 'sale' and product = 'preview' and attribution_bucket in ('Paid Ads', 'Previous Paid Ads')) as paid_prev_rev,
         sum(amount - coalesce(refund_amount, 0)) filter (where event_type = 'sale' and product = 'middle'  and attribution_bucket in ('Paid Ads', 'Previous Paid Ads')) as paid_mid_rev
  from v_events group by client_id
)
select
  c.client_id,
  'TOTAL'::text as cut_key,
  'Total'::text as cut_label,
  'all rounds'::text as cut_sub,
  fo_paid_returns(
    fo_metrics(
      coalesce(ads.ad_rows, 0) > 0,
      ads.spend, ads.reach::bigint, ads.impressions, ads.clicks,
      case when exists (select 1 from v_leads_seen z where z.client_id = c.client_id)
           then coalesce(ev.leads, 0) end,
      case when exists (select 1 from v_attendance_seen z where z.client_id = c.client_id)
           then coalesce(ev.attendance, 0) end,
      case when s.client_id is not null then coalesce(ev.prev_buy, 0) end,
      case when s.client_id is not null then coalesce(ev.mid_buy,  0) end,
      case when s.client_id is not null then coalesce(ev.prev_rev, 0) end,
      case when s.client_id is not null then coalesce(ev.mid_rev,  0) end,
      p.preview_price, p.middle_price
    ),
    case when s.client_id is not null then coalesce(ev.paid_prev_buy, 0) end,
    case when s.client_id is not null then coalesce(ev.paid_prev_rev, 0) end,
    case when s.client_id is not null then coalesce(ev.paid_mid_rev,  0) end
  ) as m
from v_clients c
left join ads on ads.client_id = c.client_id
left join ev  on ev.client_id  = c.client_id
left join v_sales_seen s on s.client_id = c.client_id
left join v_client_prices p on p.client_id = c.client_id;

grant select on v_metrics_total to anon, authenticated;


create or replace view v_metrics_by_offer as
with offers as (select unnest(array['preview', 'middle']) as product),
ads as (
  select client_id, round_id, sum(spend) as spend,
         -- 0016's rule, which this view never got: read reach off the coarsest
         -- row rather than adding the tiers, or a round claims 33,337 people
         -- when 12,672 saw it and Frequency drops below 1.
         coalesce(sum(reach) filter (where nullif(btrim(ad_set), '') is null),
                  sum(reach)) as reach,
         sum(impressions) as impressions, sum(clicks) as clicks, count(*) as ad_rows
  from v_ads group by 1, 2
),
ev as (
  select client_id, round_id,
         count(*) filter (where event_type = 'lead')       as leads,
         count(*) filter (where event_type = 'attendance') as attendance
  from v_events group by 1, 2
),
sales as (
  select client_id, lead_round_id as round_id, product,
         count(*) as buys,
         sum(amount - coalesce(refund_amount, 0)) as rev,
         -- the ad-produced slice, for ROAS and CPA (0020)
         count(*) filter (where attribution_bucket in ('Paid Ads', 'Previous Paid Ads')) as paid_buys,
         sum(amount - coalesce(refund_amount, 0)) filter (where attribution_bucket in ('Paid Ads', 'Previous Paid Ads')) as paid_rev
  from v_events
  where event_type = 'sale' and lead_round_id is not null and product is not null
  group by 1, 2, 3
)
select
  r.client_id,
  o.product,
  r.round_id                                  as cut_key,
  r.round_id                                  as cut_label,
  to_char(r.start_date, 'Mon DD') || ' – ' || to_char(r.end_date, 'DD') as cut_sub,
  r.start_date,
  fo_paid_returns(
    fo_metrics(
      coalesce(ads.ad_rows, 0) > 0,
      ads.spend, ads.reach, ads.impressions, ads.clicks,
      case when exists (select 1 from v_leads_seen z where z.client_id = r.client_id)
           then coalesce(ev.leads, 0) end,
      case when exists (select 1 from v_attendance_seen z where z.client_id = r.client_id)
           then coalesce(ev.attendance, 0) end,
      -- only this tab's offer carries numbers; the other is absent, not zero
      case when o.product = 'preview' and s.client_id is not null then coalesce(sp.buys, 0) end,
      case when o.product = 'middle'  and s.client_id is not null then coalesce(sm.buys, 0) end,
      case when o.product = 'preview' and s.client_id is not null then coalesce(sp.rev,  0) end,
      case when o.product = 'middle'  and s.client_id is not null then coalesce(sm.rev,  0) end,
      p.preview_price, p.middle_price
    ),
    case when o.product = 'preview' and s.client_id is not null then coalesce(sp.paid_buys, 0) end,
    case when o.product = 'preview' and s.client_id is not null then coalesce(sp.paid_rev,  0) end,
    case when o.product = 'middle'  and s.client_id is not null then coalesce(sm.paid_rev,  0) end
  ) as m
from rounds r
cross join offers o
left join ads on ads.client_id = r.client_id and ads.round_id = r.round_id
left join ev  on ev.client_id  = r.client_id and ev.round_id  = r.round_id
left join sales sp on sp.client_id = r.client_id and sp.round_id = r.round_id and sp.product = 'preview'
left join sales sm on sm.client_id = r.client_id and sm.round_id = r.round_id and sm.product = 'middle'
left join v_sales_seen s    on s.client_id = r.client_id
left join v_client_prices p on p.client_id = r.client_id
order by r.client_id, o.product, r.start_date;

grant select on v_metrics_by_offer to anon, authenticated;

-- ══════════════════════════════════════════════════════════════════════════
-- 0021_untracked_ads_get_one_column.sql
-- ══════════════════════════════════════════════════════════════════════════

-- ═══════════════════════════════════════════════════════════════════════════
-- 0021 — one column for the untracked ads, instead of twelve.
--
-- Twelve ads carry an ID instead of a name, because a second tracking template
-- writes {{ad.id}} where the others write {{ad.name}}. Each got its own column
-- on the Ads tab: twelve columns of dashes holding 16 leads between them, and
-- the six creatives that actually spent money were pushed off the right edge.
--
-- They are collapsed into one bucket, not deleted. Every one of those 16 leads
-- is a real person, and the tab already reads short of Total because community
-- leads have no creative — quietly dropping 16 more would widen that gap with
-- nothing on screen to explain it. There is also a finding in them: 16 leads,
-- zero attendance, zero revenue. Ads nobody can name produced nobody who came.
--
-- The bucket is keyed on the ID pattern, so an ad splits back out on its own
-- the moment Meta exports one answering to that ID. cut_sub counts them, so
-- "12 ads, no name in the export" stays true without anyone maintaining it.
--
-- Delivery and spend are blanked here for the same reason as Unsplit spend: no
-- export names these ads, so there is no spend to attribute and no reach to
-- claim. Sorting puts the bucket after the named creatives and before Unsplit.
-- ═══════════════════════════════════════════════════════════════════════════

create or replace view v_metrics_by_ad as
with ads as (
  select client_id, nullif(btrim(ad), '') as ad,
         sum(spend) as spend, sum(reach) as reach,
         sum(impressions) as impressions, sum(clicks) as clicks,
         count(*) as ad_rows
  from v_ads group by client_id, nullif(btrim(ad), '')
),
-- the creative that ACQUIRED each person: their earliest lead carrying one
lead_ad as (
  select distinct on (client_id, contact_id)
         client_id, contact_id,
         coalesce(nullif(btrim(ad), ''),
                  case when source = 'Paid Ads' then '(unsplit)' end) as ad
  from v_events
  where event_type = 'lead' and contact_id is not null
    and (nullif(btrim(ad), '') is not null or source = 'Paid Ads')
  order by client_id, contact_id, event_date
),
-- a lead counts on its OWN creative; only later events need the detour
ev_leads as (
  select client_id,
         coalesce(nullif(btrim(ad), ''),
                  case when source = 'Paid Ads' then '(unsplit)' end) as ad,
         count(*) as leads
  from v_events
  where event_type = 'lead'
    and (nullif(btrim(ad), '') is not null or source = 'Paid Ads')
  group by 1, 2
),
ev_after as (
  select la.client_id, la.ad,
    count(*) filter (where e.event_type = 'attendance') as attendance,
    count(*) filter (where e.event_type = 'sale' and e.product = 'preview') as prev_buy,
    count(*) filter (where e.event_type = 'sale' and e.product = 'middle')  as mid_buy,
    sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.event_type = 'sale' and e.product = 'preview') as prev_rev,
    sum(e.amount - coalesce(e.refund_amount, 0)) filter (where e.event_type = 'sale' and e.product = 'middle')  as mid_rev
  from v_events e
  join lead_ad la on la.client_id = e.client_id and la.contact_id = e.contact_id
  where e.event_type <> 'lead'
  group by la.client_id, la.ad
),
ev as (
  select coalesce(l.client_id, a.client_id) as client_id,
         coalesce(l.ad, a.ad)               as ad,
         l.leads, a.attendance, a.prev_buy, a.mid_buy, a.prev_rev, a.mid_rev
  from ev_leads l
  full join ev_after a on a.client_id = l.client_id and a.ad = l.ad
),
cut as (
  select coalesce(ads.client_id, ev.client_id) as client_id,
         case when ads.ad is null and ev.ad is null then '(unsplit)'
              else coalesce(ads.ad, ev.ad) end as ad,
         ads.spend, ads.reach, ads.impressions, ads.clicks, ads.ad_rows,
         ev.leads, ev.attendance, ev.prev_buy, ev.mid_buy, ev.prev_rev, ev.mid_rev
  from ads full join ev on ev.client_id = ads.client_id and ev.ad = ads.ad
),
rolled as (
  select client_id,
         -- twelve columns of dashes, one per untracked ad, pushed the six real
         -- creatives off the right edge. They are collapsed into one bucket and
         -- split back out on their own the moment Meta exports an ad answering
         -- to one of those IDs — nothing is thrown away to make room.
         case when ad ~ '^[0-9]+$' then '(ad ids)' else ad end as ad,
         count(distinct ad) filter (where ad ~ '^[0-9]+$')::int as id_count,
         sum(spend)::numeric as spend, sum(reach)::bigint as reach,
         sum(impressions)::bigint as impressions, sum(clicks)::bigint as clicks,
         sum(ad_rows)::bigint as ad_rows, sum(leads)::bigint as leads,
         sum(attendance)::bigint as attendance, sum(prev_buy)::bigint as prev_buy,
         sum(mid_buy)::bigint as mid_buy, sum(prev_rev)::numeric as prev_rev,
         sum(mid_rev)::numeric as mid_rev
  from cut group by client_id, case when ad ~ '^[0-9]+$' then '(ad ids)' else ad end
)
select
  r.client_id,
  r.ad                                                        as cut_key,
  case when r.ad = '(unsplit)' then 'Unsplit spend'
       when r.ad = '(ad ids)'  then 'Ad ID only'
       else r.ad end                                            as cut_label,
  case when r.ad = '(unsplit)' then 'paid, no ad recorded'
       when r.ad = '(ad ids)'  then r.id_count || ' ads, no name in the export' end as cut_sub,
  fo_metrics(
    coalesce(r.ad_rows, 0) > 0,
    -- the one change: 0.00 in this bucket means "not recorded", not "free"
    case when r.ad in ('(unsplit)', '(ad ids)') then nullif(r.spend, 0) else r.spend end,
    -- same rule as 0013: delivery has no subject in the unattributable bucket
    case when r.ad not in ('(unsplit)', '(ad ids)') then r.reach       end,
    case when r.ad not in ('(unsplit)', '(ad ids)') then r.impressions end,
    case when r.ad not in ('(unsplit)', '(ad ids)') then r.clicks      end,
    case when exists (select 1 from v_leads_seen z where z.client_id = r.client_id)
         then coalesce(r.leads, 0) end,
    case when exists (select 1 from v_attendance_seen z where z.client_id = r.client_id)
         then coalesce(r.attendance, 0) end,
    case when s.client_id is not null then coalesce(r.prev_buy, 0) end,
    case when s.client_id is not null then coalesce(r.mid_buy,  0) end,
    case when s.client_id is not null then coalesce(r.prev_rev, 0) end,
    case when s.client_id is not null then coalesce(r.mid_rev,  0) end,
    p.preview_price, p.middle_price
  ) as m,
  row_number() over (
    partition by r.client_id
    order by case when r.ad = '(unsplit)' then 2 when r.ad = '(ad ids)' then 1 else 0 end,
             coalesce(r.leads, 0) desc, coalesce(r.spend, 0) desc, r.ad
  )::int as ord
from rolled r
left join v_sales_seen s on s.client_id = r.client_id
left join v_client_prices p on p.client_id = r.client_id
order by 1, ord;

grant select on v_metrics_by_ad to anon, authenticated;

-- ══════════════════════════════════════════════════════════════════════════
-- 0022_products_and_channels.sql
-- ══════════════════════════════════════════════════════════════════════════

-- ═══════════════════════════════════════════════════════════════════════════
-- 0022 — a client sells more than one thing, and buys traffic in more than
-- one place.
--
-- Both dimensions are missing entirely today. Every round belongs to a client
-- and nothing narrower, and every ads row is assumed to be Meta because Meta is
-- the only export anyone has sent. Neither assumption survives a second client.
--
-- This migration adds the two columns and backfills what is already known. It
-- deliberately changes NO metric: every view still reads the same rows, so
-- spend stays 2,447.26, leads stay 313, attendance stays 40 and revenue stays
-- 5,067.00. Wiring the filters is the next step; this one only makes the
-- dimensions exist.
--
-- ── PRODUCT hangs off the round ────────────────────────────────────────────
-- Rounds are the spine: ads point at a round, events point at a round, and both
-- offers are sold inside one. Putting the product on the round means every
-- other table inherits it for free and no existing join changes.
--
-- ── CHANNEL is not SOURCE, and the difference matters ──────────────────────
-- The app already has `source`: Paid Ads, AOAI, AI Community, Organic. That is
-- WHERE THE PERSON CAME FROM. Channel is WHERE THE MONEY WAS SPENT — Meta,
-- Google, TikTok. They are independent: a Paid Ads lead can arrive from either
-- platform, and one platform can produce both paid and organic leads.
--
-- Because the two are easy to confuse, the leads importer's alias list is
-- corrected in the same change: a column headed "channel" in a GoHighLevel
-- export used to be read as the lead's SOURCE. From here it is not read at all
-- rather than read as the wrong thing. Shely's remembered mapping uses
-- `source → source`, so nothing re-maps.
-- ═══════════════════════════════════════════════════════════════════════════

-- ── PRODUCTS ───────────────────────────────────────────────────────────────
-- One client, many products. `ord` fixes the column order in the filter so a
-- product doesn't move sideways between page loads as rows land.
create table if not exists products (
  product_id   text primary key,
  client_id    text not null,
  product_name text not null,
  product_note text,
  ord          int  not null default 1
);

create index if not exists idx_products_client on products (client_id);

alter table products enable row level security;
drop policy if exists "demo read" on products;
create policy "demo read" on products for select using (true);
grant select on products to anon, authenticated;

-- Shely sells one thing today: the webinar that leads to the two offers. Named
-- for what it is rather than "Product 1", so a second one has to be named too.
insert into products (product_id, client_id, product_name, product_note, ord)
values ('shely-webinar', 'shely', 'Webinar → offer',
        'Live class, SGD 297 preview offer, 1,197 middle offer', 1)
on conflict (product_id) do nothing;

-- ── ROUNDS GAIN A PRODUCT ──────────────────────────────────────────────────
alter table rounds add column if not exists product_id text references products(product_id);
create index if not exists idx_rounds_product on rounds (product_id);

update rounds set product_id = 'shely-webinar'
where client_id = 'shely' and product_id is null;

-- ── ADS GAIN A CHANNEL ─────────────────────────────────────────────────────
-- No database default. A default would silently stamp 'meta' on a Google export
-- the day one arrives, which is exactly the kind of quiet wrongness the rest of
-- this app refuses. The importer decides, and says which channel it used.
alter table ads_performance add column if not exists channel text;
create index if not exists idx_ads_channel on ads_performance (channel);

-- Every existing row came out of a Meta export — that is evidenced by the
-- column map on the committed batch, not assumed.
update ads_performance set channel = 'meta' where channel is null;

-- ── CHANNEL REFERENCE ──────────────────────────────────────────────────────
-- Fixed order, same reasoning as v_source_buckets in 0006: a column that
-- appears and disappears as rows land would shove the others sideways.
create or replace view v_channels as
select * from (values
  ('meta',   1, 'Facebook and Instagram'),
  ('google', 2, 'Search, Display and YouTube'),
  ('tiktok', 3, 'TikTok'),
  ('other',  9, 'Anything else')
) as t(channel, ord, note);

grant select on v_channels to anon, authenticated;

-- ── WHAT THE APP READS ─────────────────────────────────────────────────────
-- Products a client actually has, with the round count behind each so the
-- filter can grey out one that has nothing in it yet.
create or replace view v_products as
select
  p.product_id,
  p.client_id,
  p.product_name,
  p.product_note,
  p.ord,
  count(r.round_id)::int as round_count
from products p
left join rounds r on r.product_id = p.product_id
group by p.product_id, p.client_id, p.product_name, p.product_note, p.ord
order by p.client_id, p.ord, p.product_name;

grant select on v_products to anon, authenticated;

-- Channels a client actually has spend in. Same rule: a channel with no rows
-- gets no entry, rather than a column of zeroes that were never measured.
create or replace view v_client_channels as
select
  r.client_id,
  coalesce(a.channel, 'other')     as channel,
  coalesce(c.ord, 9)               as ord,
  c.note,
  count(*)::int                    as ad_rows,
  sum(a.spend)::numeric            as spend
from ads_performance a
join rounds r     on r.round_id = a.round_id
left join v_channels c on c.channel = a.channel
group by r.client_id, coalesce(a.channel, 'other'), coalesce(c.ord, 9), c.note
order by r.client_id, coalesce(c.ord, 9);

grant select on v_client_channels to anon, authenticated;
